def _proc_alive(pid):
    try:
        pid = int(pid)
        if pid <= 0:
            return False
        if os.name == "nt":
            import ctypes
            h = ctypes.windll.kernel32.OpenProcess(0x1000, 0, pid)
            if h:
                ctypes.windll.kernel32.CloseHandle(h)
            return bool(h)
        os.kill(pid, 0)
        return True
    except PermissionError:
        return True
    except (OSError, ValueError, TypeError, AttributeError):
        return False

def _proc_is_brain_daemon(pid):
    """Only where the process can be inspected (Linux): is this pid `brain daemon run`? Guards against a reused pid."""
    try:
        with open("/proc/%d/cmdline" % int(pid), "rb") as f:
            cmd = f.read()
        return b"daemon" in cmd and b"run" in cmd
    except (OSError, ValueError):
        return False

def _kill_pid(pid):
    import signal
    for sig, wait in ((signal.SIGTERM, 2.0), (getattr(signal, "SIGKILL", signal.SIGTERM), 1.0)):
        try:
            os.kill(int(pid), sig)
        except (OSError, ValueError):
            return True
        end = time.time() + wait
        while time.time() < end:
            if not _proc_alive(pid):
                return True
            time.sleep(0.05)
    return not _proc_alive(pid)

