def _migrate_legacy(root, team, tenant, cfg):
    """Old layout (one replica in ROOT shared by every key and team): when the legacy copy is this key's team, stop
    the legacy daemon and move its team files into the team dir, so nothing is downloaded again. A legacy copy of
    another team is left alone. Legacy outbox lines (no key id) stay in ROOT: only `brain outbox --push` sends them."""
    legacy = ("replica.db", "replica.key", "team.id", "braind.sock", "braind.port", "braind.pid")
    if (root / "outbox.jsonl").exists() and not (root / "outbox.team").exists():
        try:
            if (root / "team.id").read_text().strip() == tenant:
                _write_private(root / "outbox.team", tenant)  # which team the old unkeyed outbox lines belong to
        except OSError:
            pass
    if not any((root / f).exists() for f in legacy) or (team / "replica.db").exists():
        return
    lock = _FileLock(root / "migrate.lock", stale=30)
    if not lock.acquire(10.0):
        return
    try:
        if (team / "replica.db").exists():
            return
        try:
            lt = (root / "team.id").read_text().strip()
        except OSError:
            lt = ""
        alive = _sock_call(root, {"op": "ping"}, 0.2, 2.0)
        if not lt and alive is not None:
            # no team.id: a legacy daemon that accepts this very key was started by it, so it is this key's team
            h = _sock_call(root, {"op": "hyper", "cfg": cfg_id(cfg)}, 0.2, 5.0)
            if isinstance(h, dict) and h.get("ok") and not h.get("cfg_mismatch"):
                lt = tenant
        if lt != tenant:
            return
        if alive is not None:
            _sock_call(root, {"op": "stop"}, 0.2, 5.0)
            end = time.time() + 6
            while time.time() < end and _sock_call(root, {"op": "ping"}, 0.1, 1.0) is not None:
                time.sleep(0.1)
        pid = _read_pid(root)
        if pid and _proc_alive(pid) and _proc_is_brain_daemon(pid):
            _kill_pid(pid)
        _private_dir(team)
        for name in ("replica.db", "replica.db-wal", "replica.db-shm", "replica.db-journal", "replica.key", "lease.json",
                     "swr-cache.enc", "spaces.count", "engine.mismatch", "team.id", "recent-results.json", "braind.log"):
            src = root / name
            if src.exists():
                try:
                    os.replace(str(src), str(team / name))
                except OSError:
                    pass
        if (root / "embed" / "state").exists():  # the old model home also held this team's vectors: they move, the install stays
            try:
                _private_dir(team / "embed-state")
                os.replace(str(root / "embed" / "state"), str(team / "embed-state" / "state"))
            except OSError:
                pass
        for f in ("braind.sock", "braind.port", "braind.pid", "braind.spawn"):
            _unlink_quiet(root / f)
        if (root / "outbox.jsonl").exists():
            _write_private(root / "outbox.team", tenant)  # which team the old unkeyed outbox lines belong to
    finally:
        lock.release()

def _merge_unbound(root, team, cid):
    """Lines written for this key while its team was not yet known join the team outbox (each carries its key id)."""
    ub = root / "unbound" / cid
    src = ub / "outbox.jsonl"
    if not src.exists():
        return
    lines = _outbox_read(src)
    lock = _FileLock(team / "outbox.lock")
    lock.acquire(2.0)
    try:
        if lines:
            fd = os.open(str(team / "outbox.jsonl"), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
            with os.fdopen(fd, "a") as f:
                f.write("".join(l + "\n" for l in lines))
        _unlink_quiet(src)
    finally:
        lock.release()
    try:
        ub.rmdir()
    except OSError:
        pass

def activate(cfg, net=True):
    """Bind this process to the data dir of the team this key belongs to, as the HOST said (never a team name the
    caller supplies). Unknown team and the host not answering: bind to a holding dir for this key alone, so nothing
    of another team is read or written and the host/offline path runs. Idempotent per key. Returns True when bound."""
    cid = cfg_id(cfg)
    if _BIND["off"] or (_BIND["cid"] == cid and _BIND["done"]):
        return _BIND["bound"]
    root = cache_dir()
    tenant = td = None
    ent = keys_lookup(cfg) if cfg.get("url") and cfg.get("key") else None
    if ent:
        tenant, td = ent[0], ent[1]
    if cfg.get("url") and cfg.get("key") and (not ent or time.time() - ent[2] >= KEYS_FRESH_S) and net:
        kind, a, b = host_verify(cfg, timeout=5)
        if kind == "ok":
            tenant, td = a, keys_record(cfg, a)
        elif kind == "refused":
            if ent:
                bind_dir(root / "teams" / td)
                _BIND.update(cid=cid, tenant=tenant, team=td, bound=True, done=True)
                key_refused(cfg, a, b)
            keys_forget(cid)
            tenant = td = None
    _BIND.update(cid=cid, tenant=tenant, team=td, bound=bool(td), done=True)
    if td:
        team = root / "teams" / td
        _private_dir(root)
        _private_dir(root / "teams")
        _private_dir(team)
        bind_dir(team)
        _migrate_legacy(root, team, tenant, cfg)
        _merge_unbound(root, team, cid)
    else:
        _private_dir(root)
        bind_dir(root / "unbound" / (cid if cfg.get("key") else "none"))
    return bool(td)

def key_refused(cfg, st, res, renew=None):
    """The host answered 401/403 for this key. Only this key is dropped: the team's local copy, lease and offline cache
    are wiped when the team itself is inactive (403, not a key-bound refusal) or this was the last known key of the team."""
    if st == 403 and is_key_bound_error(res):
        return
    cid = cfg_id(cfg)
    if st == 401:
        keys_forget(cid)
        if _BIND["team"] and keys_of_team(_BIND["team"]) - {cid}:
            return
    if _BIND["bound"]:
        expire_lease(st == 401)
        wipe_local(revoked=(st == 401), renew_url=renew or (res.get("renew_url") if isinstance(res, dict) else None))

