class _ConnSlot(object):
    """The reused HTTPSConnection (HTTP/1.1 keep-alive), one per thread: the daemon calls the host from several threads."""
    def __init__(self):
        import threading
        self._l = threading.local()

    def __getitem__(self, k):
        return getattr(self._l, k, None)

    def __setitem__(self, k, v):
        setattr(self._l, k, v)

