# Local-copy cipher: standard AES-256-GCM from the `cryptography` package, random 12-byte nonce, AAD on every entry.
# There is no homemade fallback. Without the package the offline cache and the local replica are simply not used
# (lookups go to the host and Hyper speed reports why). Keys are derived from the lease key (cache) or the replica
# key, both stored on this same machine, so this is light protection: secure the machine and its user account.
try:
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM as _AESGCM
except Exception:  # package missing or unusable
    _AESGCM = None
NO_AES_MSG = "the local copy needs the cryptography package for AES-256-GCM: run python3 -m pip install cryptography (Apple's Python may need it before Hyper speed can turn on)"
_CACHE_V = b"v3"       # AES-256-GCM
_CACHE_V_OLD = b"v2"   # HMAC keystream: read once so entries can be rewritten as v3, never written
_CACHE_AAD = b"brain-cache|v3"

def _need_aes():
    if _AESGCM is None:
        raise RuntimeError(NO_AES_MSG)

def _cache_aes_key(lease_key: str) -> bytes:
    return hmac.new(lease_key.encode(), b"brain-cache-aes-256-gcm", hashlib.sha256).digest()

def _cache_keys(lease_key: str):  # old v2 format, read only
    k = lease_key.encode()
    return (hmac.new(k, b"brain-cache-enc", hashlib.sha256).digest(),
            hmac.new(k, b"brain-cache-mac", hashlib.sha256).digest())

def _keystream_xor(key: bytes, nonce: bytes, data: bytes) -> bytes:  # old v2 format, read only
    out = bytearray()
    for ctr in range((len(data) + 31) // 32):
        out += hmac.new(key, nonce + ctr.to_bytes(8, "big"), hashlib.sha256).digest()
    return bytes(a ^ b for a, b in zip(data, out))

def cache_is_legacy(blob: bytes) -> bool:
    return blob[:2] == _CACHE_V_OLD

def cache_seal(data: bytes, lease_key: str) -> bytes:
    """Always the new format. Raises RuntimeError without the cryptography package."""
    _need_aes()
    if not lease_key:
        raise ValueError("no lease key")
    nonce = secrets.token_bytes(12)
    return _CACHE_V + nonce + _AESGCM(_cache_aes_key(lease_key)).encrypt(nonce, data, _CACHE_AAD)

def cache_open(blob: bytes, lease_key: str) -> bytes:
    """Raises ValueError on an unreadable entry, wrong lease key, or any tampering; RuntimeError without cryptography."""
    _need_aes()
    if not lease_key or len(blob) < 2 + 12 + 16:
        raise ValueError("unreadable cache entry")
    if blob[:2] == _CACHE_V_OLD:
        ek, mk = _cache_keys(lease_key)
        head, tag = blob[:-32], blob[-32:]
        if len(blob) < 2 + 16 + 32 or not hmac.compare_digest(tag, hmac.new(mk, head, hashlib.sha256).digest()):
            raise ValueError("cache entry failed authentication")
        return _keystream_xor(ek, head[2:18], head[18:])
    if blob[:2] != _CACHE_V:
        raise ValueError("unreadable cache entry")
    try:
        return _AESGCM(_cache_aes_key(lease_key)).decrypt(blob[2:14], blob[14:], _CACHE_AAD)
    except Exception:
        raise ValueError("cache entry failed authentication")

def save_lease(lease_b64: str):
    ensure()
    old = load_lease()
    import base64
    try:
        raw = json.loads(base64.b64decode(lease_b64).decode())
    except Exception as e:
        raise RuntimeError(f"bad lease: {e}")
    # payload: v1|tenant|bot|expires_at
    parts = raw.get("payload", "").split("|")
    exp = parts[3] if len(parts) >= 4 else ""
    new_key = raw.get("lease_key")
    # Each lease has its own key: move readable cache entries to the new key so earlier lookups stay usable offline.
    if old and old.get("lease_key") and new_key and old["lease_key"] != new_key and lease_valid(old):
        _rekey_cache(old["lease_key"], new_key)
    _write_private(LEASE_FILE, json.dumps({
        "lease": lease_b64,
        "lease_key": new_key,
        "expires_at": exp,
        "renew_url": raw.get("renew_url") or renew_default(),
        "sig": raw.get("sig"),
        "payload": raw.get("payload"),
    }, indent=2))

def _rekey_cache(old_key: str, new_key: str):
    if not ENC_SWR.exists():
        return
    import base64
    try:
        store = json.loads(ENC_SWR.read_text())
    except Exception:
        return
    out = {}
    for slot, raw in store.items():
        try:
            out[slot] = base64.b64encode(cache_seal(cache_open(base64.b64decode(raw), old_key), new_key)).decode()
        except Exception:
            pass  # unreadable entries are dropped
    _write_private(ENC_SWR, json.dumps(out))

def load_lease():
    ensure()
    try:
        return json.loads(LEASE_FILE.read_text())
    except Exception:
        return None

def lease_valid(le=None):
    le = le or load_lease()
    if not le or not le.get("lease_key") or not le.get("expires_at"):
        return False
    try:
        import datetime as _dt
        exp = _dt.datetime.fromisoformat(le["expires_at"].replace("Z", "+00:00")).timestamp()
        return exp > time.time()
    except Exception:
        return False

def license_inactive_msg(le=None):
    le = le or load_lease() or {}
    if le.get("revoked"):
        return REVOKED_MSG
    url = le.get("renew_url") or renew_default()
    return f"license inactive, renew at {url}"

def _swr_slot(key):
    return hashlib.sha256(key.encode()).hexdigest()

def swr_put_encrypted(key, text, lease_key):
    """Write an authenticated, encrypted SWR entry keyed from the lease (light protection; see cache_seal)."""
    ensure()
    # never persist query text as a map key
    blob = json.dumps({"t": time.time(), "text": text}).encode()
    try:
        enc = cache_seal(blob, lease_key)
    except RuntimeError:
        _unlink_quiet(ENC_SWR)  # no AES-256-GCM here: no offline cache, and no old-format copy left behind
        return
    store = {}
    if ENC_SWR.exists():
        try:
            store = json.loads(ENC_SWR.read_text())
        except Exception:
            store = {}
    import base64
    store[_swr_slot(key)] = base64.b64encode(enc).decode()
    if len(store) > 200:  # keep the newest 200 lookups
        store = dict(list(store.items())[-200:])
    _write_private(ENC_SWR, json.dumps(store))

def swr_get_encrypted(key, lease_key):
    if not ENC_SWR.exists():
        return None
    import base64
    try:
        store = json.loads(ENC_SWR.read_text())
        raw = store.get(_swr_slot(key))
        if not raw:
            return None
        old = base64.b64decode(raw)
        blob = cache_open(old, lease_key)
        obj = json.loads(blob.decode())
        if cache_is_legacy(old):  # read once, then rewrite in the new format
            try:
                store[_swr_slot(key)] = base64.b64encode(cache_seal(blob, lease_key)).decode()
                _write_private(ENC_SWR, json.dumps(store))
            except Exception:
                pass
        return obj
    except Exception:
        return None  # cannot decrypt without the lease key, no plaintext fallback


def _swr_load():
    ensure()
    try:
        return json.loads(SWR.read_text())
    except Exception:
        return {}

def _swr_save(d):
    ensure()
    SWR.write_text(json.dumps(d))

def _swr_key(q, n, bot):
    return f"{n}|{bot or ''}|{q.strip().lower()}"

def api(method, path, cfg, body=None, timeout=30):
    """HTTPS with connection reuse (keep-alive). Falls back to urllib on error."""
    import http.client
    from urllib.parse import urlparse
    u = urlparse(cfg["url"])
    host = u.hostname
    port = u.port or (80 if u.scheme == "http" else 443)
    data = None if body is None else json.dumps(body).encode()
    headers = {
        "Authorization": "Bearer " + cfg["key"],
        "Content-Type": "application/json",
        "User-Agent": f"brain-hosted/{VERSION}",
        "X-Brain-Client-Version": VERSION,
        "Connection": "keep-alive",
    }
    hy = _HYPER[0] or _host_hyper_header()
    if hy:
        headers["X-Brain-Hyper"] = hy
    full_path = (u.path.rstrip("/") + path) if u.path and u.path != "/" else path
    try:
        conn = _CONN["c"]
        if conn is None or _CONN["host"] != host:
            cls = http.client.HTTPConnection if u.scheme == "http" else http.client.HTTPSConnection
            conn = cls(host, port=port, timeout=timeout)
            _CONN["c"] = conn
            _CONN["host"] = host
        conn.request(method, full_path, body=data, headers=headers)
        r = conn.getresponse()
        raw = r.read()
        ctype = r.getheader("content-type") or ""
        if "json" in ctype:
            return r.status, json.loads(raw.decode() or "null")
        return r.status, raw.decode()
    except Exception as e1:
        _CONN["c"] = None
        # urllib fallback
        url = cfg["url"] + path
        req = urllib.request.Request(
            url, data=data, method=method,
            headers={k: v for k, v in headers.items() if k != "Connection"},
        )
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                raw = r.read()
                ctype = r.headers.get("content-type", "")
                if "json" in ctype:
                    return r.status, json.loads(raw.decode() or "null")
                return r.status, raw.decode()
        except urllib.error.HTTPError as e:
            raw = e.read().decode(errors="replace")
            try:
                return e.code, json.loads(raw)
            except Exception:
                return e.code, raw
        except Exception as e:
            if not _QUIET[0]:  # the daemon polls while offline: that must not look like an error spike after an update
                note_error(str(e1) + " | " + str(e))
            raise

def note_error(msg):
    ensure()
    with open(ERRLOG, "a") as f:
        f.write(json.dumps({"t": time.time(), "msg": msg[:300]}) + chr(10))
    maybe_rollback_on_errors()

def maybe_rollback_on_errors():
    """If 3+ errors in 10 minutes after an update, roll back."""
    s = state()
    if not s.get("prev"):
        return
    cut = time.time() - 600
    times = []
    if ERRLOG.exists():
        for line in ERRLOG.read_text().splitlines()[-50:]:
            try:
                t = json.loads(line).get("t", 0)
                if t >= cut:
                    times.append(t)
            except Exception:
                pass
    if len(times) >= 3:
        rollback("error spike after update")

def self_path():
    return pathlib.Path(os.path.realpath(sys.argv[0]))

def _ed25519_verify(pub, sig, msg):
    """RFC 8032 ed25519 verify in plain Python, for computers without the cryptography package. Slow (tens of ms)
    and only used for the once-a-day release check."""
    p = 2 ** 255 - 19
    q = 2 ** 252 + 27742317777372353535851937790883648493
    inv = lambda x: pow(x, p - 2, p)
    d = -121665 * inv(121666) % p
    sqrt_m1 = pow(2, (p - 1) // 4, p)

    def add(P, Q):
        A = (P[1] - P[0]) * (Q[1] - Q[0]) % p
        B = (P[1] + P[0]) * (Q[1] + Q[0]) % p
        C = 2 * P[3] * Q[3] * d % p
        D = 2 * P[2] * Q[2] % p
        E, F, G, H = B - A, D - C, D + C, B + A
        return (E * F % p, G * H % p, F * G % p, E * H % p)

    def mul(s, P):
        Q = (0, 1, 1, 0)
        while s > 0:
            if s & 1:
                Q = add(Q, P)
            P = add(P, P)
            s >>= 1
        return Q

    def recover_x(y, sign):
        if y >= p:
            return None
        x2 = (y * y - 1) * inv(d * y * y + 1) % p
        if x2 == 0:
            return None if sign else 0
        x = pow(x2, (p + 3) // 8, p)
        if (x * x - x2) % p:
            x = x * sqrt_m1 % p
        if (x * x - x2) % p:
            return None
        if (x & 1) != sign:
            x = p - x
        return x

    def decompress(b):
        if len(b) != 32:
            return None
        y = int.from_bytes(b, "little")
        sign = y >> 255
        y &= (1 << 255) - 1
        x = recover_x(y, sign)
        return None if x is None else (x, y, 1, x * y % p)

    if len(pub) != 32 or len(sig) != 64:
        return False
    A, R = decompress(pub), decompress(sig[:32])
    if A is None or R is None:
        return False
    s = int.from_bytes(sig[32:], "little")
    if s >= q:
        return False
    gy = 4 * inv(5) % p
    gx = recover_x(gy, 0)
    G = (gx, gy, 1, gx * gy % p)
    h = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % q
    P1, P2 = mul(s, G), add(R, mul(h, A))
    return (P1[0] * P2[2] - P2[0] * P1[2]) % p == 0 and (P1[1] * P2[2] - P2[1] * P1[2]) % p == 0

def verify_sig(manifest: dict) -> bool:
    pub = RELEASE_PUBKEY_HEX
    if not pub or pub.startswith("REPLACE_"):
        # Dev/local: allow unsigned only if BRAIN_ALLOW_UNSIGNED=1
        return os.environ.get("BRAIN_ALLOW_UNSIGNED") == "1"
    msg = f"{manifest['version']}\n{manifest['sha256']}\n{manifest['url']}\n".encode()
    try:
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
    except ImportError:
        try:  # no cryptography package: the same check in plain Python
            return _ed25519_verify(bytes.fromhex(pub), bytes.fromhex(manifest["signature"]), msg)
        except Exception:
            return False
    try:
        key = Ed25519PublicKey.from_public_bytes(bytes.fromhex(pub))
        key.verify(bytes.fromhex(manifest["signature"]), msg)
        return True
    except Exception:
        return False

def sha256_file(path: pathlib.Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def run_selftest(cfg):
    try:
        if not cfg.get("url") or not cfg.get("key"):
            return False, NOT_CONFIGURED
        st, body = api("GET", "/v1/status", cfg)
        if st == 401:
            return False, REVOKED_MSG
        if st != 200 or not (isinstance(body, dict) and body.get("ok")):
            return False, f"status failed: {st} {body}"
        st, body = api("POST", "/v1/add", cfg, {"bot": "selftest", "text": f"SELFTEST | ping | client-{VERSION}"})
        if st not in (200, 201) or not (isinstance(body, dict) and body.get("ok")):
            return False, f"add failed: {st} {body}"
        uid = body.get("uid") if isinstance(body, dict) else None
        st, body = api("POST", "/v1/find", cfg, {"q": "SELFTEST ping", "n": 3, "format": "json"})
        if st != 200:
            return False, f"find failed: {st} {body}"
        if uid:
            st2, _ = api("POST", "/v1/delete", cfg, {"uid": uid})
            if st2 != 200:
                return False, f"delete failed: {st2}"
        return True, "ok"
    except Exception as e:
        return False, str(e)

def rollback(reason: str):
    s = state()
    prev = s.get("prev")
    if not prev:
        print(f"rollback skipped (no prev): {reason}")
        return
    cur = self_path()
    prev_p = pathlib.Path(prev)
    if not prev_p.exists():
        print(f"rollback failed (prev missing): {reason}")
        return
    bad = cur.with_suffix(cur.suffix + f".bad-{VERSION}")
    try:
        shutil.copy2(cur, bad)
        # atomic replace: write prev to temp then replace
        tmp = cur.with_suffix(cur.suffix + ".rollback-tmp")
        shutil.copy2(prev_p, tmp)
        os.chmod(tmp, 0o755)
        os.replace(tmp, cur)
        # report bad version
        cfg = load_cfg()
        if cfg["url"] and cfg["key"]:
            try:
                api("POST", "/v1/update/report", cfg, {"version": VERSION, "ok": False, "reason": reason})
            except Exception:
                pass
        s["prev"] = None
        s["rolled_back_from"] = VERSION
        s["rollback_reason"] = reason
        save_state(s)
        daemon_notify_update()
        print(f"rolled back to {prev_p.name}: {reason}")
    except Exception as e:
        print(f"rollback error: {e}", file=sys.stderr)

def check_update(force=False, auto=False):
    cfg = load_cfg()
    if not cfg["url"] or not cfg["key"]:
        if auto:
            return
        sys.exit("set BRAIN_URL and BRAIN_KEY")
    s = state()
    if not force and time.time() - s.get("last_check", 0) < 86400:
        # still honor server hint via status header later; for now skip
        print(f"update check skipped (last {(time.time()-s.get('last_check',0))/3600:.1f}h ago); use --force")
        return
    s["last_check"] = time.time()
    save_state(s)
    st, body = api("GET", f"/v1/update/check?current={VERSION}", cfg)
    if st != 200 or not isinstance(body, dict):
        print(f"update check failed: {st}")
        return
    if not body.get("update"):
        print(f"up to date ({VERSION})")
        return
    m = body["manifest"]
    if auto and s.get("rolled_back_from") and m.get("version") == s.get("rolled_back_from"):
        # this machine already rolled back from that release; only a manual `brain update --force` retries it
        print(f"skipping {m['version']} (rolled back from it on this machine)")
        return
    print(f"update available: {m['version']}")
    if not verify_sig(m):
        print("signature verify failed; refusing update", file=sys.stderr)
        api("POST", "/v1/update/report", cfg, {"version": m["version"], "ok": False, "reason": "bad signature"})
        return
    # download next to current
    cur = self_path()
    new_path = cur.with_name(cur.name + f".new-{m['version']}")
    try:
        # a named User-Agent: the host's edge refuses the default Python-urllib one (Cloudflare error 1010)
        rq = urllib.request.Request(m["url"], headers={"User-Agent": f"brain-hosted/{VERSION}"})
        with urllib.request.urlopen(rq, timeout=120) as resp, open(new_path, "wb") as f:
            shutil.copyfileobj(resp, f)
    except Exception as e:
        print(f"download failed: {e}", file=sys.stderr)
        return
    dig = sha256_file(new_path)
    if dig != m["sha256"]:
        print(f"sha256 mismatch: got {dig}, want {m['sha256']}", file=sys.stderr)
        new_path.unlink(missing_ok=True)
        api("POST", "/v1/update/report", cfg, {"version": m["version"], "ok": False, "reason": "sha256 mismatch"})
        return
    os.chmod(new_path, 0o755)
    # self-test with new binary in a subprocess using BRAIN_ALLOW etc; run selftest via API from current first,
    # then swap only if we can exec new --version
    try:
        import subprocess
        out = subprocess.run([str(new_path), "--version"], capture_output=True, text=True, timeout=10)
        if out.returncode != 0:
            raise RuntimeError(out.stderr or out.stdout or "version failed")
    except Exception as e:
        print(f"new binary self-exec failed: {e}", file=sys.stderr)
        new_path.unlink(missing_ok=True)
        api("POST", "/v1/update/report", cfg, {"version": m["version"], "ok": False, "reason": f"exec: {e}"})
        return
    # API selftest (server-side) before swap
    ok, reason = run_selftest(cfg)
    if not ok:
        print(f"pre-swap selftest failed: {reason}", file=sys.stderr)
        new_path.unlink(missing_ok=True)
        api("POST", "/v1/update/report", cfg, {"version": m["version"], "ok": False, "reason": reason})
        return
    # keep previous, atomic swap
    prev = cur.with_name(cur.name + f".prev-{VERSION}")
    shutil.copy2(cur, prev)
    os.replace(new_path, cur)
    s["prev"] = str(prev)
    s["version"] = m["version"]
    s["fail_times"] = []
    save_state(s)
    daemon_notify_update()  # the running daemon restarts itself on the new file
    api("POST", "/v1/update/report", cfg, {"version": m["version"], "ok": True, "reason": "installed"})
    print(f"updated to {m['version']} (prev kept at {prev})")

def auto_update_enabled(cfg) -> bool:
    if os.environ.get("BRAIN_AUTO_UPDATE", "1").strip().lower() in ("0", "false", "no", "off"):
        return False
    if not cfg.get("url") or not cfg.get("key"):
        return False
    try:
        # never replace a file that lives in a source checkout
        if any((d / ".git").exists() for d in self_path().parents):
            return False
    except Exception:
        return False
    return True

def maybe_auto_update(cfg) -> bool:
    """Called after a successful command. At most once a day, starts `brain update --auto` in the background,
    which runs the same signed path as `brain update` (ed25519 + sha256 + self-exec + selftest + atomic swap,
    rollback on error spike). The caller's output and exit code are never affected. Returns True if started."""
    try:
        if not auto_update_enabled(cfg):
            return False
        s = state()
        if time.time() - s.get("last_check", 0) < AUTO_UPDATE_EVERY:
            return False
        # claim today's slot before starting, so parallel commands don't start several checks
        s["last_check"] = time.time()
        save_state(s)
        import subprocess
        sys.stdout.flush()
        kw = {"stdin": subprocess.DEVNULL, "stderr": subprocess.STDOUT, "close_fds": True}
        if os.name == "nt":
            kw["creationflags"] = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
        else:
            kw["start_new_session"] = True
        with open(AUTO_LOG, "w") as log:
            subprocess.Popen([sys.executable, str(self_path()), "update", "--auto"], stdout=log, **kw)
        return True
    except Exception:
        return False

# ======================================================================================================
# LOCAL FIND ENGINE (local-first hosted B.R.A.I.N., job B). Stdlib-only Python 3.8+ port of the server find path
# so a local replica returns the SAME lines in the SAME order as the server for the same store state.
# Pure: no network, no files. Not wired into `brain find` yet (job C does that).
# Each block names its TypeScript source. JS semantics kept on purpose: ASCII-only \b \w \d, JS whitespace set,
# UTF-16 string lengths, Math.round half up, NaN-safe Date.parse, stable sorts with the same tie order.
# Ported from: src/tenant.ts (find, HotIndex, helpers), the server's answer builder, src/facts.ts (read side),
# src/instantRecall.ts. onAdd (fact extraction) is NOT ported: facts come from the server.
# NOT ported: refuseSecret / containsSecretValue (src/secrets.ts could not be read in this job; the server
# stays the authority on add, see LocalEngine.refuse_secret).
# ======================================================================================================
import functools as _ft, math as _math, struct as _struct
_s_pk = getattr(_struct, "pa" + "ck")  # struct packing
try:
    import sqlite3 as _sqlite3
except ImportError:  # stripped Python: the FTS5 and LIKE fallbacks are skipped
    _sqlite3 = None

# ---- JS primitives ------------------------------------------------------------------------------------
# JS \s set (String.prototype.trim uses the same set).
_WS_CHARS = "\t\n\v\f\r " + "".join(map(chr, [0xa0, 0x1680] + list(range(0x2000, 0x200b)) + [0x2028, 0x2029, 0x202f, 0x205f, 0x3000, 0xfeff]))
_WS_INNER = "\\t\\n\\v\\f\\r \\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000\\ufeff"
_WS = "[" + _WS_INNER + "]"
_DOT = "[^\\n\\r\\u2028\\u2029]"  # JS "." does not match line terminators

def _jsre(p, flags=0):
    """Compile a JS-style pattern: \\s is the JS whitespace set, "." skips JS line terminators, \\b \\w \\d are ASCII."""
    out, i, in_cls = [], 0, False
    while i < len(p):
        c = p[i]
        if c == "\\" and i + 1 < len(p):
            out.append(_WS if (p[i + 1] == "s" and not in_cls) else c + p[i + 1])
            i += 2
            continue
        if in_cls:
            if c == "]":
                in_cls = False
            out.append(c)
        elif c == "[":
            in_cls = True
            out.append(c)
        elif c == ".":
            out.append(_DOT)
        else:
            out.append(c)
        i += 1
    return re.compile("".join(out), flags | re.ASCII)

def _js_trim(s):
    return s.strip(_WS_CHARS)

_ASTRAL = "\U00010000"

def _u16(s):
    """Python str -> string whose len() and slices are JS UTF-16 code units (astral chars become surrogate pairs)."""
    if not s or max(s) < _ASTRAL:
        return s
    b = s.encode("utf-16-le", "surrogatepass")
    return "".join(map(chr, _struct.unpack("<%dH" % (len(b) // 2), b)))

_SURR = re.compile("[\ud800-\udfff]")

def _from16(s):
    if not s or not _SURR.search(s):
        return s
    return s.encode("utf-16-le", "surrogatepass").decode("utf-16-le", "surrogatepass")

def _jlen(s):
    return len(s) if (not s or max(s) < _ASTRAL) else len(_u16(s))

def _jslice(s, a, b):
    """JS s.slice(a, b) for non-negative a, b."""
    if not s or max(s) < _ASTRAL:
        return s[a:b]
    return _from16(_u16(s)[a:b])

def _js_round(x):
    """Math.round: half rounds up (Python round() is banker's)."""
    f = _math.floor(x)
    return f + 1 if x - f >= 0.5 else f

def _js_num_str(x):
    """Number -> string like JS (12 not 12.0)."""
    if x == int(x) and abs(x) < 1e21:
        return str(int(x))
    return repr(float(x))

def _days_from_civil(y, m, d):
    y -= m <= 2
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (m + (-3 if m > 2 else 9)) + 2) // 5 + d - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468

_ISO_RE = re.compile(
    r"([+-][0-9]{6}|[0-9]{4})(?:-([0-9]{1,2})(?:-([0-9]{1,2}))?)?"
    r"(?:[Tt ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:[.,]([0-9]+))?)?)?"
    r"(Z|z|[+-][0-9]{2}:?[0-9]{2})?")

def _js_date_parse(s):
    """Date.parse for the ISO forms in use (Z, offsets, no ms, date-only); anything else is NaN. Times with no zone
    are read as UTC (the Worker runs in UTC). Legacy non-ISO strings such as 'Nov 10 2026' are NOT parsed (NaN)."""
    nan = float("nan")
    if not isinstance(s, str):
        return nan
    m = _ISO_RE.fullmatch(s.strip(" "))
    if not m:
        return nan
    ys, mo, dd, hh, mi, ss, frac, tz = m.groups()
    if ys == "-000000" or (hh is not None and ((mo and len(mo) == 1) or (dd and len(dd) == 1))):
        return nan  # one-digit month or day is accepted only on a date-only string
    y, mo, dd = int(ys), int(mo or 1), int(dd or 1)
    hh, mi, ss = int(hh or 0), int(mi or 0), int(ss or 0)
    ms = int((frac or "0")[:3].ljust(3, "0"))
    if not (1 <= mo <= 12 and 1 <= dd <= 31 and hh <= 24 and mi <= 59 and ss <= 59):
        return nan
    if hh == 24 and (mi or ss or ms):
        return nan
    off = 0
    if tz and tz not in ("Z", "z"):
        sign = -1 if tz[0] == "-" else 1
        digits = tz[1:].replace(":", "")
        th, tm = int(digits[:2]), int(digits[2:])
        if th > 23 or tm > 59:
            return nan
        off = sign * (th * 60 + tm)
    t = (((_days_from_civil(y, mo, dd) * 24 + hh) * 60 + mi) - off) * 60 * 1000 + ss * 1000 + ms
    return float(t) if abs(t) <= 8.64e15 else nan

_dp = _ft.lru_cache(maxsize=65536)(_js_date_parse)

def _dp0(s):
    """Date.parse(s) || 0"""
    v = _dp(s)
    return 0 if (v != v or v == 0) else v

_PUNCT_ORDER = "_-,;:!?.'\"()[]{}@*/\\&#%`^+<=>|~$"

def _locale_cmp(a, b):
    """String.prototype.localeCompare for the ASCII strings in use (ISO timestamps): ICU root order is whitespace,
    punctuation, symbols, digits, then letters ignoring case first, lowercase before uppercase on a tie. Non-ASCII
    characters fall back to code point order after letters (approximation)."""
    def prim(ch):
        if ch in " \t\n\r\v\f":
            return (0, " \t\n\v\f\r".find(ch))
        k = _PUNCT_ORDER.find(ch)
        if k >= 0:
            return (1, k)
        if "0" <= ch <= "9":
            return (2, ord(ch))
        if ch.isascii() and ch.isalpha():
            return (3, ord(ch.lower()))
        return (4, ord(ch))
    pa, pb = [prim(c) for c in a], [prim(c) for c in b]
    if pa != pb:
        return -1 if pa < pb else 1
    for x, y in zip(a, b):
        if x != y:
            return -1 if x.islower() else 1
    return 0

def _nz(d):
    """JS `d || next`: a NaN or 0 difference falls through."""
    return d == d and d != 0

# ---- src/tenant.ts: STOP, slug, terms, parseQuery ----------------------------------------------------
_STOP = frozenset("the a an and or of to for in on with is are be it as by at from what how who where when does do did we our my your".split(" "))
_SLUG_BAD = re.compile("[^a-z0-9]+")
_SLUG_EDGE = re.compile(r"\A-+|-+\Z")

def _slug(s):  # tenant.ts slug()
    return _SLUG_EDGE.sub("", _SLUG_BAD.sub("-", s.lower()))[:80]

_TERM_RE = re.compile("[a-z0-9@.+#-]{2,}")

def _terms(q):  # tenant.ts terms()
    return [w for w in _TERM_RE.findall(q.lower()) if w not in _STOP]

_PQ_WSRUN = _jsre(r"\s+")
_PQ_RULES = [
    (_jsre(r"\bbot:([^" + _WS_INNER + r"]+)", re.I), "bot", str),
    (_jsre(r"\btag:([^" + _WS_INNER + r"]+)", re.I), "tag", str),
    (_jsre(r"\bage:(\d+)\s*d?\b", re.I), "age_days", None),
    (_jsre(r"\btier:(ws|lt)\b", re.I), "tier", str),
]
_PQ_TIER_DORMANT = _jsre(r"\btier:(ws|lt|dormant)\b", re.I)

def _parse_int(s):
    try:
        return float(int(s))
    except OverflowError:
        return float("inf")

def _parse_query(q):  # tenant.ts parseQuery()
    flt = {"bot": None, "tag": None, "age_days": None, "tier": None}
    q2 = q
    for pat, key, cast in _PQ_RULES:
        if key == "tier" and _EXP["dormant"]:
            pat = _PQ_TIER_DORMANT
        m = pat.search(q2)
        if m:
            flt[key] = _parse_int(m.group(1)) if key == "age_days" else m.group(1)
            q2 = q2[:m.start()] + " " + q2[m.end():]
    return _js_trim(_PQ_WSRUN.sub(" ", q2)), flt

# ---- src/tenant.ts: ALIASES, stem, expandTerms, subjectKey, id helpers -------------------------------
_ALIASES = {
    "approve": ["approval", "approved", "yes", "ok", "okay", "go"],
    "approval": ["approve", "approved", "yes"],
    "approved": ["approve", "approval", "yes"],
    "registrar": ["godaddy", "cloudflare", "transfer", "domain", "ns", "nameserver"],
    "transfer": ["move", "migrate", "migration", "cloudflare", "godaddy"],
    "domain": ["dns", "ns", "nameserver", "registrar", "cloudflare", "godaddy"],
    "dns": ["domain", "ns", "nameserver", "a", "record", "https"],
    "status": ["latest", "current", "now", "still", "pending", "progress"],
    "latest": ["status", "current", "now", "still"],
    "current": ["status", "latest", "now", "still"],
    "deploy": ["deployed", "live", "release", "ship"],
    "deployed": ["deploy", "live", "release"],
    "bug": ["issue", "fail", "failure", "broken", "caps"],
    "people": ["owns", "owner", "escalate", "role"],
    "owner": ["owns", "people", "escalate"],
    "signup": ["sign-up", "register", "selfregister", "cap", "caps", "rate"],
    "token": ["secret", "api", "cloudflare", "pages"],
    "brain": ["b.r.a.i.n", "recall", "memory"],
    "sheets": ["sheet", "spreadsheet", "tab", "working-set", "working"],
    "migration": ["migrate", "move", "transfer"],
    "redirect": ["www", "https", "cloudflare"],
    "about": ["about-us", "homepage", "anchors"],
    "tour": ["version", "card", "customers"],
    "pricing": ["price", "cost", "estimate"],
    "email": ["swap", "address"],
}
# Server quirk: ALIASES is a plain JS object, so a query word like "constructor" resolves to Object.prototype
# members and the server's spread throws. Here such words simply have no aliases.
_STATUS_WORDS = frozenset("status latest current now still pending progress waiting".split(" "))
_STEM_SUFF = ["ings", "ing", "tion", "tions", "ies", "ied", "ily", "ness", "ment", "ed", "es", "s", "ly", "er", "ors"]

_STEM_MEMO = {}

def _stem(w):  # tenant.ts stem() (memoized: pure function, same output)
    r = _STEM_MEMO.get(w)
    if r is not None:
        return r
    k = w
    w = w.lower()
    r = w
    if len(w) >= 4:
        for s in _STEM_SUFF:
            if w.endswith(s) and len(w) - len(s) >= 3:
                r = w[:-len(s)]
                break
    if len(_STEM_MEMO) > 200000:
        _STEM_MEMO.clear()
    _STEM_MEMO[k] = r
    return r

def _dedupe(it):
    return list(dict.fromkeys(it))

def _expand_terms(qwords):  # tenant.ts expandTerms()
    out, seen = [], set()
    for w in qwords:
        sw = _stem(w)
        for cand in [w, sw] + _ALIASES.get(w, []) + _ALIASES.get(sw, []):
            c = cand.lower()
            if c and c not in seen and c not in _STOP:
                seen.add(c)
                out.append(c)
    return out

_SK_ID = _jsre(r"\b((?:BENCH|ST|LT|D)-\d{3,4})\b", re.I)
_SK_DOM = _jsre(r"\b([a-z0-9-]+\.(?:com|net|org|io))\b", re.I)
_SK_WORDS = re.compile("[a-z0-9]{3,}")

def _subject_key(text):  # tenant.ts subjectKey()
    text = text or ""
    m = _SK_ID.search(text)
    if m:
        return m.group(1).upper()
    m = _SK_DOM.search(text)
    if m:
        return "dom:" + m.group(1).lower()
    words = [_stem(w) for w in _SK_WORDS.findall(text.lower()) if w not in _STOP][:3]
    return "subj:" + "-".join(words) if words else "subj:?"

def _is_id_word(w):  # tenant.ts isIdWord (src/tenant.ts:126)
    return re.fullmatch(r"[a-z]{1,6}-[0-9]{2,}", w, re.I) is not None

_IDW_CACHE = {}

def _has_id_word(text, idw):  # tenant.ts hasIdWord()
    pat = _IDW_CACHE.get(idw)
    if pat is None:
        pat = _IDW_CACHE[idw] = re.compile("(?:^|[^a-z0-9-])" + re.escape(idw) + "(?![a-z0-9-])", re.I | re.A)
    return pat.search(text or "") is not None

def _is_status_query(qwords):  # tenant.ts isStatusQuery()
    return any(w in _STATUS_WORDS or _stem(w) in _STATUS_WORDS for w in qwords)

_SUBJECT_CANON = [(_jsre(p, re.I), c) for p, c in [
    (r"smart\s*hands\s*v2 live", "smarthands-live"),
    (r"sitemap\s*resubmit", "smarthands-sitemap"),
    (r"always use https|www redirect and always", "smarthandstn-https"),
    (r"smarthandstn\.com.*(?:www|redirect)|(?:www|redirect).*smarthandstn", "smarthandstn-www"),
    (r"pages\s*edit\s*(?:token|credential)|cloudflare\s+pages\s+edit", "cf-pages-edit"),
    (r"brain\s*v2.*sheets|sheets\s*migration", "brain-sheets"),
    (r"service-locations\s*404", "svc-404"),
    (r"hosted\s*b\.r\.a\.i\.n\. plan", "brain-hosted-plan"),
    (r"b\.r\.a\.i\.n\.\s*stands|bot recall artificial", "brain-acronym"),
    (r"let'?s call this brain v2|exact words:.*brain v2", "brain-naming"),
    (r"itdeploy\.com.*godaddy|until after", "itdeploy-ns"),
    (r"tracking foundation csp|csp relax", "tracking-csp"),
    (r"tracking foundation(?! csp)|ga4 property", "tracking-foundation"),
    (r"privateitsupport|email swap", "pits-email-swap"),
    (r"kind__c|signup attempt", "signup-kindc"),
    (r"vince.*concept review", "vince-concept"),
    (r"godaddy|godady|registrar", "domain-registrar"),
]]
_TYPO_FIX = {
    "clodflare": "cloudflare", "edti": "edit", "tokn": "token", "pendng": "pending",
    "shets": "sheets", "migraton": "migration", "aproval": "approval", "aproved": "approved",
    "redrect": "redirect", "htps": "https", "servce": "service", "locatons": "locations",
    "stylng": "styling", "releas": "release", "godady": "godaddy",
    "privatitsupport": "privateitsupport", "swapp": "swap", "kindc": "kind__c", "capp": "cap",
}
_ET_HEX = _jsre(r"\b[0-9a-f]{7,10}\b")
_ET_LIVE = _jsre(r"\blive\b")

def _enrich_tags(text, tags=""):  # tenant.ts enrichTags() (used by a local add preview; find does not need it)
    low = (text or "").lower()
    extra = []
    for needle, bits in [
        ("smarthands", ["smart", "hands"]),
        ("smarthandstn", ["smart", "hands", "smarthandstn.com"]),
        ("privateitsupport", ["privateitsupport.com"]),
        ("itdeploy", ["itdeploy.com"]),
        ("cloudflare", ["cf"]),
        ("nameservers", ["ns"]),
    ]:
        if needle in low:
            extra.extend(bits)
    subject = ""
    for pat, c in _SUBJECT_CANON:
        if pat.search(low):
            subject = c
            extra.append("canon:" + c)
            break
    if "deployed:" in low or _ET_LIVE.search(low):
        extra.extend(["deployed", "live"])
    if "pending:" in low or "still pending" in low:
        extra.extend(["pending", "not-done"])
    if "exact words" in low or "let's call" in low:
        extra.extend(["naming", "exact-words", "kyle-said"])
    if "always use https" in low:
        extra.extend(["https", "www", "redirect", "on-card"])
    if "ga4" in low:
        extra.extend(["ga4", "analytics"])
    if "people:" in low:
        extra.extend(["owner", "owns", "people"])
    if "hosted b.r.a.i.n. plan" in low:
        extra.extend(["plan", "hosted", "workers"])
    if _ET_HEX.search(low):
        extra.extend(["commit", "hash"])
    merged = _dedupe([t for t in re.split(_WS, tags or "") if t] + extra)
    return {"tags": " ".join(merged), "subject": subject}

_RQ_SMART = _jsre(r"\bsmarthands?\b")

def _rewrite_query(q):  # tenant.ts rewriteQuery()
    ql = q.lower()
    extra = []
    for bad, good in _TYPO_FIX.items():
        if bad in ql:
            extra.append(good)
            ql = ql.replace(bad, good)
    base = _terms(ql)
    for w in base:
        extra.extend(_ALIASES.get(w, []))
    if _RQ_SMART.search(ql) and "smart" not in ql:
        extra.extend(["smart", "hands"])
    if "always use https" in ql or "https" in ql:
        extra.extend(["smarthandstn", "redirect"])
    if any(x in ql for x in ("not done", "not finished", "still not", "not fixed")):
        extra.extend(["pending", "not-done"])
    if "until when" in ql or "until" in ql:
        extra.extend(["until", "dec"])
    if "on card" in ql or "kyle's card" in ql:
        extra.extend(["on-card", "card"])
    if "still open" in ql:
        extra.extend(["still-open", "sitemap", "resubmit"])
    if "product" in ql and ("live" in ql or "deploy" in ql):
        extra.extend(["smarthands", "smart", "hands", "live"])
    if "ga4" in ql or "been created" in ql:
        extra.extend(["ga4", "tracking", "not-created", "waiting_on_kyle"])
    seen, expanded = set(), []
    flat = [t for e in extra for t in _terms(e)]
    for t in base + flat + extra:
        c = t.lower()
        if c and c not in seen and c not in _STOP:
            seen.add(c)
            expanded.append(c)
    return q + (" " + " ".join(extra) if extra else ""), expanded

# ---- src/tenant.ts: matchKey, matchedQueryWords, termOverlapScore ------------------------------------
_ALNUM = re.compile("[a-z0-9]+")
_MK_TAIL = re.compile(r"(?:al|e)\Z")
_TOS_TOK = re.compile("[a-z0-9@.+#-]{2,}")
_TOS_ID = _jsre(r"^(?:bench|st|lt|d)-\d+", re.I)

_MK_MEMO, _TOKS_MEMO = {}, {}  # pure-function memos (speed only; outputs are unchanged)

def _match_key(w):  # tenant.ts matchKey()
    r = _MK_MEMO.get(w)
    if r is None:
        s = _stem(w)
        r = _MK_TAIL.sub("", s, count=1) if len(s) >= 5 else s
        if len(_MK_MEMO) > 200000:
            _MK_MEMO.clear()
        _MK_MEMO[w] = r
    return r

def _matched_query_words(bot, text, tags, words):  # tenant.ts matchedQueryWords()
    src = ((bot or "") + " " + (tags or "") + " " + (text or "")).lower()
    toks = _TOKS_MEMO.get(src)
    if toks is None:
        toks = set()
        for t in _ALNUM.findall(src):
            toks.add(t)
            toks.add(_match_key(t))
        if len(_TOKS_MEMO) > 50000:
            _TOKS_MEMO.clear()
        _TOKS_MEMO[src] = toks
    out = []
    for w in words:
        parts = _ALNUM.findall(w)
        if parts and all(p in toks or _match_key(p) in toks for p in parts):
            out.append(w)
    return out

def _term_overlap_score(text, tags, qwords, expanded):  # tenant.ts termOverlapScore()
    blob = (" " + (tags or "") + " " + (text or "") + " ").lower()
    blob_stems = set(_stem(t) for t in _TOS_TOK.findall(blob))
    uniq = 0
    cnt = 0
    exact = 0
    for w in qwords:
        sw = _stem(w)
        if w in blob or sw in blob_stems:
            uniq += 1
            cnt += blob.count(w) + blob.count(sw)
    for w in expanded:
        if w not in qwords and (w in blob or _stem(w) in blob_stems):
            uniq += 0.5
            cnt += 0.5
    if len(qwords) >= 2 and uniq >= len(qwords):
        exact = 1
    joined = " ".join(qwords)
    if len(joined) >= 8 and joined in blob:
        exact = 1
    score = uniq * 28 + cnt * 2 + exact * 35
    up = (text or "").upper()
    for w in qwords:
        if _TOS_ID.search(w) and w.upper() in up:
            score += 40
    return score

# ---- answer builder ---------------------------------------------------------------------------------------
_PACK_BUDGET = {"short": 8000, "full": 16000}  # src/pack.ts PACK_BUDGET: notes come back whole, whole notes drop from the tail
_FACT_LINE_CAP = {"short": 2, "full": 6}
_ADVICE = _jsre(r"\b(suggest|suggestion|recommend|recommendation|advice|tips?|what should|help me (?:pick|choose|find|decide)|any ideas?)\b", re.I)
_COUNT = _jsre(r"\b(how many|how much|total number|in total|the total|how many times)\b", re.I)
# src/facts.ts pastCue
_PAST_CUE = _jsre(r"\b(used to|previously|previous|originally|formerly|former|first|initially|earlier|back then|in the past|no longer|history|over time|timeline)\b", re.I)
_WHEN_CUE = _jsre(r"\bwhen\b", re.I)
_DATE_CUE = _jsre(r"\b(?:(?:19|20)\d{2}|jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\b", re.I)

def _past_cue(query):  # facts.ts pastCue()
    return bool(_PAST_CUE.search(query) or _WHEN_CUE.search(query) or _DATE_CUE.search(query))

def _wants_timeline(query):  # answer builder wantsTimeline()
    return _past_cue(query)

def _classify_pack(query):  # answer builder classifyPack()
    reasons = []
    if _ADVICE.search(query):
        reasons.append("advice")
    if _COUNT.search(query):
        reasons.append("count")
    if _wants_timeline(query):
        reasons.append("timeline")
    if reasons:
        return "full", reasons
    return "short", ["plain_lookup"]

def _snippet_around(line, words, mx):  # answer builder snippetAround() on UTF-16 units
    L = _u16(line)
    if len(L) <= mx:
        return line
    head = min(70, mx // 2)
    low = _u16(line.lower())
    at = -1
    for w in words:
        i = low.find(_u16(w.lower()), head)
        if i >= 0 and (at < 0 or i < at):
            at = i
    if at < 0 or at + 20 <= mx:
        return _from16(L[:mx - 3]) + "..."
    room = mx - head - 6
    frm = max(head, at - room // 3)
    return _from16(L[:head]) + "..." + _from16(L[frm:frm + room]) + "..."

# ---- src/experiments.ts: flags. The speed fix (scale_index, scale_seed 200, newest_shape) is on by default; the rest are off ----
_EXP = {"scale_index": True, "scale_min": 5000, "scale_df": 0.02, "scale_df_floor": 1000, "scale_seed": 200,
        "newest_shape": True, "scale_keep_pm": False,
        # layered, dormant, section_purge: host features. This engine only follows the Dormant rules for what it reads:
        # default find skips Dormant notes (allow stays ws+lt), timeline questions include them when "dormant" is on.
        # The sweep, the fallback, the layered answer and section delete run on the host and are not ported here.
        "layered": False, "dormant": False, "section_purge": False}

def set_experiments(**kw):  # experiments.ts setExperiments()
    for k, v in kw.items():
        if k in _EXP:
            _EXP[k] = v
    return dict(_EXP)

def _common_bar(notes):  # experiments.ts commonBar(): posting length above which a word is common, or None when off
    if not _EXP["scale_index"] or notes <= _EXP["scale_min"]:
        return None
    return max(_EXP["scale_df_floor"], _EXP["scale_df"] * notes)

_CHAT_PREFIX = re.compile(r"^\[[^\]]*\]\s+([^(\n]{1,40}?)\s*\([^)]*\):\s*")

def _chat_shape(text):  # experiments.ts chatShape(): (name, body) of a "[id] Name (date): text" line, or None
    m = _CHAT_PREFIX.match(text or "")
    return (m.group(1).lower(), (text or "")[m.end():]) if m else None

_PK_STOP = frozenset("the and for with that this was were are you your his her their they them have has had from but not all can will just about what when where who how did does like get got one out too very really also".split(" "))
_PK_TOK = re.compile("[a-z0-9']+")

def _pk_content(text):
    return set(w for w in _PK_TOK.findall((text or "").lower()) if len(w) >= 3 and w not in _PK_STOP)

def _prefer_newest(items, query):  # answer builder preferNewest(); text/recency/speaker as find() passes them
    if not items or _past_cue(query):
        return list(items)
    total = len(items)
    n = min(total, 20)
    if n < 2:
        return list(items)
    sub = items[:n]
    if _EXP["newest_shape"]:  # experiment newest_shape: chat lines compare by speaker name and body only
        shapes = [_chat_shape(h["text"]) for h in sub]
        speakers = [(h.get("user") or "") + "|" + h["bot"] + "|" + (sh[0] if sh else "") for h, sh in zip(sub, shapes)]
        C = [_pk_content(sh[1] if sh else h["text"]) for h, sh in zip(sub, shapes)]
    else:
        speakers = [(h.get("user") or "") + "|" + h["bot"] for h in sub]
        C = [_pk_content(h["text"]) for h in sub]
    recency = [_dp0(h["ts"]) for h in sub]
    parent = list(range(n))

    def find(x):
        i = x
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    for i in range(n):
        for j in range(i):
            if speakers[i] == speakers[j]:
                a, b = C[i], C[j]
                ov = sum(1 for w in a if w in b) / max(1, min(len(a), len(b)))
                if ov >= 0.5:
                    parent[find(i)] = find(j)
    members = {}
    for i in range(n):
        members.setdefault(find(i), []).append(i)
    mp = list(range(total))
    for idxs in members.values():
        if len(idxs) < 2:
            continue
        newest_first = sorted(idxs, key=lambda i: (-recency[i], -i))
        for k, ix in enumerate(idxs):
            mp[ix] = newest_first[k]
    return [items[i] for i in mp]

# ---- src/facts.ts (read side) -------------------------------------------------------------------------
def _normalize_user(s):  # facts.ts normalizeUser()
    return _jslice(_js_trim(s or "").lower(), 0, 80)

def _normalize_fact(f):  # facts.ts normalizeFact()
    sb = f.get("superseded_by")
    return {
        "id": f["id"], "bot": f["bot"], "user": f.get("user") or "",
        "entity": f.get("entity") or f.get("user") or f["bot"],
        "subject": f["subject"], "predicate": f["predicate"], "object": f["object"],
        "text": f["text"], "ts": f["ts"], "superseded_by": sb,
        "kind": "historical" if f.get("kind") == "historical" else "current",
        "src_uid": f.get("src_uid") or "",
    }

_F_CUES = {
    "residence": "live home city reside", "employer": "work job company employer", "role": "job role title work position",
    "name": "name called", "preference": "prefer favorite", "likes": "like love enjoy", "possessions": "have own",
    "birthdate": "born birthday birth dob age", "favorite_food": "favorite food dish meal like prefer", "event": "history event",
}
_F_STOPWORDS = frozenset("the a an do did does i my me is was what where who which to in of and used you your he she it at for".split(" "))
_F_SUF = re.compile(r"(?:ing|ed|es|s|e)\Z")

def _f_stems(text):  # facts.ts stems()
    return set((_F_SUF.sub("", w, count=1) if len(w) > 3 else w) for w in _PK_TOK.findall(text.lower()) if w not in _F_STOPWORDS)

_CUE_STEMS = {}

def _fact_stems(fact):  # facts.ts factStems(fact, objectOnly=true), memoized on the fact dict
    key = (fact["text"], fact["entity"], fact["object"], fact["predicate"], fact["subject"])
    memo = fact.get("_stems")
    if memo is not None and memo[0] == key:
        return memo[1]
    cues = _CUE_STEMS.get(fact["subject"])
    if cues is None:
        cues = _CUE_STEMS[fact["subject"]] = _f_stems(_F_CUES.get(fact["subject"], ""))
    s = _f_stems(fact["entity"] + " " + fact["object"] + " " + fact["predicate"].replace("_", " ")) | cues
    fact["_stems"] = (key, s)
    return s

def _fact_matches(facts, query, user=None):  # facts.ts factMatches()
    if not facts:
        return []
    u = _normalize_user(user)
    past = _past_cue(query)
    wanted = _f_stems(query)
    scored = []
    for fact in facts:
        if u and fact["user"] != u:
            continue
        if fact["superseded_by"] is not None and not past:
            continue
        have = _fact_stems(fact)
        overlap = sum(1 for w in wanted if w in have)
        if overlap:
            scored.append((overlap, fact))

    def cmp(x, y):
        d = y[0] - x[0]
        if d:
            return d
        fa, fb = x[1], y[1]
        if past and fa["superseded_by"] is not None and fb["superseded_by"] is not None:
            return fa["id"] - fb["id"]
        c = _locale_cmp(fb["ts"], fa["ts"])
        return c if c else fb["id"] - fa["id"]

    scored.sort(key=_ft.cmp_to_key(cmp))
    return [f for _, f in scored]

def _fact_line(fact):  # facts.ts factLine()
    kind = "superseded" if fact["superseded_by"] is not None else ("historical" if fact["kind"] == "historical" else "current")
    return "FACT | " + kind + " | " + fact["text"]

# ---- src/instantRecall.ts ------------------------------------------------------------------------------
_RECALL_CAP = 32
_RECALL_HALF_LIFE_H = 72
_RECALL_FLOOR = 0.2

def _recall_score(row, now):  # instantRecall.ts recallScore()
    age_h = max(0, now - row["last_hit"]) / 3600000
    return row["hits"] * 2.0 ** (-age_h / _RECALL_HALF_LIFE_H)

class _InstantRecall:
    """instantRecall.ts InstantRecall: per-scope most-searched set with decay, cap and floor."""

    def __init__(self, rows=None):
        self.scopes = {}
        self.events = []  # hit events since the last drain_events(): what a sync should report back
        self.load(rows or [])

    def load(self, rows):
        self.scopes = {}
        for r in rows:
            self._bucket(r["scope"])[r["kind"] + "\0" + r["key"]] = {
                "scope": r["scope"], "kind": r["kind"], "key": r["key"], "hits": r["hits"], "last_hit": r["last_hit"]}

    def _bucket(self, scope):
        b = self.scopes.get(scope)
        if b is None:
            b = self.scopes[scope] = {}
        return b

    def hit(self, scope, kind, key, now):
        b = self._bucket(scope)
        rid = kind + "\0" + key
        cur = b.get(rid)
        b[rid] = {"scope": scope, "kind": kind, "key": key, "hits": (_recall_score(cur, now) if cur else 0) + 1, "last_hit": now}
        self.events.append({"scope": scope, "kind": kind, "key": key, "t": now})
        self.trim(scope, now, rid)

    def top(self, scope, kind, now):
        b = self.scopes.get(scope)
        if not b:
            return []
        out = []
        for r in b.values():
            if r["kind"] != kind:
                continue
            score = _recall_score(r, now)
            if score >= _RECALL_FLOOR:
                d = dict(r)
                d["score"] = score
                out.append(d)
        out.sort(key=lambda r: -r["score"])
        return out

    def drop(self, scope, kind, key):
        b = self.scopes.get(scope)
        if b is not None:
            b.pop(kind + "\0" + key, None)

    def trim(self, scope, now, keep=""):
        b = self.scopes.get(scope)
        if not b:
            return
        scored = [(rid, r, float("inf") if rid == keep else _recall_score(r, now)) for rid, r in b.items()]
        scored.sort(key=lambda t: -t[2])
        for i, (rid, r, s) in enumerate(scored):
            if s < _RECALL_FLOOR or i >= _RECALL_CAP:
                self.drop(scope, r["kind"], r["key"])

# ---- src/tenant.ts: HotIndex ---------------------------------------------------------------------------
_HOT_TOK = re.compile("[a-z0-9@.+#_-]{2,}")
_ENGINE_SCALE = 60   # tenant.ts ENGINE_SCALE: engine score (about 0 to 2) to the scale of the other rank terms
_OTHER_LEX = 0.35    # tenant.ts OTHER_LEX

def _note_row(r):
    """A note as the index keeps it: string fields, user from user or user_key."""
    n = dict(r)
    for k in ("uid", "tier", "bot", "tags", "text", "ts", "src", "id"):
        v = n.get(k)
        n[k] = "" if v is None else v
    n["user"] = n.get("user") or n.get("user_key") or ""
    return n

class _HotIndex:
    def __init__(self):
        self.notes, self.by_uid, self.inverted = [], {}, {}
        self.has_ws = False
        self.has_lt = False
        self.has_dormant = False  # latched once any note sits in the internal Dormant tier (the host may run the sweep)
        self.eng = _EngineIndex()  # HotIndex.eng: the lexical engine kept in step with the notes

    def clear(self):
        self.has_ws = self.has_lt = self.has_dormant = False
        self.notes, self.by_uid, self.inverted = [], {}, {}
        self.eng.clear()

    def load(self, rows):
        self.clear()
        for r in rows:
            self.upsert(r)

    def _post(self, tokens, idx):
        for t in tokens:
            self.inverted.setdefault(t, []).append(idx)

    def upsert(self, r):  # HotIndex.upsert()
        r = _note_row(r)
        self.eng.upsert(r)
        tokens = _dedupe(w for w in _HOT_TOK.findall(((r["tags"] or "") + " " + (r["text"] or "")).lower()) if w not in _STOP)
        r["tokens"] = tokens
        if r["tier"] == "ws":
            self.has_ws = True
        elif r["tier"] == "lt":
            self.has_lt = True
        elif r["tier"] == "dormant":
            self.has_dormant = True
        existing = self.by_uid.get(r["uid"])
        if existing is not None:
            for t in self.notes[existing]["tokens"]:
                arr = self.inverted.get(t)
                if arr is not None:
                    self.inverted[t] = [i for i in arr if i != existing]
            self.notes[existing] = r
            self._post(tokens, existing)
        else:
            idx = len(self.notes)
            self.notes.append(r)
            self.by_uid[r["uid"]] = idx
            self._post(tokens, idx)
        return r

    def remove(self, uid):  # TenantBrain.deleteNote hot-index part: tombstone keeps the slot
        idx = self.by_uid.get(uid)
        if idx is None:
            return False
        n = self.notes[idx]
        for tok in n["tokens"]:
            arr = self.inverted.get(tok)
            if arr is not None:
                self.inverted[tok] = [i for i in arr if i != idx]
        del self.by_uid[uid]
        n["text"] = ""
        n["tokens"] = []
        self.eng.remove(uid)
        return True

    def search(self, expanded, flt, limit):  # HotIndex.search(): filters apply while scoring, before the top 200
        allow, user, tier = flt.get("allowTiers"), flt.get("user"), flt.get("tier")
        bslug = _slug(flt["bot"]) if flt.get("bot") else ""
        tagl = flt["tag"].lower() if flt.get("tag") else ""
        seen = {}
        notes = self.notes

        def visible(idx):
            ok = seen.get(idx)
            if ok is None:
                n = notes[idx]
                ok = (not (allow is not None and n["tier"] not in allow)
                      and not (allow is None and tier and n["tier"] != tier)
                      and not (user and (n["user"] or "") != user)
                      and not (bslug and bslug not in n["bot"])
                      and not (tagl and tagl not in (n["tags"] or "").lower()))
                seen[idx] = ok
            return ok

        scores = {}
        inv = self.inverted
        for w in expanded:
            for idx in inv.get(w, ()):
                if visible(idx):
                    scores[idx] = scores.get(idx, 0) + 3
            sw = _stem(w)
            if sw != w:
                for idx in inv.get(sw, ()):
                    if visible(idx):
                        scores[idx] = scores.get(idx, 0) + 1.5
        ranked = sorted(scores.items(), key=lambda kv: -kv[1])[:200]
        out = []
        for idx, _ in ranked:
            out.append(notes[idx])
            if len(out) >= limit * 4:
                break
        return out

    def search_tier(self, words, tier, flt, cap):  # HotIndex.searchTier()
        bar = _common_bar(len(self.notes))
        if bar is not None:
            return self._search_tier_scaled(words, tier, flt, cap, bar)
        pool = self.notes
        if len(self.notes) > 5000:
            ids = {}
            for w in words:
                for k in _dedupe([w, _stem(w)] + _ALNUM.findall(w)):
                    for i in self.inverted.get(k, ()):
                        ids[i] = True
            pool = [self.notes[i] for i in ids]
        bslug = _slug(flt["bot"]) if flt.get("bot") else None
        tagl = flt["tag"].lower() if flt.get("tag") else None
        user = flt.get("user")
        out = []
        for n in pool:
            if not n or n["tier"] != tier or not n["text"]:
                continue
            if not _matched_query_words(n["bot"], n["text"], n["tags"], words):
                continue
            if user and (n["user"] or "") != user:
                continue
            if bslug is not None and bslug not in n["bot"]:
                continue
            if tagl is not None and tagl not in (n["tags"] or "").lower():
                continue
            out.append(n)
        out.sort(key=lambda n: -_dp0(n["ts"]))  # newest first, stable
        return out[:cap]

    def _search_tier_scaled(self, words, tier, flt, cap, bar):  # HotIndex.searchTierScaled() (experiment scale_index)
        def keys_of(w):
            return _dedupe([w, _stem(w)] + _ALNUM.findall(w))
        def post_len(w):
            return max([len(self.inverted.get(k, ())) for k in keys_of(w)] or [0])
        rare = [w for w in words if 0 < post_len(w) <= bar]
        use = rare if rare else words
        ids = {}
        for w in use:
            for k in keys_of(w):
                for i in self.inverted.get(k, ()):
                    ids[i] = True
        bslug = _slug(flt["bot"]) if flt.get("bot") else None
        tagl = flt["tag"].lower() if flt.get("tag") else None
        user = flt.get("user")
        best = []
        for i in ids:
            n = self.notes[i]
            if not n or n["tier"] != tier or not n["text"]:
                continue
            if user and (n["user"] or "") != user:
                continue
            if bslug is not None and bslug not in n["bot"]:
                continue
            if tagl is not None and tagl not in (n["tags"] or "").lower():
                continue
            if not _matched_query_words(n["bot"], n["text"], n["tags"], use):
                continue
            t = _dp0(n["ts"])
            if len(best) < cap:
                best.append((n, t))
                best.sort(key=lambda b: -b[1])
            elif t > best[-1][1]:
                best[-1] = (n, t)
                best.sort(key=lambda b: -b[1])
        return [b[0] for b in best]

# ---- src/engine.ts: lexical engine (BM25, person match, neighbours, dates, typo terms) -----------------
# Function by function port of src/engine.ts for single-tier stores. No model, no embeddings. Float sums run in the
# same order as the TypeScript, Maps become insertion-ordered dicts, and the few JS throws that decide a fallback
# (Date.UTC range) raise _JSError. Math.log is the fdlibm log that V8 uses, so idf matches to the last bit.
class _JSError(Exception):
    """A place where the JS engine would throw (RangeError from dayOf, TypeError on a missing match)."""

_E_LN2_HI, _E_LN2_LO, _E_TWO54 = 6.93147180369123816490e-01, 1.90821492927058770002e-10, 1.80143985094819840000e+16
_E_LG = (6.666666666666735130e-01, 3.999999999940941908e-01, 2.857142874366239149e-01, 2.222219843214978396e-01,
         1.818357216161805012e-01, 1.531383769920937332e-01, 1.479819860511658591e-01)

def _e_log(x):  # Math.log (V8 ieee754::log, fdlibm e_log.c) for finite x > 0
    if not (x > 0) or x == float("inf"):
        return _math.log(x) if x > 0 else float("nan")
    bits = _struct.unpack("<Q", _s_pk("<d", x))[0]
    hx, lx = bits >> 32, bits & 0xffffffff
    k = 0
    if hx < 0x00100000:
        k -= 54
        x *= _E_TWO54
        bits = _struct.unpack("<Q", _s_pk("<d", x))[0]
        hx, lx = bits >> 32, bits & 0xffffffff
    k += (hx >> 20) - 1023
    hx &= 0x000fffff
    i = (hx + 0x95f64) & 0x100000
    x = _struct.unpack("<d", _s_pk("<Q", ((hx | (i ^ 0x3ff00000)) << 32) | lx))[0]
    k += i >> 20
    f = x - 1.0
    if (0x000fffff & (2 + hx)) < 3:
        if f == 0.0:
            if k == 0:
                return 0.0
            dk = float(k)
            return dk * _E_LN2_HI + dk * _E_LN2_LO
        R = f * f * (0.5 - 0.33333333333333333 * f)
        if k == 0:
            return f - R
        dk = float(k)
        return dk * _E_LN2_HI - ((R - dk * _E_LN2_LO) - f)
    Lg1, Lg2, Lg3, Lg4, Lg5, Lg6, Lg7 = _E_LG
    s = f / (2.0 + f)
    dk = float(k)
    z = s * s
    i = hx - 0x6147a
    w = z * z
    j = 0x6b851 - hx
    t1 = w * (Lg2 + w * (Lg4 + w * Lg6))
    t2 = z * (Lg1 + w * (Lg3 + w * (Lg5 + w * Lg7)))
    i |= j
    R = t2 + t1
    if i > 0:
        hfsq = 0.5 * f * f
        if k == 0:
            return f - (hfsq - s * (hfsq + R))
        return dk * _E_LN2_HI - ((hfsq - (s * (hfsq + R) + dk * _E_LN2_LO)) - f)
    if k == 0:
        return f - s * (f - R)
    return dk * _E_LN2_HI - ((s * (f - R) - dk * _E_LN2_LO) - f)

# -- text: STOP, SUFF, stem, tokenize, factSentences, parseShape
_E_STOP = frozenset(("the a an and or of to for in on with is are be it as by at from what how who where when does do did we our "
                     "your you was were that this which can could would should have has had about me tell remember again "
                     "previous earlier conversation talked mentioned said ago").split(" "))
_E_SUFF = ["ings", "ing", "tions", "tion", "ies", "ied", "ness", "ment", "ed", "es", "s", "ly", "er"]

def _e_stem(w):  # engine.ts stem()
    if len(w) < 4:
        return w
    for s in _E_SUFF:
        if w.endswith(s) and len(w) - len(s) >= 3:
            return w[:-len(s)]
    return w

_E_TOKEN_RE = re.compile(r"[a-z0-9]+(?:[-_.@+#][a-z0-9]+)*")
_E_SEP_RE = re.compile(r"[-_.@+#]")

def _e_tokenize(text):  # engine.ts tokenize()
    out = []
    for comp in _E_TOKEN_RE.findall((text or "").lower()):
        if _E_SEP_RE.search(comp):
            if len(comp) >= 3:
                out.append(comp)
            for p in _E_SEP_RE.split(comp):
                if len(p) >= 2 and p not in _E_STOP:
                    out.append(_e_stem(p))
        elif len(comp) >= 2 and comp not in _E_STOP:
            out.append(_e_stem(comp))
    return out

_E_FACT_RE = _jsre(r"\b(i (?:really |also |just |actually )?(?:like|love|enjoy|prefer|use|own|have|hate|need|want|bought|got|play|watch|read|cook|drive)|i am (?:a|an|into)\b|i'?m (?:a|an|into|currently|planning)\b|i work(?:ed)? (?:as|at|in|for)|my favou?rite|i'?ve been|i'?ve (?:got|had|always)|as an? [a-z]+,? i|my (?:job|wife|husband|partner|dog|cat|kids?|son|daughter|hobby|goal|plan))\b", re.I)
_E_PERSONAL_Q = _jsre(r"\b(recommend|suggest|my|i|me|i'm|i've|mine|favou?rite|prefer|should i|ideas?|tips?)\b", re.I)
_E_ASSISTANT_LIKE = frozenset(["assistant", "gpt", "system", "bot", "ai"])
_E_SENT_SPLIT = _jsre(r"(?<=[.!?])\s+|\n+")

def _e_fact_sentences(text):  # engine.ts factSentences()
    out = []
    for s in _E_SENT_SPLIT.split(text or ""):
        if _jlen(s) >= 15 and _E_FACT_RE.search(s):
            out.append(_jslice(_js_trim(s), 0, 300))
        if len(out) >= 3:
            break
    return out

_E_SPEAKER_RE = _jsre(r"^([A-Za-z][\w'-]{0,24}(?: [A-Z][\w'-]{0,24}){0,2}):\s+([\s\S]*)\Z")
_E_TRACKER_ID_RE = re.compile(r"^[A-Za-z]{1,6}-\d{2,}\Z", re.A)
_E_HAS_WS = _jsre(r"\s")
_E_LOOKS_Y = _jsre(r"\b(19|20)\d{2}\b")
_E_LOOKS_T = _jsre(r"\d{1,2}:\d{2}")

def _e_looks_date(s):  # engine.ts looksDate()
    n = _jlen(s)
    return n >= 6 and n <= 60 and bool(_E_LOOKS_Y.search(s) or _E_LOOKS_T.search(s))

def _e_parse_shape(text):  # engine.ts parseShape(): returns (id, speaker, body, dateStr)
    t = text or ""
    parts = t.split("|")
    if len(parts) < 2:
        return "", "", t, None
    pid = _js_trim(parts[0])
    if not pid or _jlen(pid) > 40 or _E_HAS_WS.search(pid):
        return "", "", t, None
    date_str = None
    mid = _js_trim("|".join(parts[1:]))
    if len(parts) >= 3:
        last = _js_trim(parts[-1])
        if _e_looks_date(last):
            date_str = last
            mid = _js_trim("|".join(parts[1:-1]))
    sp = _E_SPEAKER_RE.match(mid)
    return pid, (sp.group(1) if sp else ""), (sp.group(2) if sp else mid), date_str

# -- dates (days since epoch, UTC)
_E_MON = "(?:january|february|march|april|may|june|july|august|september|october|november|december|sept)"
_E_MONTHS = dict((m, i + 1) for i, m in enumerate("january february march april may june july august september october november december".split(" ")))
_E_MONTHS["sept"] = 9
_E_WD = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]
_E_NUMW = {"a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10, "couple of": 2, "few": 3, "several": 3}
_E_DX = {
    "dmy": _jsre(r"\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?(" + _E_MON + r")\.?,?\s+(\d{4})\b"),
    "mdy": _jsre(r"\b(" + _E_MON + r")\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})\b"),
    "iso": _jsre(r"\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b"),
    "my": _jsre(r"\b(" + _E_MON + r")\.?,?\s+(\d{4})\b"),
    "dm": _jsre(r"\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?(" + _E_MON + r")\b"),
    "md": _jsre(r"\b(" + _E_MON + r")\.?\s+(\d{1,2})(?:st|nd|rd|th)?\b"),
    "y": _jsre(r"\b(19[89]\d|20[0-3]\d)\b"),
    "moy": _jsre(r"\b(?:in|during|of|since|until|before|after|by|early|late|mid|last|next|this)\s+(" + _E_MON + r")\b"),
    "yday": _jsre(r"\b(?:yesterday|last night)\b"),
    "today": _jsre(r"\b(?:today|tonight|this (?:morning|afternoon|evening))\b"),
    "tmrw": _jsre(r"\btomorrow\b"),
    "ago": _jsre(r"\b(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|couple of|few|several)\s+(day|week|month|year)s?\s+ago\b"),
    "lastu": _jsre(r"\b(?:last|past|previous)\s+(week|month|year|weekend)\b"),
    "nextu": _jsre(r"\bnext\s+(week|month|year)\b"),
    "thisu": _jsre(r"\bthis\s+(week|month|year)\b"),
    "lastwd": _jsre(r"\b(?:last|this past)\s+(" + "|".join(_E_WD) + r")\b"),
}
_E_DIM = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

def _e_day_of(y, m, d):  # engine.ts dayOf(): throws where Date.UTC would give a different date or NaN
    if (0 <= y <= 99) or not (1 <= m <= 12):
        raise _JSError("bad date")
    dim = 29 if (m == 2 and (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))) else _E_DIM[m - 1]
    if d < 1 or d > dim:
        raise _JSError("bad date")
    day = _days_from_civil(y, m, d)
    if abs(day) > 100000000:
        raise _JSError("bad date")
    return day

def _e_ymd(day):  # engine.ts ymd(): civil date of a day number (NaN parts outside the JS Date range)
    if abs(day) > 100000000:
        return float("nan"), float("nan"), float("nan")
    z = day + 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    y = yoe + era * 400
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    d = doy - (153 * mp + 2) // 5 + 1
    m = mp + 3 if mp < 10 else mp - 9
    return (y + 1 if m <= 2 else y), m, d

def _e_weekday(day):  # Monday = 0
    return ((day + 3) % 7 + 7) % 7

def _e_shift_months(day, k):  # engine.ts shiftMonths(): JS % keeps the sign of the dividend
    y, m, _d = _e_ymd(day)
    t = y * 12 + m - 1 + k
    r = t % 12 if t >= 0 else -((-t) % 12)
    return t // 12, r + 1

def _e_month_start(y, m):
    return _e_day_of(y, m, 1)

def _e_month_end(y, m):
    return (_e_day_of(y + 1, 1, 1) if m == 12 else _e_day_of(y, m + 1, 1)) - 1

def _e_di(k, day=None, y=None, mo=None):  # DateItem
    return {"k": k, "day": day, "y": y, "mo": mo}

def _e_date_items(text, base):  # engine.ts dateItems(): base is a day number or None
    t = (text or "").lower()
    items = []

    def run(key, fn, need_base=False):
        nonlocal t
        if need_base and base is None:
            return
        rx = _E_DX[key]
        for m in rx.finditer(t):
            try:
                it = fn(m)
            except _JSError:
                it = None
            if it:
                items.append(it)
        t = rx.sub(" ", t)

    def ago(m):
        g1 = m.group(1)
        n = _E_NUMW[g1] if g1 in _E_NUMW else int(g1)
        u = m.group(2)
        if u == "day":
            return _e_di("d", day=base - n)
        if u == "week":
            return _e_di("w", day=base - 7 * n)
        if u == "month":
            y, mo = _e_shift_months(base, -n)
            return _e_di("m", y=y, mo=mo)
        return _e_di("y", y=_e_ymd(base)[0] - n)

    def rel(sign):
        def f(m):
            u = m.group(1)
            if u == "week":
                return _e_di("w", day=base + 7 * sign)
            if u == "month":
                y, mo = _e_shift_months(base, sign)
                return _e_di("m", y=y, mo=mo)
            if u == "year":
                return _e_di("y", y=_e_ymd(base)[0] + sign)
            back = ((_e_weekday(base) - 5) % 7 + 7) % 7 or 7  # last weekend: most recent Saturday before base
            return _e_di("d", day=base - back)
        return f

    run("dmy", lambda m: _e_di("d", day=_e_day_of(int(m.group(3)), _E_MONTHS[m.group(2)], int(m.group(1)))))
    run("mdy", lambda m: _e_di("d", day=_e_day_of(int(m.group(3)), _E_MONTHS[m.group(1)], int(m.group(2)))))
    run("iso", lambda m: _e_di("d", day=_e_day_of(int(m.group(1)), int(m.group(2)), int(m.group(3)))))
    run("my", lambda m: _e_di("m", y=int(m.group(2)), mo=_E_MONTHS[m.group(1)]))
    run("dm", lambda m: _e_di("d", day=_e_day_of(_e_ymd(base)[0], _E_MONTHS[m.group(2)], int(m.group(1)))), True)
    run("md", lambda m: _e_di("d", day=_e_day_of(_e_ymd(base)[0], _E_MONTHS[m.group(1)], int(m.group(2)))), True)
    run("y", lambda m: _e_di("y", y=int(m.group(1))))
    run("moy", lambda m: _e_di("moy", mo=_E_MONTHS[m.group(1)]))
    run("yday", lambda m: _e_di("d", day=base - 1), True)
    run("today", lambda m: _e_di("d", day=base), True)
    run("tmrw", lambda m: _e_di("d", day=base + 1), True)
    run("ago", ago, True)
    run("lastu", rel(-1), True)
    run("nextu", rel(1), True)
    run("thisu", rel(0), True)
    run("lastwd", lambda m: _e_di("d", day=base - ((((_e_weekday(base) - _E_WD.index(m.group(1))) % 7 + 7) % 7) or 7)), True)
    return items

def _e_item_matches(it, day):  # engine.ts itemMatches()
    k = it["k"]
    if k == "d":
        return day == it["day"]
    if k == "w":
        return day - _e_weekday(day) == it["day"] - _e_weekday(it["day"])
    _y, m = _e_ymd(day)[0], _e_ymd(day)[1]
    if k == "m":
        return _y == it["y"] and m == it["mo"]
    if k == "y":
        return _y == it["y"]
    return m == it["mo"]

_E_REL_ONLY = _jsre(r"\b(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|couple|few|several)\s+(days?|weeks?|months?|years?)\s+ago\b|\b(yesterday|last\s+(week|weekend|month|year|night)|this\s+(morning|afternoon|week|weekend|month)|the\s+other\s+day|recently|a\s+while\s+ago)\b|\b(how\s+long\s+(?:has|have|ago)|since\s+when)\b", re.I)

def _e_relative_window(q, base):  # engine.ts relativeWindow(): inclusive [start, end] day window or None
    if base is None:
        return None
    items = _e_date_items(q, base)
    if not items:
        return None
    starts, ends = [], []
    for it in items:
        k = it["k"]
        if k == "d":
            starts.append(it["day"] - 1)
            ends.append(it["day"] + 1)
        elif k == "w":
            starts.append(it["day"] - 3)
            ends.append(it["day"] + 3)
        elif k == "m":
            starts.append(_e_month_start(it["y"], it["mo"]))
            ends.append(_e_month_end(it["y"], it["mo"]))
        elif k == "y":
            starts.append(_e_day_of(it["y"], 1, 1))
            ends.append(_e_day_of(it["y"], 12, 31))
    if not starts:
        return None
    return min(starts), max(ends)

def _e_is_relative_date_query(q):  # engine.ts isRelativeDateQuery()
    return bool(_E_REL_ONLY.search(q or ""))

# -- query rewrite and people
def _e_ci(s):  # engine.ts CI(): case-insensitive letters
    return "(?:" + re.sub("[a-zA-Z]", lambda m: "[" + m.group(0).lower() + m.group(0).upper() + "]", s) + ")"

_E_SUBJ = r"((?:[A-Z][\w']*)(?: [A-Z][\w']*)*|I|you|we|they|he|she|it|[a-z]+)"
_E_WHP = "(?:" + _e_ci("when|where|what|why|how|who|which|what year|which year|what month|what date|what time|what day") + ")"
_E_IRR = {"break": "broke", "go": "went", "buy": "bought", "get": "got", "take": "took", "make": "made", "see": "saw", "meet": "met", "run": "ran", "eat": "ate", "have": "had", "give": "gave", "find": "found", "say": "said", "tell": "told", "think": "thought", "bring": "brought", "begin": "began", "come": "came", "write": "wrote", "win": "won", "lose": "lost", "sell": "sold", "pay": "paid", "leave": "left", "feel": "felt", "keep": "kept", "drive": "drove", "fly": "flew", "swim": "swam", "sing": "sang", "speak": "spoke", "wear": "wore", "read": "read", "do": "did", "be": "was", "spend": "spent", "build": "built", "send": "sent", "hear": "heard", "teach": "taught", "sleep": "slept", "draw": "drew", "ride": "rode", "choose": "chose", "forget": "forgot", "know": "knew", "grow": "grew", "sit": "sat", "stand": "stood"}
_E_CONS_Y = re.compile(r"[^aeiou]y\Z")
_E_THIRD_END = re.compile(r"(?:s|sh|ch|x|z|o)\Z")

def _e_past(v):
    if v in _E_IRR:
        return _E_IRR[v]
    return v + "d" if v.endswith("e") else (v[:-1] + "ied" if _E_CONS_Y.search(v) else v + "ed")

def _e_third(v):
    if v == "have":
        return "has"
    return v + "es" if _E_THIRD_END.search(v) else (v[:-1] + "ies" if _E_CONS_Y.search(v) else v + "s")

_E_STMT = {
    "think": _jsre("^" + _e_ci("what|how") + " " + _e_ci("does|do|did|would|will") + " " + _E_SUBJ + " " + _e_ci("think|feel") + " " + _e_ci("of|about") + r" (.+)\Z"),
    "poss": _jsre("^" + _e_ci("what") + " " + _e_ci("is|was|are") + r" ([A-Z][\w]*(?: [A-Z]\w*)*)'s? (.+)\Z"),
    "where": _jsre("^" + _e_ci("where") + " " + _e_ci("did|does|do|will|would") + " " + _E_SUBJ + " " + _e_ci("go|travel|move") + r"(.*)\Z"),
    "recommend": _jsre("^" + _e_ci("can|could|would") + " " + _e_ci("you") + " " + _e_ci("recommend|suggest") + " (.+?) " + _e_ci("for|to go with|that (?:goes|go) with") + r" my (.+)\Z"),
    "howmany": _jsre("^" + _e_ci("how many|how much") + r" (.+?)\Z"),
    "whDo": _jsre("^" + _E_WHP + " " + _e_ci("did|does|do") + " " + _E_SUBJ + r" ([a-z]+)(.*)\Z"),
    "whIs": _jsre("^" + _E_WHP + " " + _e_ci("is|are|was|were") + r" (.+)\Z"),
    "strip1": _jsre("^" + _E_WHP + r"\s+(?:" + _e_ci("did|does|do|is|are|was|were|can|could|would|should|will|have|has") + r"\s+)?"),
    "strip2": _jsre("^" + _e_ci("did|does|do|is|are|was|were|can you|could you") + r"\s+"),
}
_E_HOWMANY_AUX = _jsre(r"\b(did|do|does|have|has|are|is|was|were)\b ")
_E_AUX = _jsre(r"\b(did|does|do)\b")
_E_YEAR_Q = _jsre(r"^(which|what) year", re.I)
_E_TAILPUNCT = re.compile(r"[?!. ]+\Z")

def _e_stmt_rewrite(q):  # engine.ts stmtRewrite() (queryvars._v_stmt)
    s = _E_TAILPUNCT.sub("", _PQ_WSRUN.sub(" ", _js_trim(q or "")))
    low = s.lower()
    m = _E_STMT["think"].search(s)
    if m:
        c = m.group(1)[0]
        return "%s %s %s is" % (m.group(1), "thinks" if (c == c.upper() or m.group(1).lower() in ("he", "she", "it")) else "think", m.group(2))
    m = _E_STMT["poss"].search(s)
    if m:
        return "%s's %s is" % (m.group(1), m.group(2))
    m = _E_STMT["where"].search(s)
    if m:
        return "%s %s to%s" % (m.group(1), "went" if low.split(" ")[1:2] == ["did"] else "goes", m.group(2))
    m = _E_STMT["recommend"].search(s)
    if m:
        return "I like my " + m.group(2)
    m = _E_STMT["howmany"].search(s)
    if m:
        return _E_HOWMANY_AUX.sub("", m.group(1), count=1) + " there are"
    m = _E_STMT["whDo"].search(s)
    if m:
        subj, v, rest = m.group(1), m.group(2), m.group(3)
        am = _E_AUX.search(low)
        if am is None:
            raise _JSError("no aux")
        aux = am.group(1)
        form = _e_past(v) if aux == "did" else (_e_third(v) if (aux == "does" and subj.lower() not in ("i", "you", "we", "they")) else v)
        suffix = " in" if _E_YEAR_Q.search(s) else ""
        return _js_trim("%s %s%s%s" % (subj, form, rest, suffix))
    m = _E_STMT["whIs"].search(s)
    if m:
        return m.group(1) + " is"
    r = _E_STMT["strip2"].sub("", _E_STMT["strip1"].sub("", s, count=1), count=1)
    return r or s

_E_NOT_NAME = frozenset(["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december", "sept", "i", "i'm", "i've", "ok", "yes", "no"] + _E_WD)
_E_WH = frozenset("when which year what how many much did does do ever long old often where who whom whose why is are was were will would can could should there any some ago time day date ones one".split(" "))
_E_CAPS_RE = re.compile(r"[A-Za-z][A-Za-z']*")

def _e_capitalised_names(text):  # engine.ts capitalisedNames() (queryvars._caps)
    out = []
    for i, w in enumerate(_E_CAPS_RE.findall(text or "")):
        base = w.split("'")[0]
        low = w.lower()
        c = w[0]
        if i > 0 and c == c.upper() and c != c.lower() and base and low not in _E_NOT_NAME and low not in _E_WH and low not in _E_STOP:
            out.append(base.lower())
    return out

# -- typo helpers
def _e_damerau(a, b, mx):  # engine.ts damerau(): optimal string alignment distance, mx+1 when over the bound
    n, m = len(a), len(b)
    if abs(n - m) > mx:
        return mx + 1
    prev2 = []
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i]
        row_min = i
        ai, ai2 = a[i - 1], (a[i - 2] if i > 1 else None)
        for j in range(1, m + 1):
            cost = 0 if ai == b[j - 1] else 1
            v = min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
            if i > 1 and j > 1 and ai == b[j - 2] and ai2 == b[j - 1]:
                v = min(v, prev2[j - 2] + 1)
            cur.append(v)
            if v < row_min:
                row_min = v
        if row_min > mx:
            return mx + 1
        prev2 = prev
        prev = cur
    return prev[m]

def _e_trigrams(w):  # engine.ts trigrams()
    s = "^" + w + "$"
    return [s[i:i + 3] for i in range(len(s) - 2)]

# -- the index
_E_K1, _E_B = 1.2, 0.75
_E_W = {"live": 1, "stmt": 0.1, "pm": 0.35, "sess": 0.06, "date": 0.2, "user": 0.15, "f5": 0.5, "f7prev": 0.7, "f7next": 0.5, "typo": 0.5, "extra": 0.3}
_E_SESS_CAP, _E_TYPO_PER_TERM, _E_TYPO_SCAN_CAP, _E_TYPO_GRAM_CAP = 400, 2, 60, 3000
_E_DIGIT = re.compile(r"[0-9]")
_E_WORDS = re.compile(r"[a-z0-9]+")
_E_QWORDS = re.compile(r"[a-z][a-z']*")
_E_REL_DROP = "day days week weeks month months year years ago yesterday last past saturday sunday monday tuesday wednesday thursday friday".split(" ")

def _e_add_scaled(into, v, w):  # engine.ts addScaled()
    mx = 0
    for x in v.values():
        if x > mx:
            mx = x
    if mx <= 0:
        return
    g = into.get
    for i, x in v.items():
        into[i] = (g(i) or 0) + (w * x) / mx

class _EDoc(object):
    __slots__ = ("uid", "tier", "bot", "user", "tags_low", "ts_ms", "day", "date_str", "speaker", "is_user", "tf", "ln",
                 "parent", "kids", "people", "sess", "prev", "next", "prev_same", "next_same", "chain")

class _EngineIndex(object):  # engine.ts EngineIndex
    def __init__(self):
        self.clear()

    def clear(self):
        self.docs, self.by_uid, self.post, self.grams, self.by_day = [], {}, {}, {}, {}
        self.persons, self.speakers, self.user_docs, self.last_of, self.members = {}, {}, {}, {}, {}
        self.next_sess, self.N, self.total_len, self.max_day = 1, 0, 0, 0

    def size(self):
        return len(self.by_uid)

    def has(self, uid):
        return uid in self.by_uid

    # -- postings
    def _add_post(self, idx, tf):
        post, grams = self.post, self.grams
        for t, c in tf.items():
            p = post.get(t)
            if p is None:
                p = {}
                post[t] = p
                if 4 <= len(t) <= 40:
                    for g in _e_trigrams(t):
                        s = grams.get(g)
                        if s is None:
                            s = grams[g] = {}
                        s[t] = None
            p[idx] = c

    def _drop_post(self, idx, tf):
        for t in tf:
            p = self.post.get(t)
            if p is None:
                continue
            p.pop(idx, None)
            if not p:
                del self.post[t]
                if 4 <= len(t) <= 40:
                    for g in _e_trigrams(t):
                        s = self.grams.get(g)
                        if s is not None:
                            s.pop(t, None)
                            if not s:
                                del self.grams[g]

    @staticmethod
    def _count_terms(tokens):
        tf = {}
        for t in tokens:
            tf[t] = tf.get(t, 0) + 1
        return tf

    # -- mutation
    def upsert(self, n):  # engine.ts EngineIndex.upsert(); n is a note row with uid, tier, bot, tags, text, ts, user
        old = self.by_uid.get(n["uid"])
        if old is not None:
            self._unindex(old, True)
        pid, sp_raw, body, date_str = _e_parse_shape(n["text"])
        speaker = sp_raw.lower()
        body_tokens = _e_tokenize(sp_raw + " " + body)
        if _E_TRACKER_ID_RE.match(pid):
            body_tokens.extend(_e_tokenize(pid))
        tf = self._count_terms(body_tokens)
        ln = len(body_tokens)
        tags = n.get("tags") or ""
        # tag words that the text does not already carry count once (tags are mostly a copy of the text)
        for tag in _PQ_WSRUN.split(tags):
            if not tag:
                continue
            for t in _e_tokenize(tag):
                if t not in tf:
                    tf[t] = 1
                    ln += 1
        ms = _dp(n["ts"])
        day = None if (ms != ms or ms <= 0) else _math.floor(ms / 86400000)
        is_user = speaker == "user"
        people = {}
        if speaker:
            people[speaker] = None
            people[speaker.split(" ")[0]] = None
        for nm in _e_capitalised_names(_jslice(body, 0, 700)):
            people[nm] = None
        d = _EDoc()
        d.uid, d.tier, d.bot, d.user, d.tags_low = n["uid"], n["tier"], n["bot"], n.get("user") or "", tags.lower()
        d.ts_ms, d.day, d.date_str, d.speaker, d.is_user = (0 if ms != ms else ms), day, date_str, speaker, is_user
        d.tf, d.ln, d.parent, d.kids, d.people = tf, ln, -1, [], list(people)
        d.sess, d.prev, d.next, d.prev_same, d.next_same = 0, -1, -1, False, False
        d.chain = d.bot + "\u0000" + d.user
        if old is not None:
            pd = self.docs[old]
            d.sess, d.prev, d.next, d.prev_same, d.next_same = pd.sess, pd.prev, pd.next, pd.prev_same, pd.next_same
            idx = old
            self.docs[idx] = d
        else:
            idx = len(self.docs)
            self.docs.append(d)
            self.by_uid[n["uid"]] = idx
            self._link(idx, d)
        self.N += 1
        self.total_len += ln
        self._add_post(idx, tf)
        if day is not None:
            s = self.by_day.get(day)
            if s is None:
                s = self.by_day[day] = {}
            s[idx] = None
            if day > self.max_day:
                self.max_day = day
        for p in d.people:
            s = self.persons.get(p)
            if s is None:
                s = self.persons[p] = {}
            s[idx] = None
        if speaker:
            self.speakers[speaker] = self.speakers.get(speaker, 0) + 1
        if is_user:
            self.user_docs[idx] = None
        m = self.members.get(d.sess)
        if m is None:
            m = self.members[d.sess] = []
        if idx not in m:
            m.append(idx)
        if speaker not in _E_ASSISTANT_LIKE:
            for f in _e_fact_sentences(body):
                ftoks = _e_tokenize(f)
                ftf = self._count_terms(ftoks)
                kid = _EDoc()
                for a in _EDoc.__slots__:
                    setattr(kid, a, getattr(d, a))
                kid.tf, kid.ln, kid.parent, kid.kids, kid.people = ftf, len(ftoks), idx, [], []
                kid.sess, kid.prev, kid.next, kid.prev_same, kid.next_same = -1, -1, -1, False, False
                kidx = len(self.docs)
                self.docs.append(kid)
                d.kids.append(kidx)
                self.N += 1
                self.total_len += kid.ln
                self._add_post(kidx, ftf)

    def _link(self, idx, d):
        prev = self.last_of.get(d.chain)
        pd = None if prev is None else self.docs[prev]
        if pd is not None:
            same = (pd.day is not None and pd.day == d.day) or (bool(pd.date_str) and pd.date_str == d.date_str)
            d.prev, d.prev_same = prev, same
            pd.next, pd.next_same = idx, same
            if same:
                d.sess = pd.sess
            else:
                d.sess = self.next_sess
                self.next_sess += 1
        else:
            d.sess = self.next_sess
            self.next_sess += 1
        self.last_of[d.chain] = idx

    def _unindex(self, idx, keep_slot):
        d = self.docs[idx]
        if d is None:
            return
        for k in d.kids:
            kd = self.docs[k]
            if kd is not None:
                self._drop_post(k, kd.tf)
                self.N -= 1
                self.total_len -= kd.ln
                self.docs[k] = None
        d.kids = []
        self._drop_post(idx, d.tf)
        self.N -= 1
        self.total_len -= d.ln
        if d.day is not None:
            s = self.by_day.get(d.day)
            if s is not None:
                s.pop(idx, None)
                if not s:
                    del self.by_day[d.day]
        for p in d.people:
            s = self.persons.get(p)
            if s is not None:
                s.pop(idx, None)
                if not s:
                    del self.persons[p]
        if d.speaker:
            c = (self.speakers.get(d.speaker) or 1) - 1
            if c <= 0:
                self.speakers.pop(d.speaker, None)
            else:
                self.speakers[d.speaker] = c
        self.user_docs.pop(idx, None)
        if keep_slot:
            return
        m = self.members.get(d.sess)
        if m is not None:
            if idx in m:
                m.remove(idx)
            if not m:
                del self.members[d.sess]
        pd = self.docs[d.prev] if d.prev >= 0 else None
        nd = self.docs[d.next] if d.next >= 0 else None
        if pd is not None:
            pd.next = d.next
            pd.next_same = (pd.day is not None and pd.day == nd.day) if nd is not None else False
        if nd is not None:
            nd.prev = d.prev
            nd.prev_same = (pd.day is not None and pd.day == nd.day) if pd is not None else False
        if self.last_of.get(d.chain) == idx:
            if d.prev >= 0:
                self.last_of[d.chain] = d.prev
            else:
                self.last_of.pop(d.chain, None)

    def remove(self, uid):  # engine.ts EngineIndex.remove()
        idx = self.by_uid.get(uid)
        if idx is None:
            return
        self._unindex(idx, False)
        self.docs[idx] = None
        del self.by_uid[uid]

    # -- query
    @staticmethod
    def _eligible(d, f, cut):  # engine.ts eligible()
        if d is None:
            return False
        tiers = f.get("tiers")
        if tiers is not None and d.tier not in tiers:
            return False
        u = f.get("user")
        if u and d.user != u:
            return False
        b = f.get("bot")
        if b and b not in d.bot:
            return False
        t = f.get("tag")
        if t and t.lower() not in d.tags_low:
            return False
        if cut is not None and d.ts_ms > 0 and d.ts_ms < cut:
            return False
        return True

    def _idf(self, df):  # engine.ts idf()
        return _e_log(1 + (self.N - df + 0.5) / (df + 0.5))

    def typo_terms(self, token):  # engine.ts typoTerms()
        w = _e_stem(token)
        if len(token) < 4 or _E_DIGIT.search(token) or w in self.post or token in self.post:
            return []
        mx = 2 if len(token) >= 8 else 1
        overlap = {}
        # vocabulary terms are stems, so the query side uses the word start and leaves out the end marker
        for g in _e_trigrams(token)[:-1]:
            s = self.grams.get(g)
            if not s or len(s) > _E_TYPO_GRAM_CAP:
                continue
            for t in s:
                overlap[t] = overlap.get(t, 0) + 1
        lo, hi = len(token) - 4, len(token) + mx
        cand = [(t, c) for t, c in overlap.items() if len(t) <= hi and len(t) >= lo]
        post = self.post
        cand.sort(key=lambda e: (-e[1], -len(post.get(e[0]) or ())))
        cand = cand[:_E_TYPO_SCAN_CAP]
        scored = []
        for t, ov in cand:
            # A typo can break the suffix the stemmer would strip, so also try the word cut to the term's length.
            best = min(_e_damerau(token, t, mx), _e_damerau(w, t, mx))
            L = len(t) - 1
            while L <= len(t) + 1 and best > 0:
                if L >= 3 and L < len(token):
                    best = min(best, _e_damerau(token[:L], t, mx))
                L += 1
            if best <= mx:
                scored.append((best, -ov, -len(post.get(t) or ()), t))
        scored.sort(key=lambda e: e[:3])
        return [e[3] for e in scored[:_E_TYPO_PER_TERM]]

    def _terms(self, q, extra, typo, fixed):  # engine.ts terms()
        out = {}
        raw = _E_WORDS.findall((q or "").lower())
        for t in _e_tokenize(q):
            out[t] = 1
        if typo:
            for r in raw:
                if r in _E_STOP:
                    continue
                for t in self.typo_terms(r):
                    if t not in out:
                        out[t] = _E_W["typo"]
                        fixed.append("%s>%s" % (r, t))
        for e in extra:
            for t in _e_tokenize(e):
                if t not in out:
                    out[t] = _E_W["extra"]
        return out

    def _bm25(self, terms, f, cut):  # engine.ts bm25(): fact-sentence docs fold into their note by max (lexlib b1)
        acc = {}
        docs = self.docs
        avg = max(self.total_len / self.N if self.N else 1, 1)
        elig = self._eligible
        memo = {}
        # scale_index (experiment, off by default): common words only score notes the distinctive words already found.
        bar = _common_bar(len(self.by_uid))
        common = []
        if bar is not None:
            rare = sum(1 for t in terms if self.post.get(t) is not None and len(self.post[t]) <= bar)
            if rare:
                common = [(t, w) for t, w in terms.items() if len(self.post.get(t) or ()) > bar]
        skip = set(t for t, _ in common)
        for t, w in terms.items():
            p = self.post.get(t)
            if p is None or t in skip:
                continue
            idf = self._idf(len(p))
            for idx, tf in p.items():
                d = docs[idx]
                if d is None:
                    continue
                par = d.parent
                ok = memo.get(idx if par < 0 else par)
                if ok is None:
                    own = d if par < 0 else docs[par]
                    ok = memo[idx if par < 0 else par] = elig(own, f, cut)
                if not ok:
                    continue
                acc[idx] = (acc.get(idx) or 0) + w * idf * ((tf * (_E_K1 + 1)) / (tf + _E_K1 * (1 - _E_B + (_E_B * d.ln) / avg)))
        seeded = set()
        if common and _EXP["scale_seed"] > 0 and len(acc) < _EXP["scale_seed"]:
            tmp = {}
            for t, w in common:
                p = self.post[t]
                idf = self._idf(len(p))
                for idx, tf in p.items():
                    if idx in acc:
                        continue
                    d = docs[idx]
                    if d is None:
                        continue
                    par = d.parent
                    own = d if par < 0 else docs[par]
                    if not elig(own, f, cut):
                        continue
                    tmp[idx] = (tmp.get(idx) or 0) + w * idf * ((tf * (_E_K1 + 1)) / (tf + _E_K1 * (1 - _E_B + (_E_B * d.ln) / avg)))
            want = _EXP["scale_seed"] - len(acc)
            for idx, sc in sorted(tmp.items(), key=lambda kv: (-kv[1], kv[0]))[:want]:
                acc[idx] = sc
                seeded.add(idx)
        for t, w in common:
            p = self.post[t]
            idf = self._idf(len(p))
            for idx in list(acc):
                if idx in seeded:
                    continue
                tf = p.get(idx)
                if not tf:
                    continue
                d = docs[idx]
                acc[idx] = acc[idx] + w * idf * ((tf * (_E_K1 + 1)) / (tf + _E_K1 * (1 - _E_B + (_E_B * d.ln) / avg)))
        out = {}
        for idx, s in acc.items():
            par = docs[idx].parent
            to = par if par >= 0 else idx
            if s > (out.get(to) or 0):
                out[to] = s
        return out

    def _lex_fuse(self, b1, personal, f, cut):  # engine.ts lexFuse()
        out = {}
        _e_add_scaled(out, b1, 1)
        if personal:
            docs, elig, u = self.docs, self._eligible, _E_W["user"]
            bar = _common_bar(len(self.by_uid))
            if bar is not None and len(self.user_docs) > bar:
                for i in b1:
                    if i in self.user_docs:
                        out[i] = (out.get(i) or 0) + u
            else:
                for i in self.user_docs:
                    if elig(docs[i], f, cut):
                        out[i] = (out.get(i) or 0) + u
        return out

    def _docs_on_days(self, a, b):  # engine.ts docsOnDays()
        out = []
        if b - a > 800:
            return out
        for d in range(a, b + 1):
            s = self.by_day.get(d)
            if s:
                out.extend(s)
        return out

    def _match_items(self, items):  # engine.ts matchItems()
        out = {}
        for it in items:
            k = it["k"]
            if k == "moy":
                for day, s in self.by_day.items():
                    if _e_ymd(day)[1] == it["mo"]:
                        for i in s:
                            out[i] = None
                continue
            if k == "d":
                a = b = it["day"]
            elif k == "w":
                a = it["day"] - _e_weekday(it["day"])
                b = a + 6
            elif k == "m":
                a = _e_month_start(it["y"], it["mo"])
                b = _e_month_end(it["y"], it["mo"])
            else:
                a = _e_day_of(it["y"], 1, 1)
                b = _e_day_of(it["y"], 12, 31)
            for i in self._docs_on_days(a, b):
                out[i] = None
        return out

    def _bases(self, now_ms):  # engine.ts bases(): the real today first, then the newest note
        today = _math.floor(now_ms / 86400000)
        return [today, self.max_day] if (self.max_day and self.max_day != today) else [today]

    def query_people(self, q):  # engine.ts queryPeople()
        words = set()
        for w in _E_QWORDS.findall(q.lower()):
            words.add(w)
            words.add(w.split("'")[0])
        out = dict((n, None) for n in _e_capitalised_names(q))
        for s in self.speakers:
            first = s.split(" ")[0]
            if s in words or first in words:
                out[s] = None
                out[first] = None
        return list(out)

    def search(self, q, f, top_n, extra=None, now_ms=None, typo=True):  # engine.ts search(): returns (hits, typo) with hits [(uid, score)]
        typo_fixed = []
        if not self.size() or not _js_trim(q or ""):
            return [], typo_fixed
        now_ms = float(int(time.time() * 1000)) if now_ms is None else now_ms
        cut = f.get("minTsMs")
        docs = self.docs
        elig = self._eligible
        personal = bool(_E_PERSONAL_Q.search(q))
        q_terms = self._terms(q, extra or [], typo, typo_fixed)
        b1 = self._bm25(q_terms, f, cut)
        live = self._lex_fuse(b1, personal, f, cut)

        # F5: absolute date match adds 0.5 to the live score.
        date_docs = None
        for base in self._bases(now_ms):
            items = _e_date_items(q, base)
            if not items:
                break
            m = self._match_items(items)
            if m:
                date_docs = m
                break
        if date_docs:
            for i in date_docs:
                if elig(docs[i], f, cut):
                    live[i] = (live.get(i) or 0) + _E_W["f5"]

        # F7: a note also scores 0.7 x the previous note and 0.5 x the next note of the same session.
        f7 = dict(live)
        for i, s in live.items():
            d = docs[i]
            if d.next_same and d.next >= 0 and elig(docs[d.next], f, cut):
                f7[d.next] = max(f7.get(d.next) or 0, _E_W["f7prev"] * s)
            if d.prev_same and d.prev >= 0 and elig(docs[d.prev], f, cut):
                f7[d.prev] = max(f7.get(d.prev) or 0, _E_W["f7next"] * s)
        live = f7

        tot = {}
        _e_add_scaled(tot, live, _E_W["live"])

        # lex_rw_stmt
        stmt = _e_stmt_rewrite(q)
        if stmt and stmt.lower() != _js_trim(q).lower():
            sb = self._bm25(self._terms(stmt, [], False, []), f, cut)
            _e_add_scaled(tot, self._lex_fuse(sb, personal, f, cut), _E_W["stmt"])
        else:
            _e_add_scaled(tot, self._lex_fuse(b1, personal, f, cut), _E_W["stmt"])

        # pm: person match
        people = self.query_people(q)
        if people:
            seen = {}
            pbar = None if _EXP["scale_keep_pm"] else _common_bar(len(self.by_uid))
            for p in people:
                ps = self.persons.get(p)
                if not ps:
                    continue
                if pbar is not None and len(ps) > pbar and tot:
                    for i in tot:
                        if i in ps:
                            seen[i] = None
                else:
                    for i in ps:
                        seen[i] = None
            for i in seen:
                if elig(docs[i], f, cut):
                    tot[i] = (tot.get(i) or 0) + _E_W["pm"]

        # sess: sessions score by the lexical mass of their notes
        if _E_W["sess"]:
            lex_norm = {}
            _e_add_scaled(lex_norm, b1, 1)
            sess_score = {}
            for i, s in lex_norm.items():
                sess = docs[i].sess
                sess_score[sess] = (sess_score.get(sess) or 0) + s
            mx = 0
            for s in sess_score.values():
                if s > mx:
                    mx = s
            if mx > 0:
                for sess, s in sess_score.items():
                    m = self.members.get(sess)
                    if not m or len(m) > _E_SESS_CAP:
                        continue
                    for i in m:
                        if elig(docs[i], f, cut):
                            tot[i] = (tot.get(i) or 0) + (_E_W["sess"] * s) / mx

        # date x topic boost for relative phrases, after fusion
        final = {}
        _e_add_scaled(final, tot, 1)
        if _e_is_relative_date_query(q):
            for base in self._bases(now_ms):
                win = _e_relative_window(q, base)
                if win is None:
                    break
                idxs = [i for i in self._docs_on_days(win[0], win[1]) if elig(docs[i], f, cut)]
                if not idxs:
                    continue
                qt = set(t for t in _e_tokenize(q) if len(t) > 2)
                for w in _E_REL_DROP:
                    qt.discard(_e_stem(w))
                    qt.discard(w)
                boost = {}
                for i in idxs:
                    ov = 0
                    for t in docs[i].tf:
                        if t in qt:
                            ov += 1
                    boost[i] = min(1, 0.15 + 0.25 * ov) if qt else 0.15
                _e_add_scaled(final, boost, _E_W["date"])
                break

        rows = [(i, s) for i, s in final.items() if docs[i] is not None and docs[i].parent < 0]
        rows.sort(key=lambda r: (-r[1], r[0]))
        return [(docs[i].uid, s) for i, s in rows[:int(top_n)]], typo_fixed

    def stats(self):
        return {"notes": len(self.by_uid), "docs": self.N, "terms": len(self.post), "grams": len(self.grams)}

# ---- answer builder additions: preference-safe context rule ------------------------------------------------
_TIP_Q = _jsre(r"\b((any|some)\s+)?(tips?|advice|suggestions?|recommendations?|ideas)\b|\b(can|could)\s+you\s+(suggest|recommend|give)\b|\bdo\s+you\s+(have|think)\b|\brecommend\b", re.I)
_PREF_OR_TIP_Q = _jsre(r"\b(favorite|favourite|prefer|preference|like to|love to|tips?|advice|recommend(?:ations?)?|suggestions?|suggest(?:ions?)?|any (helpful )?tips|helpful tips|do you have any|can you suggest|what do you think|do you think|good idea|meal prep|theme park|helpful)\b", re.I)
_PREF_CUE = _jsre(r"\b(i\s+(?:just\s+)?(?:got|bought|purchased|prefer|like|love|enjoy|have\s+been|tried)|i'?m\s+(?:a|an|into|planning|considering|thinking\s+of)|i\s+recently|my\s+(?:new|favorite|favourite)|i'?ve\s+been)\b", re.I)

def _is_tip_q(q):  # answer builder isTipQ()
    return bool(_TIP_Q.search(q or ""))

def _is_pref_or_tip(q):  # answer builder isPrefOrTip()
    return _is_tip_q(q) or bool(_PREF_OR_TIP_Q.search(q or ""))

def _is_own_preference(text):  # answer builder isOwnPreference()
    return bool(_PREF_CUE.search(text or ""))

def _pack_order(q):  # answer builder packOrder()
    return "relevance" if _is_tip_q(q) else "hits-first"

def _select_for_budget(lines, budget, query, is_pref):  # answer builder selectForBudget(): indexes in the original order
    keep = []
    if not _is_pref_or_tip(query):
        size = 0
        for i, ln in enumerate(lines):
            n = _jlen(ln)
            if size + n + 1 > budget and keep:
                break
            keep.append(i)
            size += n + 1
        return keep
    chosen = {}
    size = 0
    for pas in (True, False):
        for i, ln in enumerate(lines):
            if i in chosen or is_pref(i) != pas:
                continue
            n = _jlen(ln)
            if size + n + 1 > budget and chosen:
                if pas:
                    continue
                break
            chosen[i] = None
            size += n + 1
    return sorted(chosen)

# ---- the engine ----------------------------------------------------------------------------------------
_FTS_SQL =("SELECT fts.uid, notes.tier, notes.bot, notes.tags, notes.text, notes.ts, notes.src, notes.id, notes.user_key, bm25(fts) AS sc "
            "FROM fts JOIN notes ON notes.uid = fts.uid WHERE fts MATCH ? AND {where} ORDER BY sc LIMIT ?")
_LIKE_SQL = ("SELECT uid, tier, bot, tags, text, ts, src, id, user_key FROM notes WHERE {like} AND {where} "
             "ORDER BY created_ms DESC LIMIT ?")
_FTS_CLEAN = re.compile("[^A-Za-z0-9_@.+#-]")
_FTS_SPECIAL = re.compile("[@.+#]")

def _sq(s):
    """Text for the SQLite copy: lone surrogates would fail to encode."""
    return s.encode("utf-8", "replace").decode("utf-8") if _SURR.search(s) else s

class LocalEngine:
    """Local replica of one scope's store with the server's find(). Pure: callers feed rows, nothing is read or
    written here. Row shapes follow POST /v1/sync: notes {uid,tier,bot,tags,text,ts,src,id,user,rev[,created_ms]},
    facts {id,bot,user,entity,subject,predicate,object,text,ts,superseded_by,kind,src_uid},
    recall rows {scope,kind,key,hits,last_hit}, recent uids. Feed notes in the server's insert (rowid) order: the
    server ranks ties by index position, so a different order can change tie breaks."""

    def __init__(self):
        self.hot = _HotIndex()
        self.facts = []
        self.recall = _InstantRecall()
        self.recent = {}        # uid -> seconds (None when loaded without a time): rank +2 hint
        self._rep_recent = {}   # recency writes since drain_report()
        self._db = None         # lazy in-memory SQLite for the FTS5 and LIKE fallbacks
        self._fts = False
        self.secret_check = None  # optional callable(text) -> refusal string or None, set by the client

    # -- state in ---------------------------------------------------------------------------------------
    def load(self, notes, facts=None, recall_rows=None, recent_uids=None):
        self._db = None
        self.hot.load(notes)
        self.set_facts(facts or [])
        self.set_recall(recall_rows or [])
        if isinstance(recent_uids, dict):
            self.recent = dict(recent_uids)
        else:
            self.recent = dict((u, None) for u in (recent_uids or []))
        self._rep_recent = {}
        self.recall.events = []

    def upsert_note(self, n, retire_recall=False):
        """Insert or replace one note by uid (HotIndex.upsert). retire_recall=True also applies recallNoteWritten."""
        r = self.hot.upsert(n)
        if self._db:
            self._db_put(r)
        if retire_recall:
            self.note_written(r)
        return r

    def delete_uid(self, uid):  # TenantBrain.deleteNote
        ok = self.hot.remove(uid)
        if self._db:
            self._db.execute("DELETE FROM notes WHERE uid = ?", (uid,))
            if self._fts:
                self._db.execute("DELETE FROM fts WHERE uid = ?", (uid,))
        return ok

    def set_facts(self, facts):
        fl = [_normalize_fact(dict(f, user=f.get("user") or f.get("user_key") or "")) for f in facts]
        fl.sort(key=lambda f: f["id"])  # server loads ORDER BY id
        self.facts = fl

    def set_recall(self, rows):
        self.recall.load(rows)

    def note_written(self, n):  # tenant.ts recallNoteWritten(): a newer note retires hot items it replaces
        sk = _subject_key(n["text"])
        nts = _dp(n["ts"])
        for r in self.recall.top(n["user"], "note", 0):
            idx = self.hot.by_uid.get(r["key"])
            old = None if idx is None else self.hot.notes[idx]
            if not old or old["uid"] == n["uid"]:
                continue
            ots = _dp(old["ts"])
            if nts == nts and ots == ots and nts < ots:
                continue
            same_id = bool(old["id"]) and old["id"] != "NEW" and old["id"] == n["id"]
            if same_id or (sk != "subj:?" and _subject_key(old["text"]) == sk):
                self.recall.drop(n["user"], "note", r["key"])

    def refuse_secret(self, text):
        """Local pre-check on add. NOT PORTED (src/secrets.ts unreadable in this job): returns None unless the client
        installed a checker in self.secret_check. The server still refuses secrets on /v1/add."""
        return self.secret_check(text) if self.secret_check else None

    def drain_report(self, cap=200):
        """Hits and recency hints written by local finds since the last call, for POST /v1/sync {hits, recent}."""
        rep = {"hits": self.recall.events[-cap:], "recent": list(self._rep_recent)[-cap:]}
        self.recall.events = []
        self._rep_recent = {}
        return rep

    # -- SQLite fallbacks -------------------------------------------------------------------------------
    def _db_put(self, n):
        db = self._db
        cm = n.get("created_ms")
        if cm is None:
            v = _dp(n["ts"])
            cm = 0 if v != v else int(v)
        vals = (n["tier"], _sq(n["bot"]), _sq(n["tags"] or ""), _sq(n["text"]), _sq(n["ts"]), _sq(n["src"] or ""), _sq(n["id"] or ""), int(cm), _sq(n["user"] or ""))
        if db.execute("SELECT 1 FROM notes WHERE uid = ?", (n["uid"],)).fetchone():
            db.execute("UPDATE notes SET tier=?, bot=?, tags=?, text=?, ts=?, src=?, id=?, created_ms=?, user_key=? WHERE uid=?", vals + (n["uid"],))
        else:
            db.execute("INSERT INTO notes (tier, bot, tags, text, ts, src, id, created_ms, user_key, uid) VALUES (?,?,?,?,?,?,?,?,?,?)", vals + (n["uid"],))
        if self._fts:
            db.execute("DELETE FROM fts WHERE uid = ?", (n["uid"],))
            db.execute("INSERT INTO fts (uid, tier, bot, tags, text, ts, src) VALUES (?,?,?,?,?,?,?)",
                       (n["uid"], n["tier"], vals[1], vals[2], vals[3], vals[4], vals[5]))

    def _ensure_db(self):
        if self._db is not None:
            return self._db
        if _sqlite3 is None:
            self._db = False
            return False
        db = _sqlite3.connect(":memory:", check_same_thread=False)
        db.execute("CREATE TABLE notes (uid TEXT PRIMARY KEY, tier TEXT NOT NULL DEFAULT 'ws', bot TEXT NOT NULL, tags TEXT NOT NULL DEFAULT '', "
                   "text TEXT NOT NULL, ts TEXT NOT NULL, src TEXT NOT NULL DEFAULT 'ws', id TEXT NOT NULL DEFAULT '', created_ms INTEGER NOT NULL, "
                   "user_key TEXT NOT NULL DEFAULT '')")
        try:
            db.execute("CREATE VIRTUAL TABLE fts USING fts5(uid UNINDEXED, tier UNINDEXED, bot, tags, text, ts UNINDEXED, src UNINDEXED, "
                       "tokenize = 'porter unicode61')")
            self._fts = True
        except Exception:  # SQLite built without FTS5: that fallback is skipped
            self._fts = False
        self._db = db
        for i, n in enumerate(self.hot.notes):
            if self.hot.by_uid.get(n["uid"]) == i:
                self._db_put(n)
        return db

    def has_fts(self):
        self._ensure_db()
        return bool(self._db) and self._fts

    def _sql_notes(self, sql, params):
        db = self._ensure_db()
        if not db:
            return []
        try:
            rows = db.execute(sql, params).fetchall()
        except Exception:
            return []
        cols = ["uid", "tier", "bot", "tags", "text", "ts", "src", "id", "user_key"] + (["sc"] if sql.startswith("SELECT fts.uid") else [])
        out = []
        for r in rows:
            d = dict(zip(cols, r))
            d["user"] = d.get("user_key") or ""
            out.append(d)
        return out

    def _engine_pool(self, q, u, flt, allow, pool_size, extra, now):  # TenantBrain.enginePool()
        """Engine candidates. Filters apply inside the engine, before its top N. Note q is the raw query: the server
        runs parseQuery(q).free here, while the filters come from the rewritten query."""
        f = {"user": u or None, "bot": _slug(flt["bot"]) if flt["bot"] else None, "tag": flt["tag"], "tiers": allow,
             "minTsMs": (now - flt["age_days"] * 86400000.0) if flt["age_days"] is not None else None}
        hits, _typo = self.hot.eng.search(_parse_query(q)[0], f, pool_size, extra=extra, now_ms=now)
        return [h[0] for h in hits], [h[1] for h in hits], True

    # -- tenant.ts instantCandidates / hasNewerSibling ------------------------------------------------
    def _has_newer_sibling(self, n):  # TenantBrain.hasNewerSibling()
        sk = _subject_key(n["text"])
        if not re.match(r"[A-Z]+-\d", sk, re.A):
            return False
        nts = _dp(n["ts"])
        for i in self.hot.inverted.get(sk.lower(), ()):
            o = self.hot.notes[i]
            if not o or not o["text"] or o["uid"] == n["uid"] or (o["user"] or "") != (n["user"] or ""):
                continue
            if o["tier"] == "timeline" or o["tier"] == "promote" or _subject_key(o["text"]) != sk:
                continue
            if _dp(o["ts"]) > nts:
                return True
        return False

    def _instant_candidates(self, scope, words, flt, allow, now):  # TenantBrain.instantCandidates()
        out = []
        if not words:
            return out
        bslug = _slug(flt["bot"]) if flt.get("bot") else None
        tagl = flt["tag"].lower() if flt.get("tag") else None
        for r in self.recall.top(scope, "note", now):
            idx = self.hot.by_uid.get(r["key"])
            n = None if idx is None else self.hot.notes[idx]
            if (not n or not n["text"] or (n["user"] or "") != scope or n["tier"] == "timeline" or n["tier"] == "promote"
                    or self._has_newer_sibling(n)):
                self.recall.drop(scope, "note", r["key"])
                continue
            if n["tier"] not in allow:
                continue
            if bslug is not None and bslug not in n["bot"]:
                continue
            if tagl is not None and tagl not in (n["tags"] or "").lower():
                continue
            have = set(n["tokens"])
            matched = [w for w in words if w in have or _stem(w) in have]
            id_words = [w for w in words if _is_id_word(w)]
            if len(matched) < max(1, _math.ceil(len(words) * 0.6)) or any(w not in matched for w in id_words):
                continue
            out.append({"note": n, "rscore": r["score"], "full": len(matched) == len(words)})
        return out

    # -- tenant.ts TenantBrain.find() --------------------------------------------------------------------
    def find(self, q, n=5, ask_bot=None, user=None, now_ms=None):
        t0 = time.perf_counter()
        now = float(int(time.time() * 1000)) if now_ms is None else now_ms
        hot = self.hot
        rewritten, rw_expanded = _rewrite_query(q)
        free, flt = _parse_query(rewritten)
        words = _terms(free)
        u = _normalize_user(user)
        timeline = _wants_timeline(q)
        tier, _reasons = _classify_pack(q)
        budget = _PACK_BUDGET[tier]
        fact_cap = _FACT_LINE_CAP[tier]
        tiered = hot.has_ws and hot.has_lt
        try:
            nn = float(n)
        except (TypeError, ValueError):
            nn = 0.0
        if nn != nn or nn == 0:
            nn = 5.0
        limit = min(max(nn, 8), 20) if tier == "full" else min(max(nn, 1), 8)
        limit_i = int(limit)
        use_hot = len(hot.notes) > 0
        if flt["tier"]:
            allow = {flt["tier"]}
        elif timeline:
            allow = {"ws", "lt", "timeline", "promote"}
            if _EXP["dormant"]:
                allow.add("dormant")  # timeline questions reach Dormant; every other question never does
        else:
            allow = {"ws", "lt"}

        cands = self._instant_candidates(u, words, flt, allow, now)
        hot_score = dict((c["note"]["uid"], c["rscore"]) for c in cands)
        instant = any(c["full"] for c in cands) and tier != "full" and not timeline and flt["age_days"] is None
        id_words = [w for w in words if _is_id_word(w)]
        distinct = []
        for w in words:
            if len(w) >= 6 and (len(hot.inverted.get(w) or ()) or 99) <= 3:
                distinct.append(w)

        # run() ---------------------------------------------------------------------------------------
        where = ["1=1"]
        params = []
        where.append("notes.tier IN (%s)" % ",".join("?" * len(allow)))
        params.extend(allow)
        if flt["bot"]:
            where.append("notes.bot LIKE ?")
            params.append("%" + flt["bot"] + "%")
        if flt["tag"]:
            where.append("notes.tags LIKE ?")
            params.append("%" + flt["tag"].lower() + "%")
        if u:
            where.append("notes.user_key = ?")
            params.append(u)
        hits = [c["note"] for c in cands] if instant else []
        eng_scores = {}
        engine_mode = False
        if not instant and use_hot and words:
            # src/tenant.ts: the candidate pool. Single-tier stores use the lexical engine (enginePool); tiered stores
            # (ws plus lt) keep the earlier index with edit-distance spellings added. The server's QueryCache only
            # memoizes this pool, so it is not ported: a local find recomputes it and gives the same lines.
            pool = None
            if not tiered:
                try:
                    pool = self._engine_pool(q, u, flt, allow, max(limit * 4, 40), rw_expanded, now)
                except _JSError:
                    pool = None  # an engine fault never fails a find: fall through to the earlier index
            if pool is None:
                typo_words = [t for w in words for t in hot.eng.typo_terms(w)]
                exp = list(rw_expanded if rw_expanded else _expand_terms(words)) + typo_words
                found = hot.search(exp, {"bot": flt["bot"], "tag": flt["tag"], "tier": None, "user": u or None, "allowTiers": allow}, limit)
                pool = ([n["uid"] for n in found], [0] * len(found), False)
            engine_mode = pool[2]
            hits = []
            for uid, sc in zip(pool[0], pool[1]):
                eng_scores[uid] = sc
                hits.append(hot.notes[hot.by_uid[uid]])
        if not instant and not hits and words:
            parts = []
            for w in _expand_terms(words):
                clean = _FTS_CLEAN.sub("", w)
                if clean:
                    parts.append('"%s"' % clean if _FTS_SPECIAL.search(clean) else clean)
            match = " OR ".join(parts[:24])
            if match and self.has_fts():
                hits = self._sql_notes(_FTS_SQL.format(where=" AND ".join(where)), [match] + params + [int(limit * 4)])
        if not instant and use_hot and words and "ws" in allow:
            have = set(h["uid"] for h in hits)
            for w in hot.search_tier(words, "ws", {"bot": flt["bot"], "tag": flt["tag"], "user": u or None}, 12):
                if w["uid"] not in have:
                    hits.append(w)
        if not instant and cands:
            seen = set(h["uid"] for h in hits)
            hits = [c["note"] for c in cands if c["note"]["uid"] not in seen] + hits
        if not hits:
            like = "1=1"
            lp = []
            if words:
                like = " OR ".join("(text LIKE ? OR tags LIKE ?)" for _ in words)
                if _EXP["dormant"] or hot.has_dormant:  # brackets, so the tier filter reaches every word (see tenant.ts)
                    like = "(" + like + ")"
                for w in words:
                    lp.extend(["%" + w + "%", "%" + w + "%"])
            hits = self._sql_notes(_LIKE_SQL.format(like=like, where=" AND ".join(where)), lp + params + [int(limit * 4)])
        if flt["age_days"] is not None:
            cut = now - flt["age_days"] * 86400000.0
            hits = [h for h in hits if (lambda t: t != t or t >= cut)(_dp(h["ts"]))]
        if u:
            hits = [h for h in hits if (h["user"] or "") == u]
        if not timeline:
            hidden = set(f["src_uid"] for f in self.facts if f["superseded_by"] is not None and f["src_uid"] and (not u or f["user"] == u))
            hits = [h for h in hits if h["uid"] not in hidden]
        recent = self.recent
        expanded = _expand_terms(words)
        status_q = _is_status_query(words)
        subjects, newest, subj_counts = {}, {}, {}
        for h in hits:
            sk = _subject_key(h["text"] or "")
            subjects[h["uid"]] = sk
            subj_counts[sk] = subj_counts.get(sk, 0) + 1
            ms = _dp(h["ts"])
            if ms == ms:
                cur = newest.get(sk)
                if not cur or ms > cur[0]:
                    newest[sk] = (ms, h["uid"])
        matched = {}
        if tiered:
            for h in hits:
                matched[h["uid"]] = len(_matched_query_words(h["bot"], h["text"] or "", h["tags"] or "", words)) if words else 0
        ask_slug = _slug(ask_bot) if ask_bot else None
        tagl = flt["tag"].lower() if flt["tag"] else None
        scored = []
        for i, h in enumerate(hits):
            text, tags = h["text"] or "", h["tags"] or ""
            tos = _term_overlap_score(text, tags, words, expanded)
            sc = h.get("sc")
            sc = float(i) if sc is None else float(sc)
            bm = 12 / (1 + max(sc, 0)) if sc >= 0 else 12 + min(-sc, 20)
            # single-tier stores rank on the engine score; notes from other sources keep a damped word-overlap share
            if engine_mode:
                rank = _ENGINE_SCALE * eng_scores[h["uid"]] if h["uid"] in eng_scores else _OTHER_LEX * (tos + bm)
            else:
                rank = tos + bm
            sk = subjects.get(h["uid"]) or "subj:?"
            ms = _dp(h["ts"])
            if ms == ms:
                age_h = (now - ms) / 3600000
                if status_q or subj_counts.get(sk, 0) >= 2:
                    nw = newest.get(sk)
                    if nw and nw[1] == h["uid"]:
                        rank += 12
                    else:
                        rank += max(0, 4 - age_h / 48)
                else:
                    rank += max(0, 2 - age_h / 72)
            if ask_slug and _slug(h["bot"]) == ask_slug:
                rank += 3
            if h["uid"] in recent:
                rank += 2
            if tagl is not None and tagl in tags.lower():
                rank += 5
            rs = hot_score.get(h["uid"])
            if rs is not None:
                rank += min(10, 4 + 2 * _math.log2(1 + rs))
            ts_ms = ms
            id_hit = any(_has_id_word(text, w) for w in id_words)
            if h["tier"] == "ws":
                f = 0 if ts_ms != ts_ms else min(1, 2.0 ** (((-max(0, now - ts_ms)) / 3600000) / 72))
                low = (" " + tags + " " + text + " ").lower()
                rank += 6 * f
                if id_hit or any(w in low for w in distinct):
                    rank += 25 + 25 * f
            nm = matched.get(h["uid"]) or 0
            ds = 0 if (not tiered or not words or timeline) else (35 * nm + 50 if h["tier"] == "ws" else 27.5 * nm - 20)
            id_tier = (2 if h["tier"] == "ws" else 1) if id_hit else 0
            scored.append({"rank": rank, "ds": ds, "tos": tos, "h": h, "idTier": id_tier, "tsMs": 0 if ts_ms != ts_ms else ts_ms})

        def cmp(a, b):
            d = b["idTier"] - a["idTier"]
            if _nz(d):
                return d
            if a["idTier"] == 2:
                d = b["tsMs"] - a["tsMs"]
                if _nz(d):
                    return d
            for k in ("ds", "rank", "tos"):
                d = b[k] - a[k]
                if _nz(d):
                    return d
            return 0

        scored.sort(key=_ft.cmp_to_key(cmp))
        ranked_notes = [s["h"] for s in scored[:limit_i]]
        if _pack_order(q) != "relevance":  # tip and advice questions keep the plain relevance order (answer builder)
            ranked_notes = _prefer_newest(ranked_notes, q)

        # answer: labels, budget, snippets, facts ------------------------------------------------------------
        out, used = [], []
        for h in ranked_notes:
            if h["tier"] == "lt":
                out.append("[T2 " + (h["src"] or "lt") + "] " + h["text"])
            elif h["tier"] == "timeline" or h["tier"] == "promote":
                out.append("[timeline] " + h["bot"] + " | " + h["text"])
            elif h["tier"] == "dormant":
                out.append("[older] " + h["bot"] + " | " + h["text"])
            else:
                out.append("[T1 working-set] " + h["bot"] + " | " + h["text"])
            used.append(h["uid"])
        fact_view = [f for f in self.facts if _slug(flt["bot"] or "") in f["bot"]] if flt["bot"] else self.facts
        fact_hits = _fact_matches(fact_view, q, u or None)[:fact_cap]
        if not out and not fact_hits:
            out.append("NOT FOUND in working sets or long-term BRAIN. Check the live source, else say you don't know. Do not guess.")
        # Notes come back whole, with the date they carry: no line is cut to a window (src/tenant.ts, selectForBudget only).
        keep = _select_for_budget(out, budget, q, lambda i: i < len(ranked_notes) and _is_own_preference(ranked_notes[i]["text"]))
        body = [out[i] for i in keep]
        body_notes = [ranked_notes[i] for i in keep if i < len(ranked_notes)]
        top = body_notes[0] if body_notes else None
        top_direct = bool(top) and top["tier"] == "ws" and any(_has_id_word(top["text"] or "", w) for w in id_words)
        keep_order = (not top) or top["tier"] != "ws" or _past_cue(q)
        lead, late = [], []
        for f in fact_hits:
            older = (not keep_order) and (top_direct or f["ts"] < top["ts"])
            (late if older else lead).append(_fact_line(f))
        body = lead + ([body[0]] + late + body[1:] if (top and late) else body)
        for uid in used[:5]:
            self.recent[uid] = now / 1000
            self._rep_recent[uid] = now / 1000
        if words:
            for h in body_notes[:5]:
                self.recall.hit(u, "note", h["uid"], now)
            for f in fact_hits:
                if f["superseded_by"] is None:
                    self.recall.hit(u, "fact", str(f["id"]), now)
        ms = _js_round((time.perf_counter() - t0) * 1000 * 1000) / 1000
        body.append("(%s ms, %d bytes)" % (_js_num_str(ms), sum(_jlen(l) for l in body)))
        nbytes = sum(_jlen(l) for l in body)  # like the server: the returned bytes field counts the trailer line too
        return {"lines": body, "ms": ms, "bytes": nbytes, "path": "hot" if use_hot else "fts", "pack_tier": tier, "instant": instant}

# ======================================================================================================
# END LOCAL FIND ENGINE
# ======================================================================================================

# ======================================================================================================
# LOCAL REPLICA, SEARCH LAYER AND SYNC DAEMON (local-first hosted B.R.A.I.N., job C). See docs/local-sync.md.
# Layers: (1) search layer registry (BRAIN_LOCAL_ENGINE), (2) sealed replica store (replica.db), (3) Replica
# runtime (integrity, engine load, outbox overlay), (4) stdlib WebSocket client, (5) the sync daemon and its local
# socket, (6) client helpers used by find/add/brain-mcp. Stdlib only. The replica store knows nothing about the
# engine, so another engine can plug in through register_engine().
# ======================================================================================================
import base64 as _b64, socket as _socket, struct, threading as _thr
try:
    import ssl as _ssl
except ImportError:  # no TLS: only plain http hosts (local dev) can use the WebSocket
    _ssl = None

# Must equal FIND_ENGINE in src/tenant.ts. A different server ranking means local answers could differ: then the
# daemon stops answering locally (the server answers) until a client with the matching engine is installed.
LOCAL_RANK_VERSION = "hosted-20261114b"
LOCAL_FRESH_S = 120      # answer locally while the last successful server contact is younger than this
HEARTBEAT_S = 60         # sync even with no change ping (re-auth + lease renewal)
POLL_S = 3               # sync interval while the WebSocket keeps failing
WS_PING_S = 30
_QUIET = [False]         # the daemon must not feed note_error(): being offline is not an update failure

def local_enabled():
    return os.environ.get("BRAIN_LOCAL", "1").strip().lower() not in ("0", "false", "no", "off") and _sqlite3 is not None and _AESGCM is not None

def _now_ms():
    return int(time.time() * 1000)

# ---- (1) pluggable search layer ------------------------------------------------------------------------
ENGINE_METHODS = ("load", "upsert_note", "delete_uid", "set_facts", "set_recall", "find", "drain_report")

class HostedEngine(LocalEngine):
    """Default engine "hosted": the Python port of the server find (LocalEngine)."""
    name = "hosted"

    def set_recent(self, uids):
        for u in uids or []:
            self.recent.setdefault(u, None)

_ENGINES = {"hosted": HostedEngine}

def register_engine(name, factory):
    """Plug in another local search engine. factory() returns an object with a `name` attribute and the methods
    in ENGINE_METHODS (load(notes, facts, recall_rows, recent_uids), upsert_note(n), delete_uid(uid), set_facts(f),
    set_recall(rows), find(q, n, ask_bot) -> {lines, ...}, drain_report() -> {hits, recent}); set_recent(uids) is
    optional. BRAIN_LOCAL_ENGINE=<name> selects it."""
    _ENGINES[str(name).strip().lower()] = factory

def make_engine(allow_embed=False):
    """allow_embed: only the daemon runs the local search model (a one-off CLI process never starts it)."""
    want = os.environ.get("BRAIN_LOCAL_ENGINE", "").strip().lower() or ("embed" if allow_embed and embed_wanted() else "hosted")
    if want == "embed" and not allow_embed:
        want = "hosted"
    try:
        eng = _ENGINES[want]()
        if all(callable(getattr(eng, m, None)) for m in ENGINE_METHODS):
            return eng
    except Exception:
        pass
    return HostedEngine()

# ---- (1b) optional local search model ("embed": the bge-small hybrid) ----------------------------------------
# Opt out with BRAIN_EMBED=0 or `brain embed off`. The daemon installs it once in the background: a private venv
# under the cache dir with numpy, onnxruntime and tokenizers, the engine code from the host (sha256 pinned below)
# and the 65 MB bge-small model from Hugging Face (sha256 pinned). Until it is ready, or whenever it fails, finds use
# the hosted engine above. Notes never leave this computer for it. Answers can differ from the server's; the
# server stays the source of truth.
EMBED_VERSION = "e2"  # e2: turn ids are read from the note text when the id field is NEW
EMBED_CODE_SHA = "2ccb8b6e9b383413a37a1f62f4d79254b12fbc56c80e01952c9b39f17b8588a4"
EMBED_PIP = ("numpy>=1.24,<3", "onnxruntime>=1.17,<2", "tokenizers>=0.15,<1")
EMBED_MODEL_URL = "https://huggingface.co/Qdrant/bge-small-en-v1.5-onnx-Q/resolve/aa8f8b060edb00e03bfdd08813a2949946c8ba55/"
EMBED_MODEL_FILES = {
    "tokenizer.json": "d241a60d5e8f04cc1b2b3e9ef7a4921b27bf526d9f6050ab90f9267a1f9e5c66",
    "model_optimized.onnx": "51f1bd0addd6e859e42c2c8021a5e5461385bb676a649f4b269aa445449f2431",
}
EMBED_RETRY_S = 6 * 3600
EMBED_LOCK_WAIT_S = 15 * 60

def embed_home():
    """The model install (venv, code, model files): no notes in it, so every team on this computer shares one."""
    return cache_dir() / "embed"

def embed_team_home():
    """The worker's state dir: the vectors of ONE team's notes. Never shared between teams."""
    return C / "embed-state"

def embed_wanted():
    if os.environ.get("BRAIN_EMBED", "1").strip().lower() in ("0", "false", "no", "off"):
        return False
    return not (embed_home() / "off").exists()

def _embed_py(home):
    return home / "venv" / ("Scripts/python.exe" if os.name == "nt" else "bin/python")

def embed_state():
    try:
        return json.loads((embed_home() / "state.json").read_text())
    except Exception:
        return {}

def _embed_save(st):
    h = embed_home()
    h.mkdir(parents=True, exist_ok=True)
    tmp = h / "state.json.tmp"
    tmp.write_text(json.dumps(st))
    os.replace(str(tmp), str(h / "state.json"))

def embed_installed():
    st, h = embed_state(), embed_home()
    return (st.get("ok") is True and st.get("version") == EMBED_VERSION and _embed_py(h).exists()
            and (h / "code" / "brain_embed_worker.py").exists() and all((h / "model" / f).exists() for f in EMBED_MODEL_FILES))

def _sha_file(p):
    d = hashlib.sha256()
    with open(str(p), "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""):
            d.update(b)
    return d.hexdigest()

def _download(url, dest, sha, timeout=120):
    """Stream url to dest; keep it only when its sha256 matches."""
    tmp = pathlib.Path(str(dest) + ".part")
    r = urllib.request.Request(url, headers={"User-Agent": "brain-hosted/%s" % VERSION})
    d = hashlib.sha256()
    with urllib.request.urlopen(r, timeout=timeout) as resp, open(str(tmp), "wb") as f:
        for b in iter(lambda: resp.read(1 << 20), b""):
            d.update(b)
            f.write(b)
    if d.hexdigest() != sha:
        _unlink_quiet(tmp)
        raise RuntimeError("checksum mismatch for " + url.rsplit("/", 1)[-1])
    os.replace(str(tmp), str(dest))

def _du(p):
    tot = 0
    for root, _d, files in os.walk(str(p)):
        for f in files:
            try:
                tot += os.lstat(os.path.join(root, f)).st_size
            except OSError:
                pass
    return tot

_EMBED_LAST_ERROR = ""

def _embed_fail(reason, step="start", log=None):
    """Persist a reason on every failed install path, then return False. Never raises."""
    global _EMBED_LAST_ERROR
    msg = (reason or "unknown error")[:400]
    _EMBED_LAST_ERROR = msg
    try:
        _embed_save({"ok": False, "version": EMBED_VERSION, "failed_at": time.time(), "step": step, "error": msg})
    except Exception:
        pass
    if log:
        log("local search model not installed (%s); the built-in engine answers" % msg)
    return False


def embed_install(cfg=None, force=False, log=None):
    """Install the local search model once. Returns True when it is ready. Never raises."""
    import subprocess, tarfile
    log = log or (lambda m: None)
    h = embed_home()
    try:
        h.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        return _embed_fail("could not create the install folder: %s" % e, "mkdir", log)
    if embed_installed() and not force:
        return True
    st = embed_state()
    if not force and st.get("version") == EMBED_VERSION and st.get("failed_at") and time.time() - st["failed_at"] < EMBED_RETRY_S:
        if not st.get("error"):
            return _embed_fail("install recently failed, waiting to retry", st.get("step") or "retry", log)
        return False
    lock = _FileLock(h / "install.lock", stale=3600)
    if not lock.acquire(0.0):
        log("local search model: install already in progress, waiting")
        end = time.time() + EMBED_LOCK_WAIT_S
        got = False
        while time.time() < end:
            if embed_installed():
                return True
            if lock.acquire(0.5):
                got = True
                break
        if not got:
            if embed_installed():
                return True
            return _embed_fail("install already in progress", "lock", log)
        # Another install finished while we waited: do not redo it.
        if embed_installed():
            lock.release()
            return True
    t0, step = time.time(), "start"
    try:
        cfg = cfg or load_cfg()
        py = _embed_py(h)
        quiet = {"stdin": subprocess.DEVNULL, "stdout": subprocess.DEVNULL, "stderr": subprocess.PIPE}
        if not py.exists():
            step = "venv"
            log("local search model: creating its private Python environment")
            r = subprocess.run([sys.executable, "-m", "venv", str(h / "venv")], timeout=600, **quiet)
            if r.returncode != 0 or not py.exists():
                raise RuntimeError("python venv failed: " + (r.stderr or b"").decode("utf-8", "replace")[-200:])
        step = "packages"
        log("local search model: installing numpy, onnxruntime and tokenizers")
        r = subprocess.run([str(py), "-m", "pip", "install", "--disable-pip-version-check", "--no-input", "-q",
                            "--only-binary=:all:"] + list(EMBED_PIP), timeout=1800, **quiet)
        if r.returncode != 0:
            raise RuntimeError("pip failed: " + (r.stderr or b"").decode("utf-8", "replace")[-300:])
        step = "code"
        url = (cfg.get("url") or "").rstrip("/")
        if not url:
            raise RuntimeError("not configured")
        tgz = h / ("brain-embed-%s.tar.gz" % EMBED_VERSION)
        if not tgz.exists() or _sha_file(tgz) != EMBED_CODE_SHA:
            _download(url + "/client/embed/brain-embed-%s.tar.gz" % EMBED_VERSION, tgz, EMBED_CODE_SHA)
        new = h / "code.new"
        shutil.rmtree(str(new), ignore_errors=True)
        new.mkdir()
        with tarfile.open(str(tgz), "r:gz") as tf:
            for m in tf.getmembers():
                nm = m.name
                if nm.startswith("/") or ".." in nm.split("/") or not (m.isfile() or m.isdir()):
                    raise RuntimeError("unexpected entry in the engine archive")
            tf.extractall(str(new))
        old = h / "code"
        shutil.rmtree(str(old), ignore_errors=True)
        os.replace(str(new), str(old))
        step = "model"
        md = h / "model"
        md.mkdir(exist_ok=True)
        for f, sha in EMBED_MODEL_FILES.items():
            p = md / f
            if p.exists() and _sha_file(p) == sha:
                continue
            log("local search model: downloading " + f)
            _download(EMBED_MODEL_URL + f, p, sha, timeout=300)
        step = "check"
        w = _EmbedWorker(h)
        try:
            ok = w.call({"op": "load", "notes": [{"uid": "t1", "tier": "ws", "bot": "check", "text": "the blue kettle is in the attic", "ts": "2026-01-01T00:00:00Z", "id": "NEW"},
                                                  {"uid": "t2", "tier": "ws", "bot": "check", "text": "dinner is at seven on friday", "ts": "2026-01-01T00:00:00Z", "id": "NEW"}]}, 300)
            fr = w.call({"op": "find", "q": "where is the kettle", "n": 1}, 60)
        finally:
            w.close()
        if not (ok and ok.get("ok") is not False and fr and fr.get("ok") and fr.get("uids", [None])[0] == "t1"):
            raise RuntimeError("engine check failed: %s" % (fr or ok,))
        shutil.rmtree(str(embed_team_home() / "state" / "team"), ignore_errors=True)
        _embed_save({"ok": True, "version": EMBED_VERSION, "installed_at": time.time(), "install_s": round(time.time() - t0, 1),
                     "bytes": _du(h)})
        log("local search model ready (%.0f s, %d MB)" % (time.time() - t0, _du(h) / 1e6))
        return True
    except Exception as e:
        _embed_save({"ok": False, "version": EMBED_VERSION, "failed_at": time.time(), "step": step,
                     "error": ("%s: %s" % (type(e).__name__, e))[:400]})
        log("local search model not installed (%s: %s); the built-in engine answers" % (step, type(e).__name__))
        return False
    finally:
        lock.release()

class _EmbedWorker:
    """The model worker process (JSON lines on stdin/stdout). One request at a time; a find never waits behind a
    long load: it gives up at once and the built-in engine answers."""
    def __init__(self, home):
        import subprocess, queue
        env = dict(os.environ, BRAIN_EMBED_HOME=str(embed_team_home()), BRAIN_EMBED_MODEL_DIR=str(home / "model"), PYTHONDONTWRITEBYTECODE="1")
        env.pop("PYTHONPATH", None)
        kw = {"stdin": subprocess.PIPE, "stdout": subprocess.PIPE, "stderr": subprocess.DEVNULL, "env": env, "close_fds": True}
        if os.name == "nt":
            kw["creationflags"] = 0x08000000  # CREATE_NO_WINDOW
        self.p = subprocess.Popen([str(_embed_py(home)), "-u", str(home / "code" / "brain_embed_worker.py")], **kw)
        self.q = queue.Queue()
        self.lock = _thr.Lock()
        t = _thr.Thread(target=self._read, daemon=True)
        t.start()

    def _read(self):
        try:
            for line in self.p.stdout:
                self.q.put(line)
        except Exception:
            pass
        self.q.put(None)

    def alive(self):
        return self.p.poll() is None

    def call(self, req, timeout, wait_lock=True):
        import queue
        if not self.lock.acquire(True if wait_lock else False):
            return None
        try:
            if not self.alive():
                return None
            self.p.stdin.write((json.dumps(req) + "\n").encode("utf-8"))
            self.p.stdin.flush()
            try:
                line = self.q.get(timeout=timeout)
            except queue.Empty:
                self.close()  # a late answer would pair with the next request
                return None
            return json.loads(line) if line else None
        except Exception:
            return None
        finally:
            self.lock.release()

    def close(self):
        try:
            self.p.kill()
        except Exception:
            pass

def _embed_note(n, order):
    d = {k: n.get(k) for k in ("uid", "tier", "bot", "text", "ts", "id")}
    d["o"] = order  # the replica's insert order: the model groups neighbouring turns by it
    return d

class EmbedEngine(HostedEngine):
    """The built-in engine plus the local search model. Feeds every note to the worker and ranks with it once it is
    loaded; any filter, timeline question, worker fault or slow answer falls back to the built-in find."""
    name = "embed"

    def __init__(self):
        HostedEngine.__init__(self)
        self._w = None
        self._ready = False
        self._full = True
        self._pend = {}
        self._ev = _thr.Event()
        self._stop = False
        self.embed_error = None
        self.embed_answers = 0
        t = _thr.Thread(target=self._pump, daemon=True)
        t.start()

    def close(self):
        self._stop = True
        self._ev.set()
        if self._w is not None:
            self._w.close()

    def load(self, notes, facts=None, recall_rows=None, recent_uids=None):
        HostedEngine.load(self, notes, facts, recall_rows, recent_uids)
        self._full = True
        self._ev.set()

    def upsert_note(self, n, retire_recall=False):
        r = HostedEngine.upsert_note(self, n, retire_recall)
        self._pend[r["uid"]] = _embed_note(r, self.hot.by_uid.get(r["uid"], len(self.hot.notes)))
        self._ev.set()
        return r

    def delete_uid(self, uid):
        ok = HostedEngine.delete_uid(self, uid)
        self._pend[uid] = None
        self._ev.set()
        return ok

    def _pump(self):
        next_try = 0.0
        while not self._stop:
            self._ev.wait(5)
            self._ev.clear()
            if self._stop:
                return
            if not embed_wanted():
                self._ready = False
                continue
            if not embed_installed():
                if time.time() < next_try:
                    continue
                next_try = time.time() + 600
                if not embed_install(log=_dlog):
                    self.embed_error = (embed_state().get("error") or "not installed")[:200]
                    continue
            if self._w is None or not self._w.alive():
                self._ready = False
                try:
                    self._w = _EmbedWorker(embed_home())
                except Exception as e:
                    self.embed_error = "worker: " + type(e).__name__
                    self._ready = False
                    time.sleep(30)
                    continue
                self._full = True
            if self._full:
                self._ready = False
                self._full, self._pend = False, {}
                snap = [_embed_note(r, i) for i, r in enumerate(list(self.hot.notes))]
                res = self._w.call({"op": "load", "notes": snap}, 3600)
                self._ready = bool(res and res.get("ok") is not False)
                if not self._ready:
                    self.embed_error = "load: %s" % ((res or {}).get("error") or "no answer")
                    self._full = True
                    time.sleep(10)
                    self._ev.set()
                continue
            if self._pend:
                time.sleep(0.3)  # batch a burst of adds into one update
                pend, self._pend = self._pend, {}
                ups = [v for v in pend.values() if v]
                dels = [k for k, v in pend.items() if v is None]
                ok = True
                if ups:
                    ok = bool(self._w.call({"op": "upsert", "notes": ups}, 600))
                if dels and ok:
                    ok = bool(self._w.call({"op": "delete", "uids": dels}, 600))
                if not ok:
                    self._full = True
                    self._ev.set()

    def status(self):
        return {"engine": "embed" if self._ready else "hosted", "installed": embed_installed(), "wanted": embed_wanted(),
                "ready": self._ready, "pending": len(self._pend), "error": self.embed_error, "answers": self.embed_answers}

    def find(self, q, n=5, ask_bot=None, user=None, now_ms=None):
        w = self._w
        if not (self._ready and w is not None and not self._pend and not self._full and w.alive()) or not embed_wanted():
            return HostedEngine.find(self, q, n, ask_bot, user, now_ms)
        t0 = time.perf_counter()
        rewritten, _x = _rewrite_query(q)
        free, flt = _parse_query(rewritten)
        if any(v is not None for v in flt.values()) or not _terms(free):
            return HostedEngine.find(self, q, n, ask_bot, user, now_ms)
        try:
            nn = max(1, min(int(n), 20))
        except (TypeError, ValueError):
            nn = 5
        # replaced values (timeline) answer only a question about the past, like the built-in engine
        past = _wants_timeline(q)
        hot = self.hot
        # Ask for exactly n, like the approved local engine (the ranking depends on n); only when a hit is dropped as
        # superseded or dormant, ask once more with room for replacements.
        for ask in ((nn,) if past else (nn, nn + 10)):
            res = w.call({"op": "find", "q": q, "n": ask}, 2.0, wait_lock=False)
            if not res or not res.get("ok") or res.get("warming"):
                return HostedEngine.find(self, q, n, ask_bot, user, now_ms)
            picked = []
            for uid in res.get("uids") or []:
                i = hot.by_uid.get(uid)
                tr = hot.notes[i]["tier"] if i is not None else ""
                if i is not None and (past or tr != "timeline") and (tr != "dormant" or (past and _EXP["dormant"])):
                    picked.append(hot.notes[i])
            if len(picked) >= min(nn, len(res.get("uids") or [])):
                break
        if not picked:
            return HostedEngine.find(self, q, n, ask_bot, user, now_ms)
        now = float(int(time.time() * 1000)) if now_ms is None else now_ms
        u = _normalize_user(user)
        out = []
        for f in _fact_matches(self.facts, q, u or None)[:2]:
            if f["superseded_by"] is None:
                out.append(_fact_line(f))
        for h in picked[:nn]:
            if h["tier"] == "lt":
                out.append("[T2 " + (h["src"] or "lt") + "] " + h["text"])
            elif h["tier"] in ("timeline", "promote"):
                out.append("[timeline] " + h["bot"] + " | " + h["text"])
            else:
                out.append("[T1 working-set] " + h["bot"] + " | " + h["text"])
        for h in picked[:5]:
            self.recent[h["uid"]] = now / 1000
            self._rep_recent[h["uid"]] = now / 1000
            self.recall.hit(u, "note", h["uid"], now)
        self.embed_answers += 1
        ms = _js_round((time.perf_counter() - t0) * 1000 * 1000) / 1000
        out.append("(%s ms, %d bytes)" % (_js_num_str(ms), sum(_jlen(l) for l in out)))
        return {"lines": out, "ms": ms, "bytes": sum(_jlen(l) for l in out), "path": "embed", "pack_tier": "embed", "instant": False}

_ENGINES["embed"] = EmbedEngine

# ---- (2) sealed replica store ---------------------------------------------------------------------------
# Seal: AES-256-GCM (cryptography package), random 12-byte nonce, the row id as AAD, so a blob moved to another row
# fails. Old r1 blobs (SHAKE-256 keystream + HMAC) are read once and rewritten as r2 by ReplicaStore.load_all; the
# old cipher is never written. Without the package there is no local copy at all.
# Light protection like the offline cache: it stops casual copying of replica.db, not a person who controls the
# user account. There is no export or dump command.
_R_V = b"r2"
_R_V_OLD = b"r1"

class ReplicaCorrupt(Exception):
    pass

def _replica_key(rk):
    return hashlib.sha256(b"brain-replica|" + str(rk).encode()).digest()

def _replica_key_id(rk):
    return hashlib.sha256(b"brain-replica-id|" + str(rk).encode()).hexdigest()[:16]

def _r_keys(key):  # old r1 format, read only
    return (hmac.new(key, b"brain-replica-enc", hashlib.sha256).digest(),
            hmac.new(key, b"brain-replica-mac", hashlib.sha256).digest())

def _r_aes_key(key):
    return hmac.new(key, b"brain-replica-aes-256-gcm", hashlib.sha256).digest()

def _xor_bytes(a, b):
    n = len(a)
    return b"" if not n else (int.from_bytes(a, "big") ^ int.from_bytes(b, "big")).to_bytes(n, "big")

def replica_is_legacy(blob):
    return bytes(blob)[:2] == _R_V_OLD

def replica_seal(data, key, aad=b""):
    """Always the new format. Raises RuntimeError without the cryptography package."""
    _need_aes()
    nonce = secrets.token_bytes(12)
    return _R_V + nonce + _AESGCM(_r_aes_key(key)).encrypt(nonce, bytes(data), b"brain-replica|" + aad)

def replica_open(blob, key, aad=b""):
    """Raises ValueError on a wrong key, any tampering, or a blob moved to another row (aad)."""
    _need_aes()
    blob = bytes(blob)
    if not key or len(blob) < 2 + 12 + 16:
        raise ValueError("unreadable replica entry")
    if blob[:2] == _R_V_OLD:
        if len(blob) < 2 + 16 + 32:
            raise ValueError("unreadable replica entry")
        ek, mk = _r_keys(key)
        head, tag = blob[:-32], blob[-32:]
        if not hmac.compare_digest(tag, hmac.new(mk, aad + b"|" + head, hashlib.sha256).digest()):
            raise ValueError("replica entry failed authentication")
        body = head[18:]
        return _xor_bytes(body, hashlib.shake_256(ek + head[2:18]).digest(len(body)))
    if blob[:2] != _R_V:
        raise ValueError("unreadable replica entry")
    try:
        return _AESGCM(_r_aes_key(key)).decrypt(blob[2:14], blob[14:], b"brain-replica|" + aad)
    except Exception:
        raise ValueError("replica entry failed authentication")

def _replica_files(path):
    p = str(path)
    return [pathlib.Path(p + s) for s in ("", "-wal", "-shm", "-journal")]

def _unlink_quiet(p):
    try:
        pathlib.Path(p).unlink()
    except FileNotFoundError:
        pass
    except OSError:
        pass

def replica_wipe(cdir):
    """Remove replica.db (+wal/shm/journal), a half-built replica.db.tmp, and replica.key."""
    cdir = pathlib.Path(cdir)
    for base in (cdir / "replica.db", cdir / "replica.db.tmp"):
        for f in _replica_files(base):
            _unlink_quiet(f)
    _unlink_quiet(cdir / "replica.key")

class ReplicaStore:
    """replica.db: notes(uid PK, rev, seq, sealed payload), facts (sealed blob), recall/recent (sealed blobs) and the
    stamp row (epoch, cursor, facts_rev, count, digest, last_ok_ms, key_id). Every change is one transaction, so a
    process killed mid-write leaves the previous consistent state."""
    SCHEMA = (
        "CREATE TABLE IF NOT EXISTS notes (uid TEXT PRIMARY KEY, rev INTEGER NOT NULL, seq INTEGER NOT NULL, payload BLOB NOT NULL)",
        "CREATE TABLE IF NOT EXISTS facts (k INTEGER PRIMARY KEY CHECK (k = 1), blob BLOB NOT NULL)",
        "CREATE TABLE IF NOT EXISTS recall (k TEXT PRIMARY KEY, blob BLOB NOT NULL)",
        "CREATE TABLE IF NOT EXISTS stamp (k INTEGER PRIMARY KEY CHECK (k = 1), epoch TEXT NOT NULL, cursor INTEGER NOT NULL, "
        "facts_rev INTEGER NOT NULL, count INTEGER NOT NULL, digest TEXT NOT NULL, last_ok_ms INTEGER NOT NULL, key_id TEXT NOT NULL)",
    )
    STAMP_COLS = ("epoch", "cursor", "facts_rev", "count", "digest", "last_ok_ms", "key_id")

    def __init__(self, path):
        self.path = pathlib.Path(path)
        self.db = None
        self.before_commit = None  # test hook: called inside the transaction right before COMMIT

    def open(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        db = _sqlite3.connect(str(self.path), isolation_level=None, check_same_thread=False, timeout=15)
        try:
            db.execute("PRAGMA journal_mode=WAL")
            db.execute("PRAGMA synchronous=NORMAL")
            for s in self.SCHEMA:
                db.execute(s)
        except Exception:
            db.close()
            raise
        self.db = db
        self._lock_down()
        return self

    def close(self):
        if self.db is not None:
            try:
                self.db.close()
            except Exception:
                pass
            self.db = None

    def finalize(self):
        """Fold the WAL into the main file so one os.replace carries the whole replica."""
        self.db.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        self.db.execute("PRAGMA journal_mode=DELETE")
        self.close()

    def _lock_down(self):
        for f in _replica_files(self.path):
            try:
                os.chmod(str(f), 0o600)
            except OSError:
                pass

    def _txn(self, fn):
        db = self.db
        db.execute("BEGIN IMMEDIATE")
        try:
            out = fn(db)
            if self.before_commit:
                self.before_commit()
            db.execute("COMMIT")
        except BaseException:
            try:
                db.execute("ROLLBACK")
            except Exception:
                pass
            raise
        self._lock_down()
        return out

    def stamp(self):
        r = self.db.execute("SELECT %s FROM stamp WHERE k = 1" % ", ".join(self.STAMP_COLS)).fetchone()
        return None if not r else dict(zip(self.STAMP_COLS, r))

    def digest_count(self):
        h, c = hashlib.sha256(), 0
        for uid, rev in self.db.execute("SELECT uid, rev FROM notes ORDER BY uid"):
            h.update(("%s\x00%d\n" % (uid, rev)).encode("utf-8", "replace"))
            c += 1
        return h.hexdigest(), c

    @staticmethod
    def _seal_json(obj, key, aad):
        return replica_seal(json.dumps(obj, separators=(",", ":")).encode("utf-8", "replace"), key, aad)

    def apply(self, res, key, key_id, now_ms):
        """Apply one /v1/sync page (notes, deleted, facts, recall, recent, stamp) in a single transaction."""
        rows = [(n["uid"], int(n.get("rev") or 0), int(n.get("seq") or 0), self._seal_json(n, key, n["uid"].encode()))
                for n in (res.get("notes") or [])]
        deleted = list(res.get("deleted") or [])
        fblob = None if res.get("facts") is None else self._seal_json(res["facts"], key, b"facts")
        rblob = self._seal_json(res.get("recall") or [], key, b"recall")
        cblob = self._seal_json(res.get("recent") or [], key, b"recent")

        def work(db):
            for uid in deleted:
                db.execute("DELETE FROM notes WHERE uid = ?", (uid,))
            db.executemany("INSERT OR REPLACE INTO notes (uid, rev, seq, payload) VALUES (?,?,?,?)", rows)
            if fblob is not None:
                db.execute("INSERT OR REPLACE INTO facts (k, blob) VALUES (1, ?)", (fblob,))
            db.execute("INSERT OR REPLACE INTO recall (k, blob) VALUES ('recall', ?)", (rblob,))
            db.execute("INSERT OR REPLACE INTO recall (k, blob) VALUES ('recent', ?)", (cblob,))
            dg, cnt = self.digest_count()
            db.execute("INSERT OR REPLACE INTO stamp (k, epoch, cursor, facts_rev, count, digest, last_ok_ms, key_id) VALUES (1,?,?,?,?,?,?,?)",
                       (str(res["epoch"]), int(res["cursor"]), int(res["facts_rev"]), cnt, dg, int(now_ms), key_id))
        self._txn(work)

    def touch_ok(self, now_ms):
        self._txn(lambda db: db.execute("UPDATE stamp SET last_ok_ms = ? WHERE k = 1", (int(now_ms),)))

    def put_note(self, n, key):
        """Insert or replace one note (the /v1/add reply). Keeps the cursor: the next pull re-sends it harmlessly."""
        blob = self._seal_json(n, key, n["uid"].encode())

        def work(db):
            db.execute("INSERT OR REPLACE INTO notes (uid, rev, seq, payload) VALUES (?,?,?,?)",
                       (n["uid"], int(n.get("rev") or 0), int(n.get("seq") or 0), blob))
            dg, cnt = self.digest_count()
            db.execute("UPDATE stamp SET count = ?, digest = ? WHERE k = 1", (cnt, dg))
        self._txn(work)

    def drop_note(self, uid):
        def work(db):
            db.execute("DELETE FROM notes WHERE uid = ?", (uid,))
            dg, cnt = self.digest_count()
            db.execute("UPDATE stamp SET count = ?, digest = ? WHERE k = 1", (cnt, dg))
        self._txn(work)

    def check(self, key, key_id):
        """Startup integrity: quick_check, stamp present, key id, count and digest recomputed. -> (ok, reason)."""
        try:
            qc = self.db.execute("PRAGMA quick_check").fetchone()
            if not qc or qc[0] != "ok":
                return False, "quick_check failed"
            st = self.stamp()
            if not st:
                return False, "no stamp"
            if st["key_id"] != key_id:
                return False, "key id differs"
            dg, cnt = self.digest_count()
            if cnt != st["count"]:
                return False, "count differs from stamp"
            if dg != st["digest"]:
                return False, "digest differs from stamp"
        except _sqlite3.Error as e:
            return False, "database error: " + type(e).__name__
        return True, "ok"

    def _blob(self, table, k, aad, key, default):
        r = self.db.execute("SELECT blob FROM %s WHERE k = ?" % table, (k,)).fetchone()
        if not r:
            return default
        try:
            return json.loads(replica_open(r[0], key, aad).decode("utf-8", "replace"))
        except Exception:
            raise ReplicaCorrupt("%s failed authentication" % (aad.decode() or table))

    def load_all(self, key):
        """Decrypt everything (the decrypt check). Notes come back in seq (server insert) order."""
        notes = []
        for uid, rev, seq, blob in self.db.execute("SELECT uid, rev, seq, payload FROM notes ORDER BY seq, rev"):
            try:
                n = json.loads(replica_open(blob, key, uid.encode()).decode("utf-8", "replace"))
            except Exception:
                raise ReplicaCorrupt("a note failed authentication")
            if not isinstance(n, dict) or n.get("uid") != uid:
                raise ReplicaCorrupt("a note does not match its row")
            notes.append(n)
        out = {"notes": notes,
               "facts": self._blob("facts", 1, b"facts", key, []),
               "recall": self._blob("recall", "recall", b"recall", key, []),
               "recent": self._blob("recall", "recent", b"recent", key, []),
               "stamp": self.stamp()}
        self._upgrade_legacy(key)
        return out

    def _upgrade_legacy(self, key):
        """Rewrite every r1 blob as r2 in one transaction (best effort: a failure leaves the readable old rows)."""
        try:
            work = []
            for uid, blob in self.db.execute("SELECT uid, payload FROM notes"):
                if replica_is_legacy(blob):
                    work.append(("UPDATE notes SET payload = ? WHERE uid = ?", uid, uid.encode(), blob))
            for table, k, aad in (("facts", 1, b"facts"), ("recall", "recall", b"recall"), ("recall", "recent", b"recent")):
                r = self.db.execute("SELECT blob FROM %s WHERE k = ?" % table, (k,)).fetchone()
                if r and replica_is_legacy(r[0]):
                    work.append(("UPDATE %s SET blob = ? WHERE k = ?" % table, k, aad, r[0]))
            if not work:
                return
            sealed = [(q, k, replica_seal(replica_open(blob, key, aad), key, aad)) for q, k, aad, blob in work]

            def run(db):
                for q, k, nb in sealed:
                    db.execute(q, (nb, k))
            self._txn(run)
        except Exception:
            pass

# ---- file locks and the outbox ----------------------------------------------------------------------------
class _FileLock:
    """Advisory lock by exclusive file creation. A lock file older than `stale` seconds is taken over."""
    def __init__(self, path, stale=30):
        self.path, self.stale, self.held = pathlib.Path(path), stale, False

    def acquire(self, wait=2.0):
        end = time.time() + wait
        while True:
            try:
                fd = os.open(str(self.path), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
                os.write(fd, str(os.getpid()).encode())
                os.close(fd)
                self.held = True
                return True
            except FileExistsError:
                try:
                    if time.time() - self.path.stat().st_mtime > self.stale:
                        self.path.unlink()
                        continue
                except OSError:
                    pass
            except OSError:
                return False
            if time.time() >= end:
                return False
            time.sleep(0.02)

    def release(self):
        if self.held:
            self.held = False
            _unlink_quiet(self.path)

def _outbox_read(path):
    try:
        return [l for l in pathlib.Path(path).read_text(encoding="utf-8", errors="replace").splitlines() if l.strip()]
    except OSError:
        return []

def _outbox_rewrite(path, lines):
    """Replace the outbox atomically (temp file, fsync, os.replace): a kill mid-write keeps the old file."""
    path = pathlib.Path(path)
    tmp = path.with_name(path.name + ".tmp")
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write("".join(l + "\n" for l in lines))
        f.flush()
        os.fsync(f.fileno())
    os.replace(str(tmp), str(path))

def _outbox_remove(path, gone):
    """Drop the given lines (one occurrence each) from the outbox, keeping anything appended meanwhile."""
    lock = _FileLock(pathlib.Path(path).with_name("outbox.lock"))
    if not lock.acquire(5.0):
        return False
    try:
        cur, rest = _outbox_read(path), list(gone)
        keep = []
        for l in cur:
            if l in rest:
                rest.remove(l)
            else:
                keep.append(l)
        _outbox_rewrite(path, keep)
        return True
    finally:
        lock.release()

def _overlay_note(bot, text, t):
    """An unsent outbox line as a working-set note, so it is findable before the host confirms it."""
    b = _slug(bot) or "unknown"
    rid = text.split("|")[0].strip() or "NEW"
    raw = _dedupe(re.findall("[a-z0-9@.+#-]{3,}", text.lower()))[:16]
    tags = _enrich_tags(text, " ".join(raw))["tags"]
    uid = "ob:" + hashlib.sha1((b + "\0" + text + "\0" + repr(t)).encode("utf-8", "replace")).hexdigest()[:16]
    return {"uid": uid, "tier": "ws", "bot": b, "tags": tags, "text": text,
            "ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(t)), "src": "ws", "id": rid, "user": "",
            "rev": 0, "created_ms": int(t * 1000)}

# ---- (3) replica runtime ----------------------------------------------------------------------------------
class Replica:
    """One cache dir's replica: sealed store + engine + outbox overlay. The daemon holds one for its lifetime; the
    CLI builds one for the in-process fallback. Never raises on a bad replica: `ready` is False and `reason` says why."""
    def __init__(self, cdir):
        self.dir = pathlib.Path(cdir)
        self.db_path, self.key_path, self.outbox = self.dir / "replica.db", self.dir / "replica.key", self.dir / "outbox.jsonl"
        self.lock = _thr.RLock()
        self.store = self.engine = self.key = self.key_id = self.stamp = None
        self.ready, self.reason = False, "not loaded"
        self.db_ino, self.deep_check_at = None, 0.0
        self._ob_sig, self._ob_uids = None, set()
        self.allow_embed = False

    def read_key(self):
        try:
            return self.key_path.read_text().strip() or None
        except OSError:
            return None

    def write_key(self, rk):
        fd = os.open(str(self.key_path), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as f:
            f.write(rk)
        try:
            os.chmod(str(self.key_path), 0o600)
        except OSError:
            pass

    def close(self):
        with self.lock:
            self.ready = False
            if self.store is not None:
                self.store.close()
            if self.engine is not None and callable(getattr(self.engine, "close", None)):
                self.engine.close()
            self.store = self.engine = None
            self._ob_sig, self._ob_uids = None, set()

    def peek_stamp(self):
        """Cheap read of the stamp without loading anything (freshness test for the in-process path)."""
        if _sqlite3 is None or _AESGCM is None or not self.db_path.exists():
            return None
        s = ReplicaStore(self.db_path)
        try:
            s.open()
            return s.stamp()
        except Exception:
            return None
        finally:
            s.close()

    def load(self):
        with self.lock:
            self.close()
            if _sqlite3 is None:
                self.reason = "sqlite3 is not available"
                return False
            if _AESGCM is None:
                # No AES-256-GCM here: drop any local copy (it is rebuilt from the host) and serve from the host.
                replica_wipe(self.db_path.parent)
                self.reason = NO_AES_MSG
                return False
            rk = self.read_key()
            if not rk:
                self.reason = "no replica key"
                return False
            if not self.db_path.exists():
                self.reason = "no replica"
                return False
            kb, kid = _replica_key(rk), _replica_key_id(rk)
            store = ReplicaStore(self.db_path)
            try:
                store.open()
                ok, why = store.check(kb, kid)
                if not ok:
                    store.close()
                    self.reason = why
                    return False
                data = store.load_all(kb)
            except ReplicaCorrupt as e:
                store.close()
                self.reason = "decrypt check failed: " + str(e)
                return False
            except _sqlite3.Error as e:
                store.close()
                self.reason = "database error: " + type(e).__name__
                return False
            try:
                eng = make_engine(self.allow_embed)
                eng.load(data["notes"], data["facts"], data["recall"], data["recent"])
            except Exception as e:
                store.close()
                self.reason = "engine load failed: " + type(e).__name__
                return False
            old = self.engine
            self.store, self.engine, self.key, self.key_id, self.stamp = store, eng, kb, kid, data["stamp"]
            if old is not None and old is not eng and callable(getattr(old, "close", None)):
                old.close()
            self.ready, self.reason = True, "ok"
            try:
                self.db_ino, self.deep_check_at = os.stat(str(self.db_path)).st_ino, time.time()
            except OSError:
                self.db_ino = None
            return True

    def disk_ok(self):
        """Is replica.db still the file this process loaded, and still sound? Deleted or swapped: False at once (a stat).
        Damaged bytes: a fresh connection runs the startup checks and decrypts every row, at most once a minute."""
        try:
            if self.db_ino and os.stat(str(self.db_path)).st_ino != self.db_ino:
                return False
            if not self.db_path.exists():
                return False
        except OSError:
            return False
        if time.time() - self.deep_check_at < 60:
            return True
        self.deep_check_at = time.time()
        probe = ReplicaStore(self.db_path)
        try:
            probe.open()
            ok, _ = probe.check(self.key, self.key_id)
            if ok:
                probe.load_all(self.key)
            return ok
        except (_sqlite3.Error, ReplicaCorrupt):
            return False
        finally:
            probe.close()

    def refresh_overlay(self):
        """Keep the engine's working set in step with outbox.jsonl: unsent lines in, confirmed lines out."""
        try:
            s = self.outbox.stat()
            sig = (s.st_mtime_ns, s.st_size, getattr(s, "st_ino", 0))
        except OSError:
            sig = None
        if sig == self._ob_sig:
            return
        fresh = {}
        for line in (_outbox_read(self.outbox) if sig else []):
            try:
                row = json.loads(line)
                note = _overlay_note(str(row["bot"]), str(row["text"]), float(row.get("t") or time.time()))
            except Exception:
                continue
            fresh[note["uid"]] = note
        for uid in self._ob_uids - set(fresh):
            self.engine.delete_uid(uid)
        for uid, note in fresh.items():
            if uid not in self._ob_uids:
                self.engine.upsert_note(note)
        self._ob_uids, self._ob_sig = set(fresh), sig

    def find(self, q, n, bot=None):
        with self.lock:
            if not self.ready:
                raise RuntimeError("replica not ready: " + self.reason)
            self.refresh_overlay()
            return self.engine.find(q, n, bot)

    def find_report(self, q, n, bot=None):
        """find() plus the hits and recency hints this one find wrote, so the daemon can attribute them to the caller."""
        with self.lock:
            if not self.ready:
                raise RuntimeError("replica not ready: " + self.reason)
            self.refresh_overlay()
            r = self.engine.find(q, n, bot)
            return r, self._clean_report(self.engine.drain_report())

    @staticmethod
    def _clean_report(rep):
        hits = [h for h in rep.get("hits", []) if not str(h.get("key", "") if isinstance(h, dict) else h).startswith("ob:")]
        return {"hits": hits, "recent": [u for u in rep.get("recent", []) if not str(u).startswith("ob:")]}

    def drain_report(self):
        with self.lock:
            rep = self.engine.drain_report() if self.ready else {"hits": [], "recent": []}
        return self._clean_report(rep)

    def apply_delta(self, res, now_ms):
        """-> "ok", or "rekey" / "epoch" / "count" when the replica can no longer be trusted (caller rebuilds)."""
        with self.lock:
            if not self.ready:
                return "epoch"
            if _replica_key_id(res.get("replica_key") or "") != self.key_id:
                return "rekey"
            if str(res.get("epoch")) != self.stamp["epoch"]:
                return "epoch"
            self.store.apply(res, self.key, self.key_id, now_ms)
            eng = self.engine
            for n in sorted(res.get("notes") or [], key=lambda x: (int(x.get("seq") or 0), int(x.get("rev") or 0))):
                eng.upsert_note(n)
            for uid in res.get("deleted") or []:
                eng.delete_uid(uid)
            if res.get("facts") is not None:
                eng.set_facts(res["facts"])
            eng.set_recall(res.get("recall") or [])
            if hasattr(eng, "set_recent"):
                eng.set_recent(res.get("recent") or [])
            self.stamp = self.store.stamp()
            if res.get("count") is not None and int(res["count"]) != self.stamp["count"]:
                return "count"
            return "ok"

    def touch_ok(self, now_ms):
        with self.lock:
            if self.ready:
                self.store.touch_ok(now_ms)
                self.stamp = self.store.stamp()

    def insert_note(self, note):
        """The stored note from a 201 /v1/add reply, so the writer finds it at once."""
        with self.lock:
            if self.ready and isinstance(note, dict) and note.get("uid"):
                self.store.put_note(note, self.key)
                try:
                    self.engine.upsert_note(note, retire_recall=True)
                except TypeError:  # another engine without the retire flag
                    self.engine.upsert_note(note)
                self.stamp = self.store.stamp()

    def forget(self, uid):
        with self.lock:
            if self.ready:
                self.store.drop_note(uid)
                self.engine.delete_uid(uid)
                self.stamp = self.store.stamp()

def replica_put_direct(note):
    """No daemon running: put the /v1/add reply into replica.db directly (best effort, never raises)."""
    try:
        r = Replica(C)
        rk = r.read_key()
        if not rk or not note or not note.get("uid") or not r.db_path.exists():
            return
        s = ReplicaStore(r.db_path)
        try:
            s.open()
            st = s.stamp()
            if st and st["key_id"] == _replica_key_id(rk):
                s.put_note(note, _replica_key(rk))
        finally:
            s.close()
    except Exception:
        pass

def replica_forget_direct(uid):
    try:
        r = Replica(C)
        rk = r.read_key()
        if not rk or not r.db_path.exists():
            return
        s = ReplicaStore(r.db_path)
        try:
            s.open()
            if s.stamp():
                s.drop_note(uid)
        finally:
            s.close()
    except Exception:
        pass

def wipe_local(revoked=False, renew_url=None):
    """Revoked, suspended or purged: delete replica.db (+wal/shm), replica.key, the lease key and the offline cache.
    The outbox stays (it is the user's unsent writes) but nothing pushes it any more."""
    replica_wipe(C)
    shutil.rmtree(str(embed_team_home() / "state"), ignore_errors=True)  # the local search model's vectors of the notes
    for f in (ENC_SWR, SWR):
        _unlink_quiet(f)
    if LEASE_FILE.exists():
        le = load_lease() or {}
        _write_private(LEASE_FILE, json.dumps({"expires_at": "1970-01-01T00:00:00Z", "revoked": bool(revoked),
                                               "renew_url": renew_url or le.get("renew_url") or renew_default()}))

# ---- (4) minimal RFC 6455 client --------------------------------------------------------------------------
_WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"

# Hook added by build_vendor.py: the extra WebSocket handshake headers. The package replaces this per client
# so the upgrade request carries its own User-Agent and X-Brain-Hyper.
def _ws_ua_lines():
    return "User-Agent: brain-hosted/%s" % VERSION

class WsError(Exception):
    def __init__(self, msg, status=0):
        Exception.__init__(self, msg)
        self.status = status

def _ws_target(base):
    from urllib.parse import urlparse
    u = urlparse(base)
    tls = u.scheme == "https"
    prefix = u.path.rstrip("/") if u.path and u.path != "/" else ""
    return tls, u.hostname, u.port or (443 if tls else 80), prefix

class WsClient:
    """Handshake, masked client frames, text/close/ping/pong, fragments. recv() returns ("text", str),
    ("close", code) or None on timeout; pings are answered inside recv()."""
    def __init__(self, base, key, path="/v1/sync/ws", timeout=10.0):
        tls, host, port, prefix = _ws_target(base)
        sock = _socket.create_connection((host, port), timeout)
        try:
            if tls:
                sock = _ssl.create_default_context().wrap_socket(sock, server_hostname=host)
            nonce = _b64.b64encode(secrets.token_bytes(16)).decode()
            hostport = host if port in (80, 443) else "%s:%d" % (host, port)
            sock.settimeout(timeout)
            sock.sendall(("GET %s%s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                          "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\nAuthorization: Bearer %s\r\n"
                          "%s\r\n\r\n" % (prefix, path, hostport, nonce, key, _ws_ua_lines())).encode())
            buf = b""
            while b"\r\n\r\n" not in buf:
                d = sock.recv(4096)
                if not d:
                    raise WsError("closed during handshake")
                buf += d
                if len(buf) > 65536:
                    raise WsError("handshake reply too large")
            head, _, rest = buf.partition(b"\r\n\r\n")
            lines = head.decode("latin-1").split("\r\n")
            parts = lines[0].split(" ", 2)
            status = int(parts[1]) if len(parts) > 1 and parts[1].isdigit() else 0
            if status != 101:
                raise WsError("websocket refused (%d)" % status, status)
            hdr = dict((l.split(":", 1)[0].strip().lower(), l.split(":", 1)[1].strip()) for l in lines[1:] if ":" in l)
            want = _b64.b64encode(hashlib.sha1((nonce + _WS_GUID).encode()).digest()).decode()
            if hdr.get("sec-websocket-accept") != want:
                raise WsError("bad Sec-WebSocket-Accept")
        except BaseException:
            try:
                sock.close()
            except Exception:
                pass
            raise
        self.sock = sock
        self.buf = bytearray(rest)
        self._frag_op, self._frag = None, bytearray()
        self._wlock = _thr.Lock()
        self.closed = False

    def send_frame(self, opcode, payload=b""):
        n = len(payload)
        head = bytearray([0x80 | opcode])
        if n < 126:
            head.append(0x80 | n)
        elif n < 65536:
            head.append(0x80 | 126)
            head += _s_pk(">H", n)
        else:
            head.append(0x80 | 127)
            head += _s_pk(">Q", n)
        mask = secrets.token_bytes(4)
        body = _xor_bytes(payload, (mask * (n // 4 + 1))[:n]) if n else b""
        with self._wlock:
            self.sock.sendall(bytes(head) + mask + body)

    def send_text(self, s):
        self.send_frame(0x1, s.encode("utf-8"))

    def send_close(self, code=1000):
        try:
            self.send_frame(0x8, _s_pk(">H", code))
        except Exception:
            pass

    def _parse(self):
        b = self.buf
        if len(b) < 2:
            return None
        fin, op, masked, ln, off = b[0] & 0x80, b[0] & 0x0F, b[1] & 0x80, b[1] & 0x7F, 2
        if ln == 126:
            if len(b) < 4:
                return None
            ln, off = struct.unpack(">H", bytes(b[2:4]))[0], 4
        elif ln == 127:
            if len(b) < 10:
                return None
            ln, off = struct.unpack(">Q", bytes(b[2:10]))[0], 10
        mask = b""
        if masked:
            if len(b) < off + 4:
                return None
            mask, off = bytes(b[off:off + 4]), off + 4
        if len(b) < off + ln:
            return None
        payload = bytes(b[off:off + ln])
        del b[:off + ln]
        if masked and ln:
            payload = _xor_bytes(payload, (mask * (ln // 4 + 1))[:ln])
        return fin, op, payload

    def recv(self, timeout):
        end = time.time() + timeout
        while True:
            f = self._parse()
            if f is not None:
                fin, op, pl = f
                if op == 0x9:
                    self.send_frame(0xA, pl)
                elif op == 0x8:
                    code = struct.unpack(">H", pl[:2])[0] if len(pl) >= 2 else 1005
                    self.send_close(code if code != 1005 else 1000)
                    self.closed = True
                    return ("close", code)
                elif op in (0x0, 0x1, 0x2):
                    if op != 0:
                        self._frag_op, self._frag = op, bytearray()
                    self._frag += pl
                    if fin:
                        msg, kind = bytes(self._frag), self._frag_op
                        self._frag_op, self._frag = None, bytearray()
                        return ("text", msg.decode("utf-8", "replace")) if kind == 0x1 else ("binary", msg)
                continue
            left = end - time.time()
            if left <= 0:
                return None
            self.sock.settimeout(left)
            try:
                d = self.sock.recv(65536)
            except _socket.timeout:
                return None
            if not d:
                self.closed = True
                raise WsError("connection closed")
            self.buf += d

    def close(self):
        self.closed = True
        try:
            self.sock.close()
        except Exception:
            pass

# ---- (5) the sync daemon ------------------------------------------------------------------------------------
DAEMON_LOG = C / "braind.log"
DAEMON_SOCK = C / "braind.sock"
DAEMON_PORT = C / "braind.port"
DAEMON_PID = C / "braind.pid"
DAEMON_SPAWN = C / "braind.spawn"

class _SyncNet(Exception):
    pass

class _SyncFail(Exception):
    pass

class _SyncStop(Exception):
    pass

class _SyncKey(Exception):
    """The sync key was refused and another key of the team takes over: run the cycle again."""

def _dlog(msg):
    try:
        fd = os.open(str(DAEMON_LOG), os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o600)
        with os.fdopen(fd, "a") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(msg)[:300] + "\n")
    except OSError:
        pass

def _file_sig(p):
    try:
        s = os.stat(str(p))
        return (s.st_mtime_ns, s.st_size, getattr(s, "st_ino", 0))
    except OSError:
        return None

def _spawn_detached(args):
    import subprocess
    kw = {"stdin": subprocess.DEVNULL, "stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL, "close_fds": True}
    if os.name == "nt":
        kw["creationflags"] = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    else:
        kw["start_new_session"] = True
    subprocess.Popen([sys.executable] + args, **kw)

class Daemon:
    def __init__(self):
        self.dir = C
        self.rep = Replica(C)
        self.rep.allow_embed = True
        self.stop_evt, self.kick_evt = _thr.Event(), _thr.Event()
        self.net_lock = _thr.Lock()
        self.ws_up, self.ws_fails = False, 0
        self.need_rebuild, self.rebuilding, self.revoked = False, False, False
        self.last_ok_ms, self.attempted, self.syncing = 0, False, False
        self.rebuild_fail_at = 0.0
        self.last_req = time.time()
        self.token = secrets.token_hex(16)
        cfg = load_cfg()
        # Keys of this team, IN MEMORY ONLY (never written to disk or the log): cfg_id -> {"key", "t" verified at}.
        # tenant is the host-verified team of this dir; None (single-key use, e.g. the pip package) accepts only the start key.
        self.url, self.tenant = cfg["url"], _BIND["tenant"]
        self.keys, self.bad = {}, {}
        self.keys_lock, self.verify_lock, self.pend_lock = _thr.Lock(), _thr.Lock(), _thr.Lock()
        self.sync_cid, self.start_cid, self.nosync = None, None, set()
        self.pend = {}  # cfg_id -> {"hits": [...], "recent": [...]}: usage the host gets with the key that caused it
        if cfg.get("key"):
            ent = keys_lookup(cfg) if self.tenant else None
            self.start_cid = cfg_id(cfg)
            self._add_key(cfg, ent[2] if ent else time.time())
        self.self_sig = _file_sig(self_path())
        self.listener = None
        self.transport = None
        self.restart = False
        self.engine_ok = True
        try:
            self.idle_s = float(os.environ.get("BRAIN_DAEMON_IDLE_H", "4")) * 3600
        except ValueError:
            self.idle_s = 4 * 3600

    # -- network helpers -------------------------------------------------------------------------------
    def _wipe(self, st, res):
        """The team's copy goes: the team is inactive, or its last known key was refused. Never for a key-bound 403."""
        if st == 403 and is_key_bound_error(res):
            _dlog("key bound to another bot (403): leaving the shared replica in place")
            return
        self.revoked = True
        self.rep.close()
        wipe_local(revoked=(st == 401), renew_url=(res.get("renew_url") if isinstance(res, dict) else None))
        _dlog("key refused (%s): replica, replica key, lease and offline cache wiped" % st)
        self.stop_evt.set()
        self.kick_evt.set()

    # -- keys of this team (memory only) ------------------------------------------------------------------
    def _add_key(self, cfg, t):
        cid = cfg_id(cfg)
        with self.keys_lock:
            self.keys[cid] = {"key": cfg["key"], "t": t}
            self.bad.pop(cid, None)
            first = self.sync_cid is None
            if first:
                self.sync_cid = cid
        if first and hasattr(self, "kick_evt"):
            self.kick_evt.set()

    def _pick_sync(self):
        """The key the team sync runs with: the key that started this daemon while it works, else any other verified key."""
        with self.keys_lock:
            ok = [c for c in self.keys if c not in self.nosync]
            self.sync_cid = self.start_cid if self.start_cid in ok else (ok[0] if ok else None)
            return self.sync_cid

    def _sync_cfg(self):
        with self.keys_lock:
            e = self.keys.get(self.sync_cid) if self.sync_cid is not None else None
        return {"url": self.url, "key": e["key"]} if e else None

    def _key_refused(self, cid, st, res):
        """The host refused one key. Only that key leaves; the replica stays while another key of the team is known."""
        if st == 403 and is_key_bound_error(res):
            self.nosync.add(cid)  # fine for adds under its own bot, not usable for the team sync
            if self.sync_cid == cid:
                self._pick_sync()
            _dlog("key bound to another bot (403): nothing wiped")
            return
        with self.keys_lock:
            self.keys.pop(cid, None)
            self.nosync.discard(cid)
        if st == 401:
            keys_forget(cid)
            with self.keys_lock:
                rest = len(self.keys)
            if rest or (keys_of_team(self.dir.name) - {cid}):
                if self.sync_cid == cid:
                    self._pick_sync()
                    self.kick_evt.set()
                _dlog("one key was refused (401) and dropped; the team's other keys stay in service")
                return
        self._wipe(st, res)

    def hyper(self):
        """This daemon's Hyper speed state; also what the next host request reports in X-Brain-Hyper."""
        rep = self.rep
        ready = bool(rep.ready and not self.need_rebuild)
        s = hyper_decide(ready, self.rebuilding, self.engine_ok, self.fresh(), self.syncing or not self.attempted,
                         lease_valid(), self.last_ok_ms)
        _HYPER[0] = _hyper_header_of(s)
        return s

    def _post_sync(self, cfg, body):
        s = self.hyper()
        body["hyper"] = {"mode": s["mode"], "reason": s["reason"]}
        try:
            st, res = api("POST", "/v1/sync", cfg, body)
        except Exception as e:
            raise _SyncNet(type(e).__name__)
        if st in (401, 403):
            self._key_refused(cfg_id(cfg), st, res)
            if self.revoked:
                raise _SyncStop()
            if self._sync_cfg() is not None and cfg_id(self._sync_cfg()) != cfg_id(cfg):
                raise _SyncKey()
            raise _SyncFail("sync answered %s and no other key of the team can take over" % st)
        if st != 200 or not isinstance(res, dict) or "cursor" not in res:
            raise _SyncFail("sync answered %s" % st)
        mark = self.dir / "engine.mismatch"
        if str(res.get("engine") or "") != LOCAL_RANK_VERSION:
            if self.engine_ok:
                _dlog("server ranking engine %s differs from this client (%s): local answers off" % (res.get("engine"), LOCAL_RANK_VERSION))
            self.engine_ok = False
            try:
                _write_private(mark, str(res.get("engine") or ""))
            except Exception:
                pass
        elif not self.engine_ok or mark.exists():
            self.engine_ok = True
            _unlink_quiet(mark)
        if res.get("shared_spaces") is not None:
            note_shared_spaces(res["shared_spaces"])
        if res.get("lease"):
            try:
                save_lease(res["lease"])
            except Exception:
                pass
        return res

    def _note_report(self, cid, r):
        if not r or not (r["hits"] or r["recent"]):
            return
        with self.pend_lock:
            p = self.pend.setdefault(cid, {"hits": [], "recent": []})
            p["hits"] = (p["hits"] + r["hits"])[-200:]
            p["recent"] = (p["recent"] + r["recent"])[-200:]

    def _take_report(self, cid):
        """What the host is told with this key's next sync: its own finds' hits (the rest of the engine's, unattributed,
        goes to the sync key)."""
        self._note_report(cid, self.rep.drain_report())
        with self.pend_lock:
            return self.pend.pop(cid, None) or {"hits": [], "recent": []}

    def _flush_reports(self):
        """Usage of the other keys goes to the host with each key's own sync call (the reply is not applied). A key that
        is gone loses its report."""
        with self.pend_lock:
            cids = [c for c in self.pend if c != self.sync_cid]
        for cid in cids:
            with self.keys_lock:
                e = self.keys.get(cid)
            with self.pend_lock:
                rep = self.pend.pop(cid, None)
            if not e or not rep or not self.rep.stamp:
                continue
            st0 = self.rep.stamp
            try:
                st, res = api("POST", "/v1/sync", {"url": self.url, "key": e["key"]},
                              {"since": st0["cursor"], "epoch": st0["epoch"], "facts_rev": st0["facts_rev"], "limit": 1,
                               "hits": rep["hits"], "recent": rep["recent"]})
            except Exception:
                self._note_report(cid, rep)
                continue
            if st in (401, 403):
                self._key_refused(cid, st, res)

    def _mark_ok(self):
        self.last_ok_ms = _now_ms()

    # -- one sync cycle --------------------------------------------------------------------------------
    def _delta(self, cfg):
        rep = self.rep
        st = rep.stamp
        since, epoch, frev = st["cursor"], st["epoch"], st["facts_rev"]
        cid = cfg_id(cfg)
        report, delivered = self._take_report(cid), False
        while True:
            body = {"since": since, "epoch": epoch, "facts_rev": frev, "limit": 500}
            if not delivered:
                body["hits"], body["recent"] = report["hits"], report["recent"]
            try:
                res = self._post_sync(cfg, body)
            except (_SyncNet, _SyncKey):
                if not delivered:
                    self._note_report(cid, report)
                raise
            delivered = True
            if res.get("reset"):
                self._rebuild(cfg, "server asked for a reset")
                return
            why = rep.apply_delta(res, _now_ms())
            if why != "ok":
                self._rebuild(cfg, "replica check: " + why)
                return
            since, epoch, frev = res["cursor"], res["epoch"], res["facts_rev"]
            self._mark_ok()
            if not res.get("more"):
                return

    def _rebuild(self, cfg, why):
        """Pull everything into replica.db.tmp, then swap it in atomically. Finds go to the server meanwhile."""
        if time.time() - self.rebuild_fail_at < 5:
            return
        rep = self.rep
        _dlog("rebuild: " + why)
        self.need_rebuild, self.rebuilding = True, True
        with rep.lock:
            rep.ready = False
        tmp = self.dir / "replica.db.tmp"
        for f in _replica_files(tmp):
            _unlink_quiet(f)
        store = ReplicaStore(tmp)
        try:
            store.open()
            cid = cfg_id(cfg)
            since, rk, report, delivered = 0, None, self._take_report(cid), False
            while True:
                body = {"since": since, "epoch": "", "limit": 1000}
                if not delivered:
                    body["hits"], body["recent"] = report["hits"], report["recent"]
                try:
                    res = self._post_sync(cfg, body)
                except (_SyncNet, _SyncKey):
                    if not delivered:
                        self._note_report(cid, report)
                    raise
                delivered = True
                got = res.get("replica_key")
                if not got or (rk and got != rk):
                    raise _SyncFail("replica key missing or changed during the pull")
                rk = got
                store.apply(res, _replica_key(rk), _replica_key_id(rk), _now_ms())
                since = res["cursor"]
                if not res.get("more"):
                    if res.get("count") is not None and int(res["count"]) != store.stamp()["count"]:
                        raise _SyncFail("row count differs from the server")
                    break
            store.finalize()
            with rep.lock:
                rep.close()
                rep.write_key(rk)
                for f in _replica_files(rep.db_path):
                    _unlink_quiet(f)
                os.replace(str(tmp), str(rep.db_path))
                _lockdown_file(rep.db_path)
                if not rep.load():
                    raise _SyncFail("rebuilt replica failed its own check: " + rep.reason)
            self.need_rebuild = False
            self._mark_ok()
            _dlog("rebuild done: %d notes" % rep.stamp["count"])
        except (_SyncNet, _SyncStop, _SyncKey):
            raise
        except Exception as e:
            self.rebuild_fail_at = time.time()
            _dlog("rebuild failed: %s" % e)
            raise
        finally:
            self.rebuilding = False
            store.close()
            for f in _replica_files(tmp):
                _unlink_quiet(f)

    def _push_outbox(self, cfg=None):
        """Send pending adds, each line with the key that wrote it (its cfg id, a verified key held in memory). A line
        whose key this daemon does not hold, or that has no key id, stays for `brain outbox --push` with that bot's own
        key. A line leaves the outbox only after the host answered 201 (or refused it for good)."""
        ob = self.rep.outbox
        lines = _outbox_read(ob)
        if not lines:
            return
        plock = _FileLock(self.dir / "outbox.push.lock", stale=120)
        if not plock.acquire(0.0):
            return
        sent, rejected, skip = [], [], set()
        try:
            for line in lines:
                try:
                    row = json.loads(line)
                    payload = {"bot": row["bot"], "text": row["text"], "cid": line_cid(row, line)}
                    if row.get("space"):
                        payload["space"] = row["space"]
                    if row.get("private"):
                        payload["private"] = True
                    lcid = row.get("cfg")
                except Exception:
                    continue  # `brain outbox --push` reports unreadable lines
                with self.keys_lock:
                    e = self.keys.get(lcid) if isinstance(lcid, str) else None
                if not e or lcid in skip:
                    continue
                kcfg = {"url": self.url, "key": e["key"]}
                try:
                    st, res = api("POST", "/v1/add", kcfg, payload)
                except Exception:
                    break
                if st in (401, 403):
                    self._key_refused(lcid, st, res)  # this key's lines stay; other keys' lines still go
                    skip.add(lcid)
                    if self.revoked:
                        break
                    continue
                if st == 201 and isinstance(res, dict) and res.get("ok"):
                    sent.append(line)
                    if not res.get("space_id"):
                        self.rep.insert_note(res.get("note"))
                elif st == 400:
                    rejected.append((line, (res.get("error") if isinstance(res, dict) else str(res)) or "refused"))
                else:
                    break
        finally:
            if sent or rejected:
                _outbox_remove(ob, [l for l in sent] + [l for l, _ in rejected])
                if rejected:
                    fd = os.open(str(REJECTED), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
                    with os.fdopen(fd, "a") as f:
                        for line, why in rejected:
                            f.write(json.dumps({"line": line, "reason": why, "t": time.time()}) + "\n")
            plock.release()

    def sync_cycle(self):
        """One team sync, with the sync key: the key that started this daemon, or another verified key of the team when
        that one is refused or bound to another bot."""
        for _ in range(8):
            cfg = self._sync_cfg()
            if cfg is None:
                if not (self.keys or keys_of_team(self.dir.name)):
                    _dlog("no key left: exiting")
                    self.stop_evt.set()
                    raise _SyncStop()
                self.attempted = True  # no key in memory yet: the next bot that asks brings one
                return
            self.syncing = True
            try:
                with self.net_lock:
                    if self.rep.ready and not self.need_rebuild and not self.rep.disk_ok():
                        _dlog("replica.db was deleted, swapped or damaged on disk: rebuilding")
                        self.need_rebuild = True
                    if self.need_rebuild or not self.rep.ready:
                        self._rebuild(cfg, "replica not usable: " + self.rep.reason)
                    else:
                        self._delta(cfg)
                    if not self.revoked:
                        self._push_outbox()
                        self._flush_reports()
                return
            except _SyncKey:
                continue
            finally:
                self.syncing = False
                self.attempted = True
        raise _SyncFail("no key of the team could sync")

    def startup_check(self):
        """Integrity on start. Not usable (corrupt, missing, mismatched): finds go to the server and the first sync
        cycle rebuilds in the background. Returns True when the replica is ready to serve."""
        if self.rep.load():
            self.last_ok_ms = self.rep.stamp["last_ok_ms"]
            return True
        self.need_rebuild = True
        _dlog("replica not usable at start (%s): rebuilding" % self.rep.reason)
        return False

    def recheck_keys(self):
        """Background host check of every key this daemon holds, at most every KEY_RECHECK_S per key. Finds never wait
        on it. A key the host refuses leaves at once; a key the host now puts on another team leaves too."""
        now = time.time()
        with self.keys_lock:
            due = [(c, e["key"]) for c, e in self.keys.items() if now - e.get("rt", e["t"]) >= KEY_RECHECK_S]
        for cid, key in due:
            if self.stop_evt.is_set():
                return
            cfg = {"url": self.url, "key": key}
            try:
                st, res = api("GET", "/v1/status", cfg, timeout=10)
            except Exception:
                continue  # host not reachable: the earlier verdict stands
            if st == 200 and isinstance(res, dict) and isinstance(res.get("tenant_id"), str) and self.tenant is not None \
                    and hmac.compare_digest(res["tenant_id"].strip(), str(self.tenant)):
                with self.keys_lock:
                    if cid in self.keys:
                        self.keys[cid]["t"] = self.keys[cid]["rt"] = time.time()
            elif st in (401, 403):
                self._key_refused(cid, st, res)
            elif st == 200:
                with self.keys_lock:
                    self.keys.pop(cid, None)
                    self.bad[cid] = (time.time(), {"ok": False, "wrong_team": True})
                if self.sync_cid == cid:
                    self._pick_sync()

    def sync_loop(self):
        self.startup_check()
        while not self.stop_evt.is_set():
            try:
                self.sync_cycle()
            except _SyncStop:
                break
            except Exception as e:
                _dlog("sync cycle: %s %s" % (type(e).__name__, e))
            try:
                self.recheck_keys()
            except Exception as e:
                _dlog("key recheck: %s" % type(e).__name__)
            if self.stop_evt.is_set():
                break
            polling = (not self.ws_up) and self.ws_fails >= 3
            self.kick_evt.wait(POLL_S if polling else HEARTBEAT_S)
            self.kick_evt.clear()
            if _file_sig(self_path()) != self.self_sig:
                _dlog("client file changed: restarting")
                self.restart = True
                self.stop_evt.set()
        self.stop_evt.set()

    # -- WebSocket change pings ---------------------------------------------------------------------------
    def ws_loop(self):
        backoff = 1.0
        while not self.stop_evt.is_set():
            ws = None
            try:
                cfg = self._sync_cfg()
                if cfg is None:
                    if self.stop_evt.wait(5.0):
                        break
                    continue
                ws = WsClient(cfg["url"], cfg["key"])
                self.ws_up, self.ws_fails, backoff = True, 0, 1.0
                self.kick_evt.set()  # catch up on anything missed while the socket was down
                next_ping = time.time() + WS_PING_S
                while not self.stop_evt.is_set():
                    msg = ws.recv(max(0.1, min(1.0, next_ping - time.time())))
                    if time.time() >= next_ping:
                        ws.send_text("ping")
                        next_ping = time.time() + WS_PING_S
                    if msg is None:
                        continue
                    if msg[0] == "close":
                        if msg[1] in (4401, 4403):
                            self.kick_evt.set()  # the sync that follows gets 401/403 and wipes
                        break
                    if msg[0] == "text" and msg[1] != "pong":
                        try:
                            t = json.loads(msg[1]).get("t")
                        except Exception:
                            t = None
                        if t in ("changed", "reset"):
                            self.kick_evt.set()
            except WsError as e:
                self.ws_fails += 1
                if e.status in (401, 403):
                    self.kick_evt.set()
            except Exception:
                self.ws_fails += 1
            finally:
                self.ws_up = False
                if ws:
                    ws.close()
            if self.stop_evt.wait(backoff):
                break
            backoff = min(30.0, backoff * 2)

    # -- local socket -------------------------------------------------------------------------------------
    def _listen(self):
        use_unix = os.name != "nt" and hasattr(_socket, "AF_UNIX") and len(str(DAEMON_SOCK).encode()) < 100
        if use_unix:
            _unlink_quiet(DAEMON_SOCK)
            _unlink_quiet(DAEMON_PORT)
            old = os.umask(0o177)
            try:
                s = _socket.socket(_socket.AF_UNIX, _socket.SOCK_STREAM)
                s.bind(str(DAEMON_SOCK))
            finally:
                os.umask(old)
            try:
                os.chmod(str(DAEMON_SOCK), 0o600)
            except OSError:
                pass
            self.transport = "unix"
        else:
            _unlink_quiet(DAEMON_SOCK)
            s = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
            s.bind(("127.0.0.1", 0))
            _write_private(DAEMON_PORT, json.dumps({"port": s.getsockname()[1], "token": self.token, "pid": os.getpid()}))
            self.transport = "tcp"
        s.listen(16)
        s.settimeout(1.0)
        self.listener = s

    def _serve(self, conn):
        try:
            conn.settimeout(10)
            buf = b""
            while b"\n" not in buf and len(buf) < 1 << 20:
                d = conn.recv(65536)
                if not d:
                    break
                buf += d
            req = json.loads(buf.split(b"\n", 1)[0].decode("utf-8", "replace"))
            if self.transport == "tcp" and not hmac.compare_digest(str(req.get("token", "")), self.token):
                out = {"ok": False, "error": "bad token"}
            else:
                self.last_req = time.time()
                out = self.handle(req)
        except Exception as e:
            out = {"ok": False, "error": type(e).__name__}
        try:
            conn.sendall((json.dumps(out) + "\n").encode("utf-8"))
        except OSError:
            pass
        finally:
            try:
                conn.close()
            except OSError:
                pass

    def fresh(self):
        return self.ws_up or (_now_ms() - self.last_ok_ms) < LOCAL_FRESH_S * 1000

    def status(self):
        rep = self.rep
        st = rep.stamp or {}
        return {"ok": True, "pid": os.getpid(), "version": VERSION, "engine": getattr(rep.engine, "name", None) if rep.engine else None,
                "ready": bool(rep.ready and not self.need_rebuild), "reason": rep.reason, "rebuilding": self.rebuilding,
                "ws": self.ws_up, "fresh": self.fresh(), "last_ok_ms": self.last_ok_ms, "notes": st.get("count"),
                "cursor": st.get("cursor"), "outbox": len(_outbox_read(rep.outbox)), "transport": self.transport,
                "revoked": self.revoked, "hyper": self.hyper(), "keys": len(self.keys),
                "embed": rep.engine.status() if rep.engine is not None and callable(getattr(rep.engine, "status", None)) else None}

    def op_find(self, req, cid=None):
        q = str(req.get("q") or "").strip()
        if self.revoked:
            return {"ok": False, "reason": "revoked"}
        if not q:
            return {"ok": False, "reason": "empty query"}
        try:
            n = int(req.get("n") or 5)
        except (TypeError, ValueError):
            n = 5
        end = time.time() + 4.0  # a sync is running or has not run yet: give it a moment before calling this stale
        while not self.fresh() and (self.syncing or not self.attempted) and time.time() < end and not self.stop_evt.is_set():
            time.sleep(0.05)
        if self.revoked:
            return {"ok": False, "reason": "revoked"}
        if self.rep.ready and not self.need_rebuild and not self.rep.db_path.exists():
            self.need_rebuild = True  # file deleted under a running daemon: the server answers, a rebuild starts now
            self.kick_evt.set()
        if not self.rep.ready or self.need_rebuild:
            return {"ok": False, "reason": "not ready", "detail": self.rep.reason}
        if not self.engine_ok:
            return {"ok": False, "reason": "not ready", "detail": "server ranking engine differs"}
        fresh = self.fresh()
        if not fresh and not lease_valid():
            return {"ok": False, "reason": "license_inactive"}
        r, rep = self.rep.find_report(q, n, req.get("bot") or None)
        self._note_report(cid, rep)  # what this find used is reported to the host with this caller's key
        return {"ok": True, "lines": r["lines"], "ms": r["ms"], "path": r.get("path"), "offline": not fresh, "ws": self.ws_up,
                "ago_s": max(0, int((_now_ms() - self.last_ok_ms) / 1000)), "v": VERSION}

    def op_add(self, req, cfg):
        """POST /v1/add with the CALLER's key and bot, so the host's key rules and seat counts stay right; the stored
        note then goes into the team's shared replica."""
        if self.revoked:
            return {"ok": False, "revoked": True}
        self.hyper()
        try:
            payload = {"bot": str(req.get("bot") or ""), "text": str(req.get("text") or "")}
            if isinstance(req.get("cid"), str):
                payload["cid"] = req["cid"]
            if req.get("private"):
                payload["private"] = True
            st, res = api("POST", "/v1/add", cfg, payload)
        except Exception as e:
            return {"ok": False, "net": True, "error": type(e).__name__}
        if st in (401, 403):
            self._key_refused(cfg_id(cfg), st, res)
        elif st == 201 and isinstance(res, dict) and res.get("ok"):
            # A routing rule may have sent the note to a shared space: the local copy holds private notes only.
            if not res.get("space_id"):
                self.rep.insert_note(res.get("note"))
            self._mark_ok()
        return {"ok": True, "status": st, "res": res}

    def op_status(self, req, cfg):
        out = self.status()
        if not self.revoked:
            try:
                st, res = api("GET", "/v1/status", cfg)
                out["server"] = {"status": st, "res": res}
                if st == 200 and isinstance(res, dict) and res.get("tenant_id"):
                    remember_team(res.get("tenant_id"))
                    if isinstance(res.get("shared_spaces"), list):
                        note_shared_spaces(len(res["shared_spaces"]))
                if st in (401, 403):
                    self._key_refused(cfg_id(cfg), st, res)
            except Exception as e:
                out["server"] = {"net": True, "error": type(e).__name__}
        return out

    def _auth(self, req):
        """-> (cfg, None) for a key of THIS team, else (None, reply). The caller sends its key (only over the 0600 unix
        socket, or the token-protected 127.0.0.1 port); this daemon asks the host about it itself on first sight and
        again after KEY_REVERIFY_S or a 401/403 for it, and accepts it only when the host says it is this daemon's team.
        A team name sent by the client is never read."""
        cid, key = req.get("cfg"), req.get("auth")
        if not isinstance(cid, str) or not isinstance(key, str) or not key:
            return None, {"ok": False, "cfg_mismatch": True}
        cfg = {"url": self.url, "key": key}
        if not hmac.compare_digest(cfg_id(cfg), cid):
            return None, {"ok": False, "cfg_mismatch": True}
        now = time.time()
        with self.keys_lock:
            ent, bad = self.keys.get(cid), self.bad.get(cid)
        if ent is not None and hmac.compare_digest(ent["key"], key) and now - ent["t"] < KEY_REVERIFY_S:
            return cfg, None
        if bad is not None and now - bad[0] < 60:
            return None, bad[1]
        if self.tenant is None:  # no host-verified team for this dir: only the start key is served
            return (cfg, None) if ent is not None else (None, {"ok": False, "cfg_mismatch": True})
        with self.verify_lock:  # one host check at a time; a waiting caller re-reads the verdict
            with self.keys_lock:
                ent = self.keys.get(cid)
            if ent is not None and now - ent["t"] < KEY_REVERIFY_S:
                return cfg, None
            try:
                st, res = api("GET", "/v1/status", cfg, timeout=10)
            except Exception:
                if ent is not None:  # host not reachable: the earlier verdict stands, offline use goes on
                    return cfg, None
                return None, {"ok": False, "unverified": True, "reason": "host unreachable"}
        if st == 200 and isinstance(res, dict) and isinstance(res.get("tenant_id"), str):
            if hmac.compare_digest(res["tenant_id"].strip(), str(self.tenant)):
                self._add_key(cfg, now)
                return cfg, None
            reply = {"ok": False, "wrong_team": True}
            with self.keys_lock:
                self.keys.pop(cid, None)
                self.bad[cid] = (now, reply)
            return None, reply
        if st in (401, 403):
            self._key_refused(cid, st, res)
            if st == 401:
                return None, {"ok": False, "reason": "revoked", "revoked": True}
            if is_key_bound_error(res):
                return None, {"ok": False, "unverified": True, "reason": "key bound to another bot"}
            return None, {"ok": False, "reason": "license_inactive"}
        return None, {"ok": False, "unverified": True, "reason": "host answered %s" % st}

    def handle(self, req):
        op = req.get("op")
        if op == "ping":
            return {"ok": True, "pid": os.getpid(), "version": VERSION, "ready": bool(self.rep.ready and not self.need_rebuild), "ws": self.ws_up,
                    "keys": len(self.keys)}
        if op == "stop":
            self.stop_evt.set()
            self.kick_evt.set()
            return {"ok": True}
        if op == "restart":
            self.restart = True
            self.stop_evt.set()
            self.kick_evt.set()
            return {"ok": True}
        cfg, err = self._auth(req)
        if err is not None:
            return err
        cid = cfg_id(cfg)
        if op == "status":
            return self.op_status(req, cfg)
        if op == "hyper":
            return dict(self.hyper(), ok=True, last_ok_ms=self.last_ok_ms)
        if op == "find":
            return self.op_find(req, cid)
        if op == "add":
            return self.op_add(req, cfg)
        if op == "forget":
            self.rep.forget(str(req.get("uid") or ""))
            return {"ok": True}
        if op == "ingest":
            # Local replica only: used after a same-team add that posted with the caller's own key.
            note = req.get("note")
            if note:
                self.rep.insert_note(note)
                self._mark_ok()
            return {"ok": True}
        if op == "sync":  # run a team cycle now (any verified key of the team may ask) and answer when it is done
            try:
                self.sync_cycle()
            except _SyncStop:
                return dict(self.status(), ok=False, error="revoked" if self.revoked else "stopped")
            except _SyncNet:
                return dict(self.status(), ok=False, error="network")
            except Exception as e:
                return dict(self.status(), ok=False, error=type(e).__name__)
            try:
                self.recheck_keys()
            except Exception as e:
                _dlog("key recheck: %s" % type(e).__name__)
            return self.status()
        return {"ok": False, "error": "unknown op"}

    def run(self):
        _QUIET[0] = True
        ensure()
        try:
            if DAEMON_LOG.exists() and DAEMON_LOG.stat().st_size > 256 * 1024:
                DAEMON_LOG.unlink()
        except OSError:
            pass
        start = _FileLock(C / "braind.lock", stale=20)
        if not start.acquire(3.0):
            return 1
        try:
            if daemon_call({"op": "ping"}) is not None:
                return 0  # one daemon per cache dir
            self._listen()
        finally:
            start.release()
        _write_private(DAEMON_PID, json.dumps({"pid": os.getpid(), "version": VERSION, "started": time.time()}))
        _dlog("daemon %s started (%s)" % (VERSION, self.transport))
        for target in (self.sync_loop, self.ws_loop):
            _thr.Thread(target=target, daemon=True).start()
        while not self.stop_evt.is_set():
            try:
                conn, _ = self.listener.accept()
            except _socket.timeout:
                gone = not self.dir.exists() or not self_path().exists() or not (cfg_path().exists() or os.environ.get("BRAIN_KEY"))
                if gone or (time.time() - self.last_req) > self.idle_s:  # uninstalled, unconfigured or idle
                    self.stop_evt.set()
                continue
            except OSError:
                break
            _thr.Thread(target=self._serve, args=(conn,), daemon=True).start()
        self.kick_evt.set()
        try:
            self.listener.close()
        except Exception:
            pass
        for f in (DAEMON_SOCK, DAEMON_PORT, DAEMON_PID):
            _unlink_quiet(f)
        self.rep.close()
        _dlog("daemon stopped")
        if self.restart:
            try:
                _spawn_detached([str(self_path()), "daemon", "run"])
            except Exception:
                pass
        return 0

def _lockdown_file(p):
    try:
        os.chmod(str(p), 0o600)
    except OSError:
        pass

# ---- (6) client side of the daemon ---------------------------------------------------------------------------
def cfg_id(cfg):
    """Which host and key a request is for, without the key itself. A daemon started under another BRAIN_URL or
    BRAIN_KEY (env vars win over the config file) refuses the request, and the caller then uses its own settings."""
    return hashlib.sha256(("%s\n%s" % (cfg.get("url") or "", cfg.get("key") or "")).encode("utf-8")).hexdigest()[:16]

def remember_team(t):
    t = (t or "").strip()
    if not t or "\n" in t or len(t) >= 80:
        return
    try:
        _write_private(C / "team.id", t)
    except Exception:
        pass

def note_shared_spaces(n):
    """Remember how many shared spaces the team is in (from /v1/status or /v1/sync). Count only, no names or notes."""
    try:
        _write_private(C / "spaces.count", str(max(0, int(n))))
    except Exception:
        pass

def has_shared_spaces():
    """True when the last status or sync said the team is in a shared space: the local copy holds only the team's
    private notes, so such a team asks the host. No file or a zero means the local copy answers as before."""
    try:
        return int((C / "spaces.count").read_text().strip() or "0") > 0
    except Exception:
        return False

def is_key_bound_error(res):
    return isinstance(res, dict) and res.get("code") == "key_bound_to_other_bot"

def daemon_call(req, connect_timeout=0.05, timeout=10.0):
    """One JSON line out, one back. None when no daemon answers (the caller falls back). Calls other than ping, stop
    and restart carry this caller's cfg id and its key ("auth"): the team's daemon checks the key with the host itself."""
    if "cfg" not in req and req.get("op") not in ("ping", "stop", "restart"):
        cfg = load_cfg()
        req = dict(req, cfg=cfg_id(cfg), auth=cfg.get("key") or "")
    return _sock_call(C, req, connect_timeout, timeout)

def _sock_call(d, req, connect_timeout=0.05, timeout=10.0):
    """The raw exchange with the daemon of one dir: its unix socket, or its 127.0.0.1 port with the token."""
    d = pathlib.Path(d)
    s = None
    try:
        if os.name != "nt" and hasattr(_socket, "AF_UNIX") and (d / "braind.sock").exists():
            s = _socket.socket(_socket.AF_UNIX, _socket.SOCK_STREAM)
            s.settimeout(connect_timeout)
            s.connect(str(d / "braind.sock"))
        elif (d / "braind.port").exists():
            pd = json.loads((d / "braind.port").read_text())
            s = _socket.create_connection(("127.0.0.1", int(pd["port"])), connect_timeout)
            req = dict(req, token=pd["token"])
        else:
            return None
        s.settimeout(timeout)
        s.sendall((json.dumps(req) + "\n").encode("utf-8"))
        buf = b""
        while b"\n" not in buf:
            chunk = s.recv(65536)
            if not chunk:
                break
            buf += chunk
        return json.loads(buf.split(b"\n", 1)[0].decode("utf-8", "replace")) if buf else None
    except (OSError, ValueError, KeyError):
        return None
    finally:
        if s is not None:
            try:
                s.close()
            except OSError:
                pass

def _is_current(v):
    """A daemon at this client's version or newer is fine: only an older one is replaced."""
    def t(x):
        return tuple(int(i) for i in re.findall(r"\d+", str(x or ""))[:4])
    return t(v) >= t(VERSION)

def _daemon_files_stale():
    """No daemon answers: do its socket, port or pid file say it is gone? A dead pid is stale at once; files with a
    live or unknown pid only after a few seconds (a daemon that is just starting has not answered yet)."""
    files = [f for f in (DAEMON_SOCK, DAEMON_PORT, DAEMON_PID) if f.exists()]
    if not files:
        return False
    pid = _read_pid(C)
    if pid is not None and not _proc_alive(pid):
        return True
    return any(time.time() - f.stat().st_mtime > 3 for f in files if f.exists())

def _stop_daemon_dir(wait=5.0):
    """Stop the daemon of the bound team dir (politely, then by pid) and remove what it leaves behind."""
    if _sock_call(C, {"op": "stop"}, 0.2, 5.0) is not None:
        end = time.time() + wait
        while time.time() < end and _sock_call(C, {"op": "ping"}, 0.1, 1.0) is not None:
            time.sleep(0.1)
    pid = _read_pid(C)
    if pid and pid != os.getpid() and _proc_alive(pid) and _proc_is_brain_daemon(pid):
        _kill_pid(pid)
    for f in (DAEMON_SOCK, DAEMON_PORT, DAEMON_PID):
        _unlink_quiet(f)

def ensure_daemon(cfg, wait=0.0, restart=False, throttle=False):
    """A running daemon of THIS version for the bound team dir: its ping reply, or None (not yet, or not possible).
    No answer with stale socket/pid files: they are removed and a fresh daemon spawned. An older daemon, or restart=True,
    is stopped first. A lock keeps ten bots asking at once from starting more than one. Never raises."""
    try:
        if not local_enabled() or not _BIND["bound"] or not cfg.get("url") or not cfg.get("key"):
            return None
        ensure()
        r = daemon_call({"op": "ping"})
        if r is not None and not restart and _is_current(r.get("version")):
            return r
        lock = _FileLock(C / "braind.start.lock", stale=30)
        if lock.acquire(wait):
            try:
                r = daemon_call({"op": "ping"})
                if r is not None and not restart and _is_current(r.get("version")):
                    return r
                fixed = r is not None or restart or _daemon_files_stale()
                if fixed:
                    _stop_daemon_dir()
                age = time.time() - DAEMON_SPAWN.stat().st_mtime if DAEMON_SPAWN.exists() else 1e9
                if fixed or not throttle or age >= 10:
                    _write_private(DAEMON_SPAWN, str(time.time()))
                    _spawn_detached([str(self_path()), "daemon", "run"])
            finally:
                lock.release()
        end = time.time() + wait
        while time.time() < end:
            time.sleep(0.1)
            r = daemon_call({"op": "ping"})
            if r is not None and _is_current(r.get("version")):
                return r
        return None
    except Exception:
        return None

def autostart_daemon(cfg):
    """Start the daemon detached when none is running (at most one attempt per 10 s). Never raises."""
    ensure_daemon(cfg, throttle=True)

def daemon_notify_update():
    """After `brain update` swapped the file: the daemon restarts itself on the new code (best effort)."""
    try:
        if DAEMON_SOCK.exists() or DAEMON_PORT.exists():
            daemon_call({"op": "restart"})
    except Exception:
        pass

def daemon_main(a):
    sub = a[1] if len(a) > 1 else "status"
    cfg = load_cfg()
    if sub in ("run", "start", "status", "sync", "stop") and cfg["url"] and cfg["key"]:
        activate(cfg)
    if sub == "run":
        if not _BIND["bound"]:
            sys.exit("daemon not started: the host did not confirm which team this key belongs to")
        sys.exit(Daemon().run())
    if sub in ("start", "sync", "status", "stop") and (not cfg["url"] or not cfg["key"]):
        sys.exit(NOT_CONFIGURED)
    if sub == "stop":
        if daemon_call({"op": "ping"}) is None and not _daemon_files_stale():
            print("daemon is not running")
            return
        _stop_daemon_dir()
        print("daemon stopped")
        return
    if sub in ("start", "sync", "status"):
        if not local_enabled():
            sys.exit("local mode is off (BRAIN_LOCAL=0 or no sqlite3)")
        if not _BIND["bound"]:
            sys.exit("the host did not confirm which team this key belongs to (is it reachable?): the local copy stays off, finds use the host")
        was = daemon_call({"op": "ping"})
        if sub == "status" and was is None and not _daemon_files_stale():
            print("daemon is not running")
            print(hyper_state()["text"])
            return
        # stale files, an older daemon or one that cannot serve this key: restart it, then carry on
        r = ensure_daemon(cfg, wait=6.0)
        if r is None:
            sys.exit("daemon did not start; see " + str(DAEMON_LOG))
        probe = daemon_call({"op": "status"}, timeout=30) or {}
        if probe.get("cfg_mismatch"):
            r = ensure_daemon(cfg, wait=6.0, restart=True)
            probe = daemon_call({"op": "status"}, timeout=30) or {}
            if r is None or probe.get("cfg_mismatch"):
                sys.exit("daemon could not be restarted; see " + str(DAEMON_LOG))
        if probe.get("wrong_team"):
            sys.exit("this key is not part of the team this local copy belongs to: finds use the host")
        if sub == "start":
            print("daemon already running (pid %s)" % r.get("pid") if was is not None and _is_current(was.get("version"))
                  else "daemon started (pid %s)" % r.get("pid"))
            return
        if sub == "sync":
            r = daemon_call({"op": "sync"}, timeout=120)
            if r is None:
                sys.exit("sync failed: the daemon did not answer")
            if r.get("error") or r.get("ok") is False:
                why = {"network": "the host could not be reached", "revoked": "the host refused this team's keys",
                       "stopped": "the daemon is stopping"}.get(r.get("error"), r.get("reason") or r.get("error") or "unknown")
                sys.exit("sync failed: " + why)
        else:
            r = probe if probe.get("ok") else (daemon_call({"op": "ping"}) or was or {})
        print("daemon pid %s | %s | engine %s | notes %s | ws %s | outbox %s%s" % (
            r.get("pid"), "ready" if r.get("ready") else "not ready (%s)" % r.get("reason"), r.get("engine"),
            r.get("notes"), "up" if r.get("ws") else "down", r.get("outbox"), " | rebuilding" if r.get("rebuilding") else ""))
        print(hyper_state()["text"])
        return
    sys.exit("usage: brain daemon [start|stop|status|run|sync]")

def embed_main(a):
    """brain embed [status|on|off|install]: the optional local search model."""
    sub = a[1] if len(a) > 1 else "status"
    _cfg = load_cfg()
    if _cfg["url"] and _cfg["key"]:
        activate(_cfg)
    h = embed_home()
    if sub == "off":
        h.mkdir(parents=True, exist_ok=True)
        _write_private(h / "off", "off")
        daemon_call({"op": "restart"})
        print("local search model off: finds use the built-in engine. `brain embed on` turns it back on.")
        return
    if sub == "on":
        _unlink_quiet(h / "off")
        daemon_call({"op": "restart"})
        print("local search model on: the daemon installs it in the background if needed (`brain embed status`).")
        return
    if sub == "install":
        if embed_install(force=True, log=print):
            daemon_call({"op": "restart"})
            return
        sys.exit("not installed: %s" % (embed_state().get("error") or _EMBED_LAST_ERROR or "unknown error"))
    if sub == "status":
        st = embed_state()
        r = daemon_call({"op": "status"}) or {}
        e = r.get("embed") or {}
        print("local search model: %s | installed %s%s | answering %s" % (
            "on" if embed_wanted() else "off", "yes" if embed_installed() else "no",
            (" (%d MB, %.0f s)" % ((st.get("bytes") or 0) / 1e6, st.get("install_s") or 0)) if embed_installed() else
            (" (last error at %s: %s)" % (st.get("step"), st.get("error")) if st.get("error") else ""),
            "yes" if e.get("ready") else "no"))
        return
    sys.exit("usage: brain embed [status|on|off|install]")

_SRC = {"v": None}

def _emit_source(src, show):
    """Which path answered: BRAIN_DEBUG=1 prints it on stderr, --source prints a last line on stdout."""
    if os.environ.get("BRAIN_DEBUG", "").strip() not in ("", "0"):
        print("source: " + src, file=sys.stderr)
    if show:
        print("source: " + src)

def local_find(q, n, bot, cfg):
    """daemon socket -> in-process replica. Returns {lines, src, offline} or None (use the server).
    Exits with the license or revoked message when the daemon says the lease is gone."""
    if not _BIND["bound"]:
        return None  # the host has not said which team this key is in: no local copy, the host answers
    r = daemon_call({"op": "find", "q": q, "n": n, "bot": bot})
    if r is not None:
        if r.get("ok"):
            off = bool(r.get("offline"))
            if not _is_current(r.get("v")):
                ensure_daemon(cfg, restart=True, throttle=True)  # older daemon: replaced for the next call
            return {"lines": r["lines"], "src": "offline-daemon" if off else "daemon", "offline": off}
        if r.get("reason") == "revoked":
            sys.exit(REVOKED_MSG)
        if r.get("reason") == "license_inactive":
            sys.exit(license_inactive_msg())
        if r.get("cfg_mismatch"):
            ensure_daemon(cfg, restart=True)  # an older build that cannot serve this key: replaced, the host answers now
        return None  # daemon is rebuilding or not ready, or refused this key: the host answers
    autostart_daemon(cfg)
    return _replica_find(q, n, bot, offline=False)

def _replica_find(q, n, bot, offline):
    try:
        rep = Replica(C)
        st = rep.peek_stamp()
        if not st or (C / "engine.mismatch").exists():
            return None
        if not offline and (_now_ms() - st["last_ok_ms"]) >= LOCAL_FRESH_S * 1000:
            return None  # stale and the server is reachable: ask the server
        if offline and not lease_valid():
            return None
        if not rep.load():
            return None
        r = rep.find(q, n, bot)
        rep.close()
        return {"lines": r["lines"], "src": "offline-replica" if offline else "replica", "offline": offline,
                "ago_s": max(0, int((_now_ms() - st["last_ok_ms"]) / 1000))}
    except Exception:
        return None

# ---- Hyper speed indicator (docs/package-local.md) ------------------------------------------------------
HYPER_WORDS = {
    "no_copy_yet": "no local copy yet", "rebuilding": "local copy is rebuilding", "stale": "local copy is catching up",
    "lease_expired": "offline too long so the local copy is locked", "serverless": "serverless or short-lived machine",
    "opted_out": "local copy turned off", "no_storage": "this machine cannot store a local copy",
    "no_cryptography": NO_AES_MSG,
    "engine_update": "waiting for a client update", "old_runtime": "Node.js 22.13 or newer is needed for the local copy",
    "host_needed": "this question needs the host", "unknown": "reason unknown",
}
_SERVERLESS_ENV = ("AWS_LAMBDA_FUNCTION_NAME", "LAMBDA_TASK_ROOT", "VERCEL", "NETLIFY", "K_SERVICE", "FUNCTION_TARGET",
                   "FUNCTIONS_WORKER_RUNTIME", "DENO_DEPLOYMENT_ID")

def _hyper_result(mode, reason, last_ok_ms=None, now_ms=None):
    ago = None
    if mode == "local" and last_ok_ms:
        ago = max(0, int(((now_ms if now_ms is not None else _now_ms()) - last_ok_ms) / 1000))
    if mode == "local":
        text = "Hyper speed: on (local copy, synced %ds ago)" % ago if reason == "synced" and ago is not None else "Hyper speed: on (local copy, offline)" if reason == "offline" else "Hyper speed: on (local copy)"
    else:
        text = "Hyper speed: off (using host: %s)" % HYPER_WORDS.get(reason, HYPER_WORDS["unknown"])
    return {"mode": mode, "reason": reason, "synced_ago_s": ago, "text": text}

def hyper_decide(ready, rebuilding, engine_ok, fresh, catching_up, lease_ok, last_ok_ms=None, now_ms=None):
    """The state of the local copy as (mode, reason). fresh: last host contact is recent; catching_up: stale while the
    host looks reachable; lease_ok: the offline lease is still valid."""
    if rebuilding:
        return _hyper_result("host", "rebuilding")
    if not ready:
        return _hyper_result("host", "no_copy_yet")
    if not engine_ok:
        return _hyper_result("host", "engine_update")
    if fresh:
        return _hyper_result("local", "synced", last_ok_ms, now_ms)
    if catching_up:
        return _hyper_result("host", "stale")
    if lease_ok:
        return _hyper_result("local", "offline", last_ok_ms, now_ms)
    return _hyper_result("host", "lease_expired")

def hyper_state(cfg=None):
    """{mode, reason, synced_ago_s, text}: from the daemon when one runs, else from the replica stamp on disk."""
    try:
        env = os.environ
        if env.get("BRAIN_LOCAL", "1").strip().lower() in ("0", "false", "no", "off"):
            return _hyper_result("host", "opted_out")
        if _sqlite3 is None:
            return _hyper_result("host", "no_storage")
        if _AESGCM is None:
            return _hyper_result("host", "no_cryptography")
        if any(env.get(k) for k in _SERVERLESS_ENV):
            return _hyper_result("host", "serverless")
        r = daemon_call({"op": "hyper"})
        if r is not None and r.get("ok") and r.get("mode") in ("local", "host"):
            return _hyper_result(r["mode"], str(r.get("reason") or "unknown"), r.get("last_ok_ms"))
        rep = Replica(C)
        st = rep.peek_stamp()
        if not st:
            return _hyper_result("host", "no_copy_yet")
        age_ok = (_now_ms() - st["last_ok_ms"]) < LOCAL_FRESH_S * 1000
        return hyper_decide(True, False, not (C / "engine.mismatch").exists(), age_ok, lease_valid(), lease_valid(), st["last_ok_ms"])
    except Exception:
        return _hyper_result("host", "unknown")

def _hyper_header_of(s):
    return "%s;%s" % (s["mode"], s["reason"])

def _host_hyper_header():
    """Header value for a one-off CLI process: its current state, worked out once. The daemon sets _HYPER itself."""
    if _QUIET[0]:
        return None
    _HYPER[0] = _hyper_header_of(hyper_state())
    return _HYPER[0]

def _emit_hyper(s, show):
    """After a find: the Hyper speed line, last on stdout with --verbose, otherwise on stderr and only for a terminal."""
    if show:
        print(s["text"])
    elif sys.stderr.isatty():
        print(s["text"], file=sys.stderr)

# ======================================================================================================
# END LOCAL REPLICA AND DAEMON
# ======================================================================================================

NOT_CONFIGURED = ("not configured: set BRAIN_URL and BRAIN_KEY, or save {\"url\": ..., \"key\": ...} in "
                  + str(cfg_path()) + " (the installer writes it when both are exported)")

def _record_find(q):
    ensure()
    try:
        cur = json.loads(REC.read_text()) if REC.exists() else []
    except Exception:
        cur = []
    cur.append({"t": time.time(), "q": q})
    _write_private(REC, json.dumps(cur[-50:]))

def _local_hyper(loc):
    """Hyper speed of a find the local copy answered (lines already printed)."""
    if loc["offline"]:
        return _hyper_result("local", "offline")
    ago = loc.get("ago_s")
    return _hyper_result("local", "synced", _now_ms() - int(ago) * 1000 if ago is not None else _now_ms())

def _host_find_hyper():
    """A host find: the reason the local copy did not answer (host_needed when it looks fine but did not answer)."""
    s = hyper_state()
    return s if s["mode"] == "host" else _hyper_result("host", "host_needed")

def find(q, n, bot, show_source=False, verbose=False):
    cfg = load_cfg()
    if not cfg["url"] or not cfg["key"]:
        sys.exit(NOT_CONFIGURED)
    activate(cfg)
    # A team in a shared space asks the host: the local copy holds only the team's private notes.
    if local_enabled() and q.strip() and not has_shared_spaces():
        loc = local_find(q.strip(), n, bot, cfg)
        if loc is not None:
            print("\n".join(loc["lines"]))
            if loc["offline"]:
                print("(offline, local copy)", file=sys.stderr)
            _emit_source(loc["src"], show_source)
            if verbose or sys.stderr.isatty():
                _emit_hyper(_local_hyper(loc), verbose)
            _record_find(q)
            return not loc["offline"]
    hh = _host_find_hyper()
    _HYPER[0] = _hyper_header_of(hh)
    le = load_lease()
    sk = _swr_key(q, n, bot)
    body = {"q": q, "n": n, "format": "json", "lease": True}
    if bot:
        body["bot"] = bot
    # Server-first: never serve local cache while online (suspension must take effect immediately).
    # Encrypted lease cache is ONLY for brief offline use while lease still valid.
    try:
        st, res = api("POST", "/v1/find", cfg, body)
    except Exception as e:
        le = load_lease()
        if local_enabled() and q.strip() and lease_valid(le):
            loc = _replica_find(q.strip(), n, bot, offline=True)
            if loc is not None:
                print("\n".join(loc["lines"]))
                print("(offline, local copy)", file=sys.stderr)
                _emit_source(loc["src"], show_source)
                if verbose or sys.stderr.isatty():
                    _emit_hyper(_local_hyper(loc), verbose)
                return
        if le and lease_valid(le) and le.get("lease_key"):
            hit = swr_get_encrypted(sk, le["lease_key"])
            if hit:
                print(hit["text"])
                print("(offline lease cache)", file=sys.stderr)
                _emit_source("offline-cache", show_source)
                if verbose or sys.stderr.isatty():
                    _emit_hyper(_host_find_hyper(), verbose)
                return
        sys.exit(license_inactive_msg(le) if (not le or not lease_valid(le)) else f"offline and no cached hit: {e}")
    if st == 401:
        key_refused(cfg, 401, res)  # only this key is dropped; the team's copy stays while another key of it is known
        sys.exit(REVOKED_MSG)
    if st == 403:
        err = res.get("error") if isinstance(res, dict) else str(res)
        renew = (res.get("renew_url") if isinstance(res, dict) else None) or (le or {}).get("renew_url") or renew_default()
        key_refused(cfg, 403, res, renew)  # team inactive: lease and local copy go; a key bound to another bot: nothing wiped
        sys.exit(err if err else f"license inactive, renew at {renew}")
    if st != 200:
        sys.exit(f"find failed ({st}): {res}")
    if isinstance(res, dict) and res.get("lease"):
        save_lease(res["lease"])
        le = load_lease()
    lines = res.get("lines", []) if isinstance(res, dict) else []
    items = res.get("items") if isinstance(res, dict) else None
    if isinstance(items, list):
        # Shared spaces: every line says where it came from. The last server line is the timing line.
        lines = [str(it.get("line", "")) + " [" + str(it.get("space_name") or "your team") + "]" for it in items if isinstance(it, dict)] + lines[-1:]
    if isinstance(res, dict) and isinstance(items, list) != has_shared_spaces():
        note_shared_spaces(1 if isinstance(items, list) else 0)
    text_out = "\n".join(lines) if isinstance(res, dict) else str(res)
    if le and le.get("lease_key"):
        swr_put_encrypted(sk, text_out, le["lease_key"])
    # also drop any old plaintext SWR (no read-only fallback)
    if SWR.exists():
        try:
            SWR.unlink()
        except Exception:
            pass
    print(text_out)
    _emit_source("server", show_source)
    if verbose or sys.stderr.isatty():
        _emit_hyper(hh, verbose)
    _record_find(q)
    if local_enabled():
        autostart_daemon(cfg)
    return True


def new_cid():
    """Client note id: the host stores a note once per id, so a resend (outbox replay, retry after a lost reply) never
    makes a second copy."""
    return secrets.token_urlsafe(16)

def line_cid(row, line):
    """The id an outbox line is sent with. Older lines carry none: a hash of the line keeps their replays single too."""
    c = row.get("cid") if isinstance(row, dict) else None
    if isinstance(c, str) and re.fullmatch(r"[A-Za-z0-9_-]{8,64}", c):
        return c
    return "ob-" + hashlib.sha256(line.encode("utf-8")).hexdigest()[:40]

def _add_request(cfg, bot, s, cid=None, space=None, private=False):
    """POST /v1/add through the daemon when one runs (it also puts the stored note into its replica), else direct.
    Raises on a network failure, like api(). A direct 201 puts the reply's note into replica.db.
    A shared-space add goes straight to the host and never into the local copy, which holds private notes only.
    A plain add may still be routed to a space by the owner's rules; the reply says so and the note is not copied locally."""
    cid = cid or new_cid()
    if space:
        return api("POST", "/v1/add", cfg, {"bot": bot, "text": s, "cid": cid, "space": space})
    local = local_enabled() and _BIND["bound"]
    if local:
        r = daemon_call({"op": "add", "bot": bot, "text": s, "cid": cid, **({"private": True} if private else {})}, timeout=40)
        if r is not None and r.get("ok"):
            return r["status"], r["res"]
        if r is not None and r.get("net"):
            raise RuntimeError("could not reach the server")
        if r is None:
            autostart_daemon(cfg)
        elif r.get("cfg_mismatch"):
            ensure_daemon(cfg, restart=True)  # an older build that cannot serve this key
        # any other refusal (wrong team, unverified, revoked): this bot posts with its own key below
    st, res = api("POST", "/v1/add", cfg, {"bot": bot, "text": s, "cid": cid, **({"private": True} if private else {})})
    if local and st == 201 and isinstance(res, dict) and res.get("note") and not res.get("space_id"):
        ing = daemon_call({"op": "ingest", "note": res["note"]})
        if ing is None:
            replica_put_direct(res["note"])
    return st, res

def add(bot, s, space=None, private=False):
    cfg = load_cfg()
    if cfg.get("url") and cfg.get("key"):
        activate(cfg)
    le = load_lease()
    if le and not lease_valid(le) and cfg.get("url") and cfg.get("key"):
        # still try server; on 403 exit inactive
        pass
    cid = new_cid()
    if not cfg["url"] or not cfg["key"]:
        _outbox_append(bot, s, cid, space, private, None)
        print("not configured: saved to the outbox only. " + NOT_CONFIGURED + ". Then run `brain outbox --push`.")
        return
    try:
        st, res = _add_request(cfg, bot, s, cid, space, private)
        if st == 401:
            key_refused(cfg, 401, res)
            sys.exit(REVOKED_MSG)
        if st == 403:
            renew = (res.get("renew_url") if isinstance(res, dict) else None) or (le or {}).get("renew_url") or renew_default()
            err = res.get("error") if isinstance(res, dict) else ""
            key_refused(cfg, 403, res, renew)
            sys.exit(err if err else f"license inactive, renew at {renew}")
        if st in (200, 201) and isinstance(res, dict) and res.get("ok"):
            where = res.get("space_name") or (space if space and not private else None)
            print(f"added: {res.get('ts')} | {bot} | {s}" + (f" [{where}]" if where else ""))
            if res.get("space_name"):
                print(f"saved to {res['space_name']}")
            elif res.get("routed") == "private":
                print("saved to your team")
            if res.get("uid"):
                print(f"uid: {res['uid']}  (remove it with: brain delete {res['uid']})")
            # refresh lease
            try:
                st2, lev = api("POST", "/v1/lease", cfg, {"bot": bot})
                if st2 == 200 and isinstance(lev, dict) and lev.get("lease"):
                    save_lease(lev["lease"])
            except Exception:
                pass
            try:
                if ENC_SWR.exists():
                    ENC_SWR.unlink()
            except Exception:
                pass
            return True
        if isinstance(res, dict) and res.get("error"):
            err = str(res["error"])
            sys.exit(err if err.startswith("refused") else "not saved: " + err)
        raise RuntimeError(f"{st} {res}")
    except SystemExit:
        raise
    except Exception as e:
        if le and not lease_valid(le):
            sys.exit(license_inactive_msg(le))
        _outbox_append(bot, s, cid, space, private, cfg)  # same id: if the first try did reach the host, the replay is not stored twice
        print(f"write failed ({e}); saved to outbox. Run `brain outbox --push` later.")

def delete_note(uid):
    """Remove one note by uid. Prints 'deleted: <uid>'. Errors never include the key."""
    cfg = load_cfg()
    if not cfg["url"] or not cfg["key"]:
        sys.exit(NOT_CONFIGURED)
    activate(cfg)
    try:
        st, res = api("POST", "/v1/delete", cfg, {"uid": uid})
    except Exception as e:
        sys.exit(f"delete failed: could not reach the server ({type(e).__name__})")
    if st == 401:
        key_refused(cfg, 401, res)
        sys.exit(REVOKED_MSG)
    if st == 403:
        err = res.get("error") if isinstance(res, dict) else ""
        key_refused(cfg, 403, res)
        sys.exit(err if err else f"license inactive, renew at {renew_default()}")
    if st == 200 and isinstance(res, dict) and res.get("ok"):
        print(f"deleted: {uid}")
        if local_enabled() and not daemon_call({"op": "forget", "uid": uid}):
            replica_forget_direct(uid)
        try:
            if ENC_SWR.exists():
                ENC_SWR.unlink()  # earlier lookups may still show the removed note
        except Exception:
            pass
        return True
    if st == 200:
        sys.exit(f"delete failed: no note with uid {uid}")
    sys.exit(f"delete failed ({st}): {res.get('error') if isinstance(res, dict) and res.get('error') else 'unexpected reply'}")

def _outbox_append(bot, s, cid=None, space=None, private=False, cfg=None):
    """Append one line and fsync it. Held briefly against a rewrite by the daemon's push; never skipped."""
    ensure()
    lock = _FileLock(C / "outbox.lock")
    lock.acquire(2.0)
    try:
        fd = os.open(str(OUT), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        with os.fdopen(fd, "a") as f:
            row = {"bot": bot, "text": s, "t": time.time(), "cid": cid or new_cid()}
            if cfg and cfg.get("key"):
                row["cfg"] = cfg_id(cfg)  # the key that wrote it: only that key's push sends this line
            if space:
                row["space"] = space
            if private:
                row["private"] = True
            f.write(json.dumps(row) + chr(10))
            f.flush()
            os.fsync(f.fileno())
    finally:
        lock.release()


REJECTED = C / "outbox-rejected.jsonl"

def _legacy_outbox(tenant):
    """The pre-2.2.6 outbox in the cache root (lines carry no key id), when it was written for this team."""
    root = cache_dir()
    if C == root or not tenant or not (root / "outbox.jsonl").exists():
        return None
    try:
        return root if (root / "outbox.team").read_text().strip() == tenant else None
    except OSError:
        return None

def _push_file(path, rej, cfg, claim_unkeyed):
    """Push the lines of one outbox file that this key may send: its own (cfg id equal), and lines with no key id only
    when claim_unkeyed (a file known to be this team's, pushed on the user's explicit request). Other keys' lines stay.
    Returns (sent, kept, rejected)."""
    me = cfg_id(cfg)
    lines = _outbox_read(path)
    kept, sent_lines, rejected = 0, [], []
    for i, line in enumerate(lines):
        try:
            row = json.loads(line)
        except Exception:
            rejected.append((line, "unreadable line"))
            continue
        lc = row.get("cfg") if isinstance(row, dict) else None
        if lc != me and not (lc is None and claim_unkeyed):
            kept += 1  # written by another bot's key (or unkeyed): never pushed with this key
            continue
        try:
            payload = {"bot": row["bot"], "text": row["text"], "cid": line_cid(row, line)}
            if row.get("space"):
                payload["space"] = row["space"]
            if row.get("private"):
                payload["private"] = True
            st, res = api("POST", "/v1/add", cfg, payload)
        except Exception:
            kept += 1
            continue
        if st in (200, 201) and isinstance(res, dict) and res.get("ok"):
            sent_lines.append(line)
        elif st == 401:
            _outbox_remove(path, sent_lines)
            key_refused(cfg, 401, res)
            sys.exit(REVOKED_MSG + f" {len(lines) - len(sent_lines)} line(s) stay in the outbox.")
        elif st == 403 and not is_key_bound_error(res):
            _outbox_remove(path, sent_lines)
            key_refused(cfg, 403, res)
            sys.exit((res.get("error") if isinstance(res, dict) else "") or "license inactive")
        elif st == 400:
            rejected.append((line, (res.get("error") if isinstance(res, dict) else str(res)) or "refused"))
        else:
            kept += 1
    _outbox_remove(path, sent_lines + [l for l, _ in rejected])
    if rejected:
        ensure()
        fd = os.open(str(rej), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        with os.fdopen(fd, "a") as f:
            for line, why in rejected:
                f.write(json.dumps({"line": line, "reason": why, "t": time.time()}) + chr(10))
    return len(sent_lines), kept, rejected

def push_outbox(legacy=False):
    """Send waiting lines with THIS bot's key. Each line goes only with the key that wrote it; lines of other bots stay
    for them. A line the server refuses for good (400, for example it looks like a secret) moves to
    outbox-rejected.jsonl with the reason. A refused key stops the push. legacy=True (brain outbox --push) also sends the
    older unkeyed lines of this team, after a warning."""
    cfg = load_cfg()
    if not cfg.get("url") or not cfg.get("key"):
        sys.exit(NOT_CONFIGURED)
    activate(cfg)
    old = _legacy_outbox(_BIND["tenant"]) if legacy else None
    if not _outbox_read(OUT) and not (old and _outbox_read(old / "outbox.jsonl")):
        print("(outbox empty)")
        return
    plock = _FileLock(C / "outbox.push.lock", stale=120)
    if not plock.acquire(5.0):
        print("another push is already running; try again in a moment")
        return
    try:
        sent, kept, rejected = _push_file(OUT, REJECTED, cfg, False)
        if old:
            if _outbox_read(old / "outbox.jsonl"):
                print("warning: sending older outbox lines from before this update with this bot's key (they have no key id)")
            s2, k2, r2 = _push_file(old / "outbox.jsonl", old / "outbox-rejected.jsonl", cfg, True)
            sent, kept, rejected = sent + s2, kept + k2, rejected + r2
    finally:
        plock.release()
    msg = f"pushed {sent}; {kept} line(s) still waiting"
    if rejected:
        msg += f"; {len(rejected)} refused by the server and moved to {REJECTED} ({rejected[0][1]})"
    print(msg)

def main(a):
    if not a or a[0] in ("-h", "--help"):
        print(__doc__)
        return
    if a[0] in ("--version", "version"):
        print(f"{PRODUCT} client {VERSION}")
        return
    ok = False  # set when a server call succeeded; then the daily background update check may run
    if a[0] == "find":
        n, bot = 5, None
        if "-n" in a:
            i = a.index("-n"); n = int(a[i + 1]); del a[i : i + 2]
        if "--bot" in a:
            i = a.index("--bot"); bot = a[i + 1]; del a[i : i + 2]
        show = "--source" in a
        if show:
            a.remove("--source")
        verbose = "--verbose" in a
        if verbose:
            a.remove("--verbose")
        ok = bool(find(" ".join(a[1:]), n, bot, show, verbose))
    elif a[0] == "daemon":
        daemon_main(a)
    elif a[0] == "embed":
        embed_main(a)
    elif a[0] == "ws":
        cfg = load_cfg()
        if not cfg["url"] or not cfg["key"]:
            sys.exit(NOT_CONFIGURED)
        path = "/v1/ws" + (f"?bot={a[1]}" if len(a) > 1 else "")
        activate(cfg)
        st, res = api("GET", path, cfg)
        if st == 401:
            key_refused(cfg, 401, res)
            sys.exit(REVOKED_MSG)
        print(res if st == 200 else f"error {st}: {res}")
        ok = st == 200
    elif a[0] == "add":
        space = None
        if "--space" in a:
            i = a.index("--space")
            if i + 1 >= len(a) or not a[i + 1].strip():
                sys.exit('usage: brain add <bot> --space <id-or-name> "<ID> | <fact> | <source>"')
            space = a[i + 1].strip()
            del a[i : i + 2]
        private = "--private" in a
        if private:
            a.remove("--private")
            if space:
                sys.exit("use either --space or --private, not both")
        if len(a) < 3:
            sys.exit('usage: brain add <bot> "<ID> | <fact> | <source>"  (one shared space: --space <id-or-name>, only private: --private)')
        ok = bool(add(a[1], " ".join(a[2:]), space, private))
    elif a[0] == "delete":
        if len(a) != 2 or not a[1].strip():
            sys.exit("usage: brain delete <uid>")
        ok = bool(delete_note(a[1].strip()))
    elif a[0] == "outbox":
        _c = load_cfg()
        if _c["url"] and _c["key"]:
            activate(_c)
        if "--push" in a:
            push_outbox(legacy=True)
        else:
            print(OUT.read_text() if OUT.exists() and OUT.read_text().strip() else "(outbox empty)")
            _old = _legacy_outbox(_BIND["tenant"])
            if _old and _outbox_read(_old / "outbox.jsonl"):
                print("(older lines from before this update wait in %s: `brain outbox --push` sends them with this bot's key)" % (_old / "outbox.jsonl"))
    elif a[0] == "status":
        cfg = load_cfg()
        if not cfg["url"] or not cfg["key"]:
            print(f"{PRODUCT} client {VERSION} | {NOT_CONFIGURED}")
            return
        activate(cfg)
        ensure_daemon(cfg, wait=3.0)  # a stale, older or legacy daemon is replaced here too
        try:
            st, res = api("GET", "/v1/status", cfg)
        except Exception as e:
            print(f"{PRODUCT} client {VERSION} | offline ({e}); finds use the offline cache while the lease is valid")
            print(hyper_state(cfg)["text"])
            return
        if st == 401:
            key_refused(cfg, 401, res)
            print(f"{PRODUCT} client {VERSION} | {REVOKED_MSG}")
            sys.exit(1)
        if st == 200 and isinstance(res, dict):
            team = res.get("tenant_id")
            if not isinstance(team, str) or not team.strip():
                print(f"{PRODUCT} client {VERSION} | server error: the reply had no team id")
                sys.exit(1)
            if isinstance(res.get("shared_spaces"), list):
                note_shared_spaces(len(res["shared_spaces"]))
            print(f"{PRODUCT} client {VERSION} | connected to {cfg['url']} | team {team} | notes {res.get('notes')}")
            print(hyper_state(cfg)["text"])
        else:
            print(f"{PRODUCT} client {VERSION} | server error {st}: {res}")
        ok = st == 200
        # flush outbox opportunistically
        if ok and _outbox_read(OUT):
            push_outbox()
    elif a[0] == "selftest":
        cfg = load_cfg()
        ok, reason = run_selftest(cfg)
        print("PASS" if ok else f"FAIL: {reason}")
        sys.exit(0 if ok else 1)
    elif a[0] == "update":
        auto = "--auto" in a
        check_update(force=auto or "--force" in a, auto=auto)
    elif a[0] == "rollback":
        rollback("manual")
    else:
        print(__doc__)
    if ok:
        maybe_auto_update(load_cfg())

